import type {
  ObservationPolicyResult,
  ObservationPolicyState,
  ObservationProfile,
  ObservationState,
  Vec2,
  VisionConfig,
} from './types'

const FLOAT_TOLERANCE = 1e-10

export const DEFAULT_VISION_CONFIG: VisionConfig = {
  fovDeg: 65,
  range: 12,
  exitGraceMs: 100,
}

export const INITIAL_OBSERVATION_STATE: ObservationState = {
  status: 'unobserved',
  invisibleSinceMs: null,
}

export const INITIAL_OBSERVATION_POLICY_STATE: ObservationPolicyState = {
  status: 'unobserved',
  invisibleSinceMs: null,
  visibleSinceMs: null,
  broken: false,
  hiddenSinceMs: null,
}

function isFiniteVec2(value: Vec2): boolean {
  return Number.isFinite(value.x) && Number.isFinite(value.z)
}

function assertVisionConfig(config: VisionConfig): void {
  if (
    !Number.isFinite(config.fovDeg) ||
    config.fovDeg < 0 ||
    config.fovDeg > 360
  ) {
    throw new RangeError('fovDeg must be between 0 and 360')
  }
  if (!Number.isFinite(config.range) || config.range < 0) {
    throw new RangeError('range must be a non-negative finite number')
  }
  if (!Number.isFinite(config.exitGraceMs) || config.exitGraceMs < 0) {
    throw new RangeError('exitGraceMs must be a non-negative finite number')
  }
}

function assertObservationProfile(profile: ObservationProfile): void {
  if (profile.mode !== 'break-after') return

  if (
    !Number.isFinite(profile.breakAfterMs) ||
    (profile.breakAfterMs ?? 0) <= 0
  ) {
    throw new RangeError(
      'breakAfterMs must be a positive finite number for break-after',
    )
  }
  if (
    !Number.isFinite(profile.rearmHiddenMs) ||
    (profile.rearmHiddenMs ?? -1) < 0
  ) {
    throw new RangeError(
      'rearmHiddenMs must be a non-negative finite number for break-after',
    )
  }
}

function observationResult(
  state: ObservationPolicyState,
  frozen: boolean,
  justBroke = false,
  breakProgress = 0,
): ObservationPolicyResult {
  return {
    state,
    frozen,
    justBroke,
    breakProgress: Math.max(0, Math.min(1, breakProgress)),
  }
}

/**
 * Tests only distance and facing angle. Static-world occlusion must be queried by
 * the caller and combined with this result before calling updateObservation.
 */
export function isVisionCandidate(
  observer: Vec2,
  facing: Vec2,
  target: Vec2,
  config: VisionConfig = DEFAULT_VISION_CONFIG,
): boolean {
  assertVisionConfig(config)

  if (
    !isFiniteVec2(observer) ||
    !isFiniteVec2(facing) ||
    !isFiniteVec2(target)
  ) {
    return false
  }

  const toTargetX = target.x - observer.x
  const toTargetZ = target.z - observer.z
  const distanceSquared = toTargetX * toTargetX + toTargetZ * toTargetZ
  const rangeSquared = config.range * config.range

  if (distanceSquared > rangeSquared + FLOAT_TOLERANCE) {
    return false
  }

  if (distanceSquared <= FLOAT_TOLERANCE) {
    return true
  }

  const facingLength = Math.hypot(facing.x, facing.z)
  if (facingLength <= FLOAT_TOLERANCE) {
    return false
  }

  if (config.fovDeg >= 360) {
    return true
  }

  const targetLength = Math.sqrt(distanceSquared)
  const normalizedDot =
    (facing.x * toTargetX + facing.z * toTargetZ) /
    (facingLength * targetLength)
  const halfAngleRadians = (config.fovDeg * Math.PI) / 360
  const minimumDot = Math.cos(halfAngleRadians)

  return normalizedDot + FLOAT_TOLERANCE >= minimumDot
}

/**
 * Applies exit hysteresis to a direct-vision signal. Entry is immediate; after
 * vision is lost, the enemy stays observed until exitGraceMs has elapsed.
 */
export function updateObservation(
  previous: ObservationState,
  directlyVisible: boolean,
  nowMs: number,
  config: VisionConfig = DEFAULT_VISION_CONFIG,
): ObservationState {
  assertVisionConfig(config)
  if (!Number.isFinite(nowMs)) {
    throw new RangeError('nowMs must be finite')
  }

  if (directlyVisible) {
    return { status: 'observed', invisibleSinceMs: null }
  }

  if (previous.status === 'unobserved') {
    return INITIAL_OBSERVATION_STATE
  }

  const lostAt =
    previous.invisibleSinceMs === null || nowMs < previous.invisibleSinceMs
      ? nowMs
      : previous.invisibleSinceMs

  if (nowMs - lostAt < config.exitGraceMs) {
    return { status: 'observed', invisibleSinceMs: lostAt }
  }

  return INITIAL_OBSERVATION_STATE
}

/**
 * Reduces one direct-vision sample into an archetype observation policy.
 *
 * `freeze` preserves the original gaze behavior, `inverse-freeze` moves only
 * while visible, `immune` never pauses the enemy, and `break-after` can escape
 * a continuous gaze until it has remained fully outside vision long enough to
 * re-arm. The vision config's exit grace deliberately preserves the visible
 * timer through sub-100 ms sight jitter.
 */
export function updateObservationPolicy(
  previous: ObservationPolicyState,
  directlyVisible: boolean,
  nowMs: number,
  profile: ObservationProfile,
  config: VisionConfig = DEFAULT_VISION_CONFIG,
): ObservationPolicyResult {
  assertVisionConfig(config)
  assertObservationProfile(profile)
  if (!Number.isFinite(nowMs)) {
    throw new RangeError('nowMs must be finite')
  }

  if (profile.mode === 'immune') {
    return observationResult(
      {
        status: directlyVisible ? 'observed' : 'unobserved',
        invisibleSinceMs: directlyVisible ? null : nowMs,
        visibleSinceMs: directlyVisible ? nowMs : null,
        broken: false,
        hiddenSinceMs: directlyVisible ? null : nowMs,
      },
      false,
    )
  }

  if (profile.mode === 'inverse-freeze') {
    const visibility = updateObservation(
      {
        status: previous.status,
        invisibleSinceMs: previous.invisibleSinceMs,
      },
      directlyVisible,
      nowMs,
      config,
    )
    const consideredVisible = visibility.status === 'observed'
    const visibleSinceMs = consideredVisible
      ? previous.visibleSinceMs === null || nowMs < previous.visibleSinceMs
        ? nowMs
        : previous.visibleSinceMs
      : null
    return observationResult(
      {
        status: visibility.status,
        invisibleSinceMs: visibility.invisibleSinceMs,
        visibleSinceMs,
        broken: false,
        hiddenSinceMs: directlyVisible ? null : nowMs,
      },
      !consideredVisible,
    )
  }

  if (profile.mode === 'freeze') {
    const legacy = updateObservation(
      {
        status: previous.status,
        invisibleSinceMs: previous.invisibleSinceMs,
      },
      directlyVisible,
      nowMs,
      config,
    )
    const stayedObserved = legacy.status === 'observed'
    const visibleSinceMs = stayedObserved
      ? previous.visibleSinceMs === null || nowMs < previous.visibleSinceMs
        ? nowMs
        : previous.visibleSinceMs
      : null
    return observationResult(
      {
        status: legacy.status,
        invisibleSinceMs: legacy.invisibleSinceMs,
        visibleSinceMs,
        broken: false,
        hiddenSinceMs: directlyVisible ? null : nowMs,
      },
      stayedObserved,
    )
  }

  const breakAfterMs = profile.breakAfterMs as number
  const rearmHiddenMs = profile.rearmHiddenMs as number

  if (previous.broken) {
    if (directlyVisible) {
      return observationResult(
        {
          status: 'observed',
          invisibleSinceMs: null,
          visibleSinceMs: previous.visibleSinceMs,
          broken: true,
          hiddenSinceMs: null,
        },
        false,
        false,
        1,
      )
    }

    const hiddenSinceMs =
      previous.hiddenSinceMs === null || nowMs < previous.hiddenSinceMs
        ? nowMs
        : previous.hiddenSinceMs
    if (nowMs - hiddenSinceMs >= rearmHiddenMs) {
      return observationResult(INITIAL_OBSERVATION_POLICY_STATE, false)
    }

    return observationResult(
      {
        status: 'unobserved',
        invisibleSinceMs: hiddenSinceMs,
        visibleSinceMs: previous.visibleSinceMs,
        broken: true,
        hiddenSinceMs,
      },
      false,
      false,
      1,
    )
  }

  if (directlyVisible) {
    const visibleSinceMs =
      previous.status === 'observed' &&
      previous.visibleSinceMs !== null &&
      nowMs >= previous.visibleSinceMs
        ? previous.visibleSinceMs
        : nowMs
    const breakProgress = (nowMs - visibleSinceMs) / breakAfterMs
    if (breakProgress >= 1) {
      return observationResult(
        {
          status: 'observed',
          invisibleSinceMs: null,
          visibleSinceMs,
          broken: true,
          hiddenSinceMs: null,
        },
        false,
        true,
        1,
      )
    }

    return observationResult(
      {
        status: 'observed',
        invisibleSinceMs: null,
        visibleSinceMs,
        broken: false,
        hiddenSinceMs: null,
      },
      true,
      false,
      breakProgress,
    )
  }

  if (previous.status === 'unobserved') {
    return observationResult(INITIAL_OBSERVATION_POLICY_STATE, false)
  }

  const invisibleSinceMs =
    previous.invisibleSinceMs === null || nowMs < previous.invisibleSinceMs
      ? nowMs
      : previous.invisibleSinceMs
  if (nowMs - invisibleSinceMs < config.exitGraceMs) {
    const visibleSinceMs = previous.visibleSinceMs ?? nowMs
    const breakProgress = (nowMs - visibleSinceMs) / breakAfterMs
    // Exit grace deliberately keeps the gaze alive through sight jitter, so a
    // threshold crossed inside the window is a real break. Reporting it here
    // rather than at re-acquisition stops the progress from being discarded
    // when the grace expires. Hidden time is measured from the actual sight
    // loss so the re-arm countdown is not restarted by the break itself.
    if (breakProgress >= 1) {
      return observationResult(
        {
          status: 'unobserved',
          invisibleSinceMs,
          visibleSinceMs,
          broken: true,
          hiddenSinceMs: invisibleSinceMs,
        },
        false,
        true,
        1,
      )
    }
    return observationResult(
      {
        status: 'observed',
        invisibleSinceMs,
        visibleSinceMs,
        broken: false,
        hiddenSinceMs: invisibleSinceMs,
      },
      true,
      false,
      breakProgress,
    )
  }

  return observationResult(INITIAL_OBSERVATION_POLICY_STATE, false)
}
