import { Color, type ColorRepresentation } from 'three'

/**
 * Selective bloom treats toneMapped=false as an explicit light-source opt-in.
 * Both player and enemy projectiles share this contract.
 */
export const PROJECTILE_BLOOM_TONE_MAPPED = false
/** HDR headroom gives the bloom pass light to spread beyond the projectile. */
export const PROJECTILE_BLOOM_COLOR_MULTIPLIER = 2.8

export function getProjectileBloomColor(color: ColorRepresentation): Color {
  return new Color(color).multiplyScalar(PROJECTILE_BLOOM_COLOR_MULTIPLIER)
}

export function getSimpleProjectileDimensions(
  projectileRadius = 0.16,
): readonly [number, number, number] {
  const radius = Number.isFinite(projectileRadius)
    ? Math.max(0.01, projectileRadius)
    : 0.16
  const width = Math.max(0.1, radius * 0.65)
  return [width, width, Math.max(0.3, radius * 2)]
}
