import { useFrame } from '@react-three/fiber'
import { useEffect, useRef } from 'react'
import {
  BackSide,
  BoxGeometry,
  Group,
  Mesh,
  MeshBasicMaterial,
  MeshToonMaterial,
  OctahedronGeometry,
  SphereGeometry,
  TorusGeometry,
} from 'three'

import type { CombatantArchetypeId } from '../game'
import type { CharacterMotionRef } from './AssetModels'
import { getPerformanceFactor } from './frameBudget'
import { applyHitstop } from './hitstop'
import { TOON_PALETTE, toonGradientMap } from './toonMaterials'

/**
 * Hostiles are machines now.
 *
 * They used to be rigged humanoids: eight skinned GLBs, a shared animation
 * bank, and a `CharacterAnimator` with its own `AnimationMixer` per body. That
 * is a fine budget for the ten enemies the old walled rooms held, and a bad one
 * for the fifty-six the survivor spawner can put on screen — skinning cost is paid
 * on the CPU every frame, per body, and the GLB path also renders an outline
 * shell, so every hostile was two draw calls of skinned geometry.
 *
 * A drone needs none of it. No skeleton, no mixer, no clips: motion is a sine
 * bob, a spinning ring, and a tilt, which is arithmetic on three transforms.
 * Every geometry and material below is a module-level singleton, so putting
 * forty of these on screen allocates nothing and uploads nothing new.
 *
 * The player stays human on purpose. The read the game wants is one person
 * against a machine swarm, and that only works if the silhouettes disagree.
 */

// ---------------------------------------------------------------------------
// Shared GPU resources. Created once for the module's lifetime and never
// disposed — they live as long as the scene does, and every drone points at
// these exact instances.
// ---------------------------------------------------------------------------
/*
 * Shapes are chosen for the camera the game actually uses: a high, near
 * top-down rig. What the player sees of a hostile is mostly its *top*, so the
 * read has to come from the plan view — a bright hull plate, a glowing halo
 * wider than the body, and a lens. A first pass built these as a dark
 * octahedron inside an inverted-hull outline, which from above collapsed into
 * an unreadable dark wedge on a near-white deck.
 */
const HULL_GEOMETRY = new OctahedronGeometry(0.34, 0)
const PLATE_GEOMETRY = new BoxGeometry(0.46, 0.09, 0.46)
/** The halo. Wider than the hull so it stays visible from directly above. */
const RING_GEOMETRY = new TorusGeometry(0.52, 0.055, 6, 20)
const EYE_GEOMETRY = new SphereGeometry(0.11, 10, 8)
const THRUSTER_GEOMETRY = new SphereGeometry(0.12, 8, 6)
const RIM_GEOMETRY = new OctahedronGeometry(0.34, 0)

/**
 * A tight inverted-hull rim, not a silhouette blob. One draw for edge
 * separation; at 1.07 it reads as a drawn outline rather than swallowing the
 * body the way the 1.16 shell did.
 */
const RIM_MATERIAL = new MeshBasicMaterial({
  color: TOON_PALETTE.ink,
  side: BackSide,
})

function toonMaterial(color: string): MeshToonMaterial {
  return new MeshToonMaterial({ color, gradientMap: toonGradientMap })
}

/**
 * Chassis tones sit light. The deck is near-white, and a dark body on it has
 * plenty of contrast but no *form* — toon shading needs a mid-to-light base
 * before its bands are visible at all.
 */
const HULL_MATERIAL = toonMaterial('#aebabc')
const HULL_HELD_MATERIAL = toonMaterial('#e2f7f4')
const CORE_MATERIAL = toonMaterial('#7d8c90')
const CORE_HELD_MATERIAL = toonMaterial('#b8e6e1')

/**
 * Emissive parts are unlit and excluded from tone mapping so the bloom pass
 * actually catches them — this is the only channel that reports enemy state,
 * so it has to survive whatever the grade does to the rest of the frame.
 */
function glowMaterial(color: string): MeshBasicMaterial {
  return new MeshBasicMaterial({ color, toneMapped: false })
}
const EYE_HOSTILE_MATERIAL = glowMaterial(TOON_PALETTE.hostileLight)
const EYE_HELD_MATERIAL = glowMaterial(TOON_PALETTE.cyanLight)
const EYE_FLASH_MATERIAL = glowMaterial('#ffffff')
const RING_HOSTILE_MATERIAL = glowMaterial(TOON_PALETTE.hostile)
const RING_HELD_MATERIAL = glowMaterial(TOON_PALETTE.cyanLight)

/** FNV-1a over the id. Only needs to be stable and look unstructured. */
function hashPhase(value: string): number {
  let hash = 2166136261
  for (let index = 0; index < value.length; index += 1) {
    hash ^= value.charCodeAt(index)
    hash = Math.imul(hash, 16777619)
  }
  return hash >>> 0
}

interface DroneShape {
  /** Overall size multiplier. */
  readonly scale: number
  /** Hover height above the deck. */
  readonly hover: number
  /** Ring spin rate, rad/s. */
  readonly spin: number
  /** How far the chassis bobs. */
  readonly bob: number
  /** Extra hull plates, for the heavier frames. */
  readonly plated: boolean
}

/**
 * Silhouette per archetype. These are the game's existing roles — a scout, a
 * turret, a brute — so the shapes have to be tellable apart at a glance from
 * a top-down camera, which in practice means size and ring count, not detail.
 */
const DRONE_SHAPES: Readonly<Record<CombatantArchetypeId, DroneShape>> = {
  'grave-husk': { scale: 1, hover: 0.95, spin: 1.7, bob: 0.07, plated: false },
  'bone-archer': {
    scale: 0.92,
    hover: 1.15,
    spin: 2.6,
    bob: 0.05,
    plated: false,
  },
  'crypt-brute': {
    scale: 1.5,
    hover: 0.85,
    spin: 0.9,
    bob: 0.05,
    plated: true,
  },
  'gaze-stalker': {
    scale: 0.86,
    hover: 1.05,
    spin: 3.4,
    bob: 0.1,
    plated: false,
  },
  'veil-breaker': {
    scale: 1.08,
    hover: 1.2,
    spin: 2.1,
    bob: 0.08,
    plated: true,
  },
  'blind-thrall': {
    scale: 0.72,
    hover: 0.8,
    spin: 4.2,
    bob: 0.12,
    plated: false,
  },
  'grave-warden': {
    scale: 2.3,
    hover: 1.1,
    spin: 0.7,
    bob: 0.04,
    plated: true,
  },
  'moonbriar-queen': {
    scale: 2.2,
    hover: 1.35,
    spin: 1.1,
    bob: 0.06,
    plated: true,
  },
  'parallax-seraph': {
    scale: 2.05,
    hover: 2.15,
    spin: 2.8,
    bob: 0.12,
    plated: false,
  },
  'null-crown': {
    scale: 2.55,
    hover: 1.3,
    spin: 0.38,
    bob: 0.025,
    plated: true,
  },
}

const DEFAULT_SHAPE: DroneShape = {
  scale: 1,
  hover: 1,
  spin: 1.8,
  bob: 0.07,
  plated: false,
}

export function DroneVisual({
  id,
  archetypeId,
  observed,
  dying,
  motionRef,
  hitFlashRevision,
}: {
  /** Enemy runtime id; seeds the hover phase so a crowd never bobs in sync. */
  id: string
  archetypeId: CombatantArchetypeId
  observed: boolean
  dying: boolean
  motionRef: CharacterMotionRef
  hitFlashRevision: number
}) {
  const shape = DRONE_SHAPES[archetypeId] ?? DEFAULT_SHAPE
  const chassisRef = useRef<Group>(null)
  const ringRef = useRef<Mesh>(null)
  const eyeRef = useRef<Mesh>(null)

  // Phase offset per drone so a crowd does not bob in lockstep, which is the
  // single most obvious tell that a swarm is procedural. Derived from the id
  // rather than Math.random so a seed always renders the same swarm.
  const phase = ((hashPhase(id) % 1000) / 1000) * Math.PI * 2

  const flashUntil = useRef(0)
  const jolt = useRef(0)
  const lastMotionRevision = useRef(-1)
  const clock = useRef(0)
  const deathSpin = useRef(0)
  const visualDelta = useRef(0)

  useEffect(() => {
    if (hitFlashRevision <= 0) return
    flashUntil.current = clock.current + 0.15
    jolt.current = 1
  }, [hitFlashRevision])

  useFrame((_, rawDelta) => {
    visualDelta.current += applyHitstop(Math.min(rawDelta, 0.08))
    const performance = getPerformanceFactor()
    const minimumVisualStep =
      performance < 0.55 ? 1 / 20 : performance < 0.8 ? 1 / 30 : 0
    if (
      !dying &&
      minimumVisualStep > 0 &&
      visualDelta.current < minimumVisualStep
    ) {
      return
    }
    const delta = visualDelta.current
    visualDelta.current = 0
    clock.current += delta
    const chassis = chassisRef.current
    if (!chassis) return

    const motion = motionRef.current
    if (motion.revision !== lastMotionRevision.current) {
      lastMotionRevision.current = motion.revision
      // An attack is a lunge and a flare; the drone has no arms to swing.
      if (motion.motion === 'attack' || motion.motion === 'dash-attack') {
        jolt.current = -1.4
        flashUntil.current = clock.current + 0.12
      } else if (motion.motion === 'hit') {
        jolt.current = 1
      }
    }

    if (dying) {
      // Machines do not crumple. They lose lift, tip over, and spin down.
      deathSpin.current += delta
      const fall = Math.min(1, deathSpin.current / 0.6)
      chassis.position.y = shape.hover * (1 - fall * fall) * shape.scale
      chassis.rotation.z = fall * 1.9
      chassis.rotation.y += delta * (7 - fall * 6)
      return
    }

    // Hover. Held drones sag slightly and stop bobbing — the gaze is pinning
    // them in place, and stillness is what sells that.
    const bob = observed ? 0 : Math.sin(clock.current * 2.4 + phase) * shape.bob
    jolt.current *= Math.max(0, 1 - delta * 9)
    chassis.position.y = (shape.hover + bob - jolt.current * 0.12) * shape.scale
    chassis.rotation.z = jolt.current * 0.22
    chassis.rotation.x = Math.sin(clock.current * 1.7 + phase) * 0.05

    const ring = ringRef.current
    if (ring) {
      // The halo lies in the ground plane, so its spin axis is the local Z —
      // turning Y here would stand it back up and hide it from this camera.
      // Frozen means it stops turning; stillness is the whole gaze read.
      ring.rotation.z += delta * (observed ? 0.12 : shape.spin)
      ring.rotation.x = Math.PI / 2 + Math.sin(clock.current + phase) * 0.09
    }

    const eye = eyeRef.current
    if (eye) {
      const flashing = clock.current < flashUntil.current
      eye.material = flashing
        ? EYE_FLASH_MATERIAL
        : observed
          ? EYE_HELD_MATERIAL
          : EYE_HOSTILE_MATERIAL
      const pulse = observed
        ? 1
        : 1 + Math.sin(clock.current * 6 + phase) * 0.12
      eye.scale.setScalar(flashing ? 1.5 : pulse)
    }
  })

  const hull = observed ? HULL_HELD_MATERIAL : HULL_MATERIAL
  const core = observed ? CORE_HELD_MATERIAL : CORE_MATERIAL
  const ringMaterial = observed ? RING_HELD_MATERIAL : RING_HOSTILE_MATERIAL

  return (
    <group ref={chassisRef} scale={shape.scale} name={`drone-${archetypeId}`}>
      {/* Edge rim. Tight enough to read as a drawn outline, not a blob. */}
      <mesh geometry={RIM_GEOMETRY} material={RIM_MATERIAL} scale={1.07} />
      {/* Dynamic swarm shadows multiply the shadow pass by enemy count. The
          ground marker/ring already anchors the drone, so normals skip them. */}
      <mesh geometry={HULL_GEOMETRY} material={hull} />
      {/* Top plate — the surface this camera actually looks at. */}
      <mesh
        geometry={PLATE_GEOMETRY}
        material={core}
        position={[0, 0.17, 0]}
        rotation={[0, Math.PI / 4, 0]}
      />
      {shape.plated ? (
        <mesh
          geometry={PLATE_GEOMETRY}
          material={core}
          position={[0, -0.15, 0]}
          scale={[1.15, 0.8, 1.15]}
        />
      ) : null}
      {/*
        The halo, held flat. A torus standing on edge disappears from directly
        above, which is exactly where the player is looking from — laying it in
        the ground plane is what makes a drone read as a drone in plan view.
      */}
      <mesh
        ref={ringRef}
        geometry={RING_GEOMETRY}
        material={ringMaterial}
        rotation={[Math.PI / 2, 0, 0]}
      />
      {/* Forward lens. -Z is the game's facing convention. */}
      <mesh
        ref={eyeRef}
        geometry={EYE_GEOMETRY}
        material={EYE_HOSTILE_MATERIAL}
        position={[0, 0.1, -0.26]}
      />
      <mesh
        geometry={THRUSTER_GEOMETRY}
        material={ringMaterial}
        position={[0, -0.24, 0]}
        scale={[1, 0.4, 1]}
      />
    </group>
  )
}
