import { useFrame } from '@react-three/fiber'
import { useRef } from 'react'
import { DoubleSide, type Group } from 'three'

import { getEliteBadgePresentation } from './sceneMetadata'
import { TOON_PALETTE } from './toonMaterials'

export function EliteBadge({
  affixId,
  height = 1.92,
}: {
  affixId: unknown
  height?: number
}) {
  const presentation = getEliteBadgePresentation(affixId)
  const billboardRef = useRef<Group>(null)

  useFrame(({ camera }) => {
    billboardRef.current?.quaternion.copy(camera.quaternion)
  })

  if (!presentation) return null

  return (
    <>
      <group
        ref={billboardRef}
        position={[0, height, 0]}
        name={`elite-badge-${presentation.id}-${presentation.shape}`}
      >
        <mesh position={[0, 0, -0.005]} renderOrder={38}>
          <circleGeometry args={[0.31, 16]} />
          <meshBasicMaterial
            color={TOON_PALETTE.ink}
            depthWrite={false}
            side={DoubleSide}
          />
        </mesh>
        {presentation.shape === 'chevrons' ? (
          <group name="elite-shape-chevrons" position={[0, 0.015, 0]}>
            {[-0.09, 0.09].map((offset) => (
              <group key={offset} position={[0, offset, 0]}>
                <mesh
                  position={[-0.07, 0, 0]}
                  rotation={[0, 0, -Math.PI / 4]}
                  renderOrder={39}
                >
                  <planeGeometry args={[0.07, 0.23]} />
                  <meshBasicMaterial
                    color={presentation.accent}
                    depthWrite={false}
                    side={DoubleSide}
                    toneMapped={false}
                  />
                </mesh>
                <mesh
                  position={[0.07, 0, 0]}
                  rotation={[0, 0, Math.PI / 4]}
                  renderOrder={39}
                >
                  <planeGeometry args={[0.07, 0.23]} />
                  <meshBasicMaterial
                    color={presentation.accent}
                    depthWrite={false}
                    side={DoubleSide}
                    toneMapped={false}
                  />
                </mesh>
              </group>
            ))}
          </group>
        ) : presentation.shape === 'shield' ? (
          <group name="elite-shape-shield" position={[0, 0.015, 0]}>
            <mesh renderOrder={39}>
              <circleGeometry args={[0.2, 5]} />
              <meshBasicMaterial
                color={presentation.accent}
                depthWrite={false}
                side={DoubleSide}
                toneMapped={false}
              />
            </mesh>
            <mesh position={[0, 0.015, 0.005]} renderOrder={40}>
              <circleGeometry args={[0.1, 5]} />
              <meshBasicMaterial
                color={TOON_PALETTE.ink}
                depthWrite={false}
                side={DoubleSide}
              />
            </mesh>
          </group>
        ) : (
          <group name="elite-shape-spikes" position={[0, 0.015, 0]}>
            {Array.from({ length: 6 }, (_, index) => (
              <mesh
                key={index}
                position={[
                  Math.cos((index / 6) * Math.PI * 2) * 0.13,
                  Math.sin((index / 6) * Math.PI * 2) * 0.13,
                  0,
                ]}
                rotation={[0, 0, (index / 6) * Math.PI * 2 - Math.PI / 2]}
                renderOrder={39}
              >
                <circleGeometry args={[0.12, 3]} />
                <meshBasicMaterial
                  color={presentation.accent}
                  depthWrite={false}
                  side={DoubleSide}
                  toneMapped={false}
                />
              </mesh>
            ))}
          </group>
        )}
      </group>

      <group
        position={[0, -0.675, 0]}
        rotation={[-Math.PI / 2, 0, 0]}
        name={`elite-ground-cue-${presentation.shape}`}
      >
        <mesh>
          <ringGeometry
            args={[0.56, 0.64, presentation.shape === 'spikes' ? 6 : 16]}
          />
          <meshBasicMaterial
            color={presentation.accent}
            opacity={0.62}
            transparent
            depthWrite={false}
            toneMapped={false}
          />
        </mesh>
        {presentation.shape === 'shield' ? (
          <mesh rotation={[0, 0, Math.PI / 4]}>
            <ringGeometry args={[0.37, 0.42, 4]} />
            <meshBasicMaterial
              color={presentation.accent}
              opacity={0.54}
              transparent
              depthWrite={false}
              toneMapped={false}
            />
          </mesh>
        ) : null}
      </group>
    </>
  )
}
