import type { CombatantArchetypeId } from '../game/types'

import { getEnemyDroneVisual } from './assetCatalog'

export interface EnemyStatusLayout {
  readonly healthBarHeight: number
  readonly eliteBadgeHeight: number
  readonly markerHeight: number
  readonly markerRadius: number
  readonly maxDistanceScale: number
  readonly clearance: number
}

const HEALTH_BAR_HALF_HEIGHT = 0.0925
const DEFAULT_MARKER_RADIUS = 0.5
const ELITE_BADGE_RADIUS = 0.31
const DEFAULT_CLEARANCE = 0.14
const MAX_DISTANCE_SCALE = 1.15

export function shouldShowEnemyHealthBar(health: number): boolean {
  return health > 0
}

export function getEnemyStatusLayout(
  archetypeId: CombatantArchetypeId,
  hasEliteBadge = false,
): EnemyStatusLayout {
  const isBoss =
    archetypeId === 'grave-warden' ||
    archetypeId === 'moonbriar-queen' ||
    archetypeId === 'parallax-seraph' ||
    archetypeId === 'null-crown'
  const healthBarHeight = getEnemyDroneVisual(archetypeId).statusAnchorHeight
  const markerRadius = isBoss ? 0.58 : DEFAULT_MARKER_RADIUS
  const clearance = isBoss ? 0.18 : DEFAULT_CLEARANCE
  const healthBarTop = healthBarHeight + HEALTH_BAR_HALF_HEIGHT
  const eliteBadgeHeight = healthBarTop + clearance + ELITE_BADGE_RADIUS
  const markerBase = hasEliteBadge
    ? eliteBadgeHeight + ELITE_BADGE_RADIUS
    : healthBarTop

  return {
    healthBarHeight,
    eliteBadgeHeight,
    markerHeight: markerBase + markerRadius * MAX_DISTANCE_SCALE + clearance,
    markerRadius,
    maxDistanceScale: MAX_DISTANCE_SCALE,
    clearance,
  }
}
