import { useFrame, useThree } from '@react-three/fiber'
import {
  CapsuleCollider,
  RigidBody,
  interactionGroups,
  type RapierRigidBody,
  useBeforePhysicsStep,
} from '@react-three/rapier'
import {
  useCallback,
  useEffect,
  useMemo,
  useRef,
  type MutableRefObject,
  type RefObject,
} from 'react'
import {
  BackSide,
  DoubleSide,
  Group,
  MathUtils,
  Mesh,
  MeshBasicMaterial,
  type Object3D,
  Plane,
  Quaternion,
  Raycaster,
  Vector2,
  Vector3,
} from 'three'

import { audioEngine } from '../runtime/audio'
import { useGameStore } from '../runtime/gameStore'
import {
  InputActionAdapter,
  getPrimaryGamepad,
  rumbleGamepad,
  type GamepadLike,
} from '../runtime/inputActions'
import { requestCameraImpact, runtime } from '../runtime/registry'
import {
  AssetBoundary,
  EmbeddedDirectionalCharacterModel,
  assetUrl,
  setCharacterMotion,
  type CharacterLocomotionState,
  type CharacterMotionRef,
  type CharacterMotionState,
} from './AssetModels'
import { resolveLocomotionSpeed01 } from './animation/locomotionBlend'
import { PLAYER_VISUAL } from './assetCatalog'
import { ARENA_HALF_X, ARENA_HALF_Z } from './arenaGround'
import {
  clampCameraAnchorToRoom,
  getCameraFramingInsets,
} from './cameraFraming'
import { quaternionFromNegativeZForward } from './direction'
import { advanceGameplayElapsed, isActiveGameplayPhase } from './gameplayClock'
import { applyHitstop, hitstopScale } from './hitstop'
import { resolvePlayerVisualFacing } from './playerVisualFacing'
import {
  createOperatorFeedProjectionState,
  disconnectOperatorFeedProjection,
  updateOperatorFeedProjection,
} from './operatorFeedProjection'
import {
  PLAYER_DEATH_FOCUS_FALLBACK_ANCHOR,
  findPlayerDeathFocusAnchor,
  isPlayerDeathFocusAnchorAttached,
  writePlayerDeathFocusPosition,
} from './playerDeathFocus'
import { TOON_PALETTE, toonGradientMap } from './toonMaterials'
import { EquippedWeaponHardpoints } from './weapons/WeaponModels'

const UP = new Vector3(0, 1, 0)
const GROUND_PLANE = new Plane(UP, 0)
const PLAYER_HIT_REACTION_SECONDS = 0.16
const PLAYER_HIT_STAGGER_SECONDS = 0.12
const PLAYER_HIT_ACTION_SECONDS = 0.2
const DASH_DURATION_SECONDS = 0.18
const DASH_ACTION_SECONDS = 0.36
const DASH_INVULNERABILITY_SECONDS = 0.23
const DASH_INPUT_BUFFER_SECONDS = 0.14
const DASH_SPEED_MULTIPLIER = 2
function ProceduralPlayerVisual() {
  return (
    <group name="player-procedural-fallback">
      <object3D
        name={PLAYER_DEATH_FOCUS_FALLBACK_ANCHOR}
        position={[0, 0.35, 0]}
      />
      <group scale={1.055}>
        <mesh position={[0, 0.08, 0]}>
          <capsuleGeometry args={[0.38, 0.7, 5, 10]} />
          <meshBasicMaterial color={TOON_PALETTE.ink} side={BackSide} />
        </mesh>
        <mesh position={[0, 0.58, -0.02]}>
          <sphereGeometry args={[0.31, 12, 9]} />
          <meshBasicMaterial color={TOON_PALETTE.ink} side={BackSide} />
        </mesh>
      </group>
      <mesh castShadow position={[0, 0.12, 0]}>
        <boxGeometry args={[0.68, 0.72, 0.46]} />
        <meshToonMaterial
          color={TOON_PALETTE.indigo}
          gradientMap={toonGradientMap}
        />
      </mesh>
      <mesh castShadow position={[0, 0.58, -0.02]}>
        <dodecahedronGeometry args={[0.29, 0]} />
        <meshToonMaterial
          color={TOON_PALETTE.white}
          gradientMap={toonGradientMap}
        />
      </mesh>
      <mesh castShadow position={[0, 0.12, 0.3]}>
        <boxGeometry args={[0.5, 0.52, 0.2]} />
        <meshToonMaterial
          color={TOON_PALETTE.indigoLight}
          gradientMap={toonGradientMap}
        />
      </mesh>
      <mesh position={[0, 0.58, -0.28]}>
        <boxGeometry args={[0.28, 0.075, 0.045]} />
        <meshBasicMaterial color={TOON_PALETTE.cyanLight} toneMapped={false} />
      </mesh>
    </group>
  )
}

function PlayerVisual({
  motionRef,
  locomotionRef,
  hitFlashRevision,
}: {
  motionRef: CharacterMotionRef
  locomotionRef: MutableRefObject<CharacterLocomotionState>
  hitFlashRevision?: string | null
}) {
  return (
    <AssetBoundary
      resetKey={PLAYER_VISUAL.model}
      fallback={<ProceduralPlayerVisual />}
    >
      <EmbeddedDirectionalCharacterModel
        url={assetUrl(PLAYER_VISUAL.model)}
        motionRef={motionRef}
        locomotionRef={locomotionRef}
        clips={PLAYER_VISUAL.clips}
        tint="#b9b9b9"
        tintStrength={0.08}
        position={[0, PLAYER_VISUAL.verticalOffset, 0]}
        scale={PLAYER_VISUAL.scale}
        outlineDistance={PLAYER_VISUAL.outlineDistance}
        hitFlashRevision={hitFlashRevision}
        hitFlashDurationMs={180}
        name="player-operative"
      />
    </AssetBoundary>
  )
}

interface PlayerProps {
  readonly spawn: { x: number; z: number }
  /** World point the opening camera beat reveals — the sector's exit gate. */
  readonly introFocus?: { x: number; z: number }
  readonly operatorFeedRef?: RefObject<HTMLDivElement | null>
}

export function Player({ spawn, introFocus, operatorFeedRef }: PlayerProps) {
  const bodyRef = useRef<RapierRigidBody>(null)
  const hitReactionRef = useRef<Group>(null)
  const visualRef = useRef<Group>(null)
  const dashRingRef = useRef<Mesh>(null)
  const simulatedPosition = useRef(new Vector3(spawn.x, 0.8, spawn.z))
  const input = useRef(new InputActionAdapter())
  const hitStaggerEndsAt = useRef(0)
  const hitReactionRemaining = useRef(0)
  const dashRequestedAt = useRef(Number.NEGATIVE_INFINITY)
  const dashMovementEndsAt = useRef(Number.NEGATIVE_INFINITY)
  const dashActionEndsAt = useRef(Number.NEGATIVE_INFINITY)
  const dashReadyAt = useRef(0)
  const dashCooldownSeconds = useRef(0.7)
  const lastDashProgress = useRef(1)
  const deathFlyDirection = useRef(new Vector3())
  const deathFlyProgress = useRef(Number.POSITIVE_INFINITY)
  const deathFocusAnchor = useRef<Object3D | null>(null)
  const roomIntroProgress = useRef(0)
  const introFocusRef = useRef(introFocus)
  const lastFootstepAt = useRef(0)
  const motionRef = useRef<CharacterMotionState>({
    motion: 'idle',
    revision: 0,
  })
  const locomotionRef = useRef<CharacterLocomotionState>({
    speed01: 0,
    moveAngle: 0,
  })
  const phase = useGameStore((state) => state.phase)
  const lastPlayerHit = useGameStore((state) => state.lastPlayerHit)
  const roomIndex = useGameStore((state) => state.roomIndex)
  const runId = useGameStore((state) => state.runId)
  const { camera, gl, size } = useThree()
  const raycaster = useMemo(() => new Raycaster(), [])
  const pointer = useMemo(() => new Vector2(), [])
  const aimPoint = useMemo(() => new Vector3(), [])
  const aimFacing = useMemo(() => new Vector3(), [])
  const desiredCamera = useMemo(() => new Vector3(), [])
  const smoothedCameraPosition = useRef(camera.position.clone())
  const cameraImpactOffset = useMemo(() => new Vector3(), [])
  const desiredLookTarget = useMemo(() => new Vector3(), [])
  const operatorFeedProjection = useMemo(() => new Vector3(), [])
  const operatorFeedProjectionState = useMemo(
    () => createOperatorFeedProjectionState(),
    [],
  )
  const smoothedLookTarget = useRef(new Vector3(spawn.x, 0, spawn.z - 0.7))
  const cameraAnchor = useMemo(() => new Vector3(), [])
  const cameraFramingInsets = useMemo(
    () => getCameraFramingInsets(size.width / Math.max(1, size.height)),
    [size.height, size.width],
  )
  const cameraFramingInsetsRef = useRef(cameraFramingInsets)
  const targetRotation = useMemo(() => new Quaternion(), [])
  const visualFacingTarget = useMemo(() => new Vector3(0, 0, -1), [])
  const physicsMove = useMemo(() => new Vector3(), [])
  const physicsVelocity = useMemo(() => new Vector3(), [])
  const dashDirection = useMemo(() => new Vector3(0, 0, -1), [])

  useEffect(() => {
    cameraFramingInsetsRef.current = cameraFramingInsets
  }, [cameraFramingInsets])

  useEffect(() => {
    introFocusRef.current = introFocus
  }, [introFocus])

  useEffect(() => {
    simulatedPosition.current.set(spawn.x, 0.8, spawn.z)
    runtime.playerPosition.copy(simulatedPosition.current)
    bodyRef.current?.setTranslation(simulatedPosition.current, true)
    bodyRef.current?.setLinvel({ x: 0, y: 0, z: 0 }, true)
    input.current.reset()
    hitStaggerEndsAt.current = 0
    dashRequestedAt.current = Number.NEGATIVE_INFINITY
    dashMovementEndsAt.current = Number.NEGATIVE_INFINITY
    dashActionEndsAt.current = Number.NEGATIVE_INFINITY
    dashReadyAt.current = 0
    lastDashProgress.current = 1
    deathFocusAnchor.current = null
    runtime.playerFocusPosition.copy(simulatedPosition.current)
    runtime.playerVisualFacing.set(0, 0, -1)
    runtime.playerDashVisualActive = false
    useGameStore.getState().setDashCooldownProgress(1)
    roomIntroProgress.current = 0
    desiredCamera.set(spawn.x, 14.2, spawn.z + 10.2)
    smoothedCameraPosition.current.copy(desiredCamera)
    camera.position.copy(desiredCamera)
    smoothedLookTarget.current.set(spawn.x, 0, spawn.z - 0.7)
    camera.lookAt(smoothedLookTarget.current)
  }, [camera, desiredCamera, roomIndex, runId, spawn.x, spawn.z])

  const updateAimFromPointer = useCallback(() => {
    raycaster.setFromCamera(runtime.pointerNdc, camera)
    if (!raycaster.ray.intersectPlane(GROUND_PLANE, aimPoint)) return false
    const facing = aimFacing
      .copy(aimPoint)
      .sub(simulatedPosition.current)
      .setY(0)
    if (facing.lengthSq() <= 0.02) return false
    runtime.playerFacing.copy(facing.normalize())
    return true
  }, [aimFacing, aimPoint, camera, raycaster])

  const updatePointerNdc = useCallback(
    (event: PointerEvent) => {
      const bounds = gl.domElement.getBoundingClientRect()
      if (bounds.width <= 0 || bounds.height <= 0) return
      pointer.set(
        ((event.clientX - bounds.left) / bounds.width) * 2 - 1,
        -((event.clientY - bounds.top) / bounds.height) * 2 + 1,
      )
      runtime.pointerNdc.copy(pointer)
    },
    [gl.domElement, pointer],
  )

  useEffect(() => {
    if (!lastPlayerHit) return
    hitReactionRemaining.current = PLAYER_HIT_REACTION_SECONDS
    hitStaggerEndsAt.current =
      runtime.presentationElapsed + PLAYER_HIT_STAGGER_SECONDS
    const state = useGameStore.getState()
    if (state.phase !== 'defeat' && !state.settings.reducedMotion) {
      setCharacterMotion(motionRef, 'hit', true, PLAYER_HIT_ACTION_SECONDS)
    }
  }, [lastPlayerHit])

  useEffect(() => {
    if (phase === 'defeat') {
      setCharacterMotion(motionRef, 'death', true)
      // The killing blow throws the body backward — away from whatever landed
      // it. Physics is paused in defeat, so the throw is animated on the
      // visual group in the frame loop below rather than through Rapier.
      deathFlyDirection.current
        .set(-runtime.playerHitDirection.x, 0, -runtime.playerHitDirection.z)
        .normalize()
      if (deathFlyDirection.current.lengthSq() < 0.01) {
        deathFlyDirection.current.copy(runtime.playerFacing).negate()
      }
      deathFlyProgress.current = 0
      deathFocusAnchor.current = null
    } else {
      deathFlyProgress.current = Number.POSITIVE_INFINITY
      deathFocusAnchor.current = null
      if (visualRef.current) visualRef.current.position.set(0, 0, 0)
    }
  }, [phase])

  useEffect(() => {
    const canvas = gl.domElement

    const handleKeyDown = (event: KeyboardEvent) => {
      if (event.code === 'Escape' && !event.repeat) {
        event.preventDefault()
        input.current.keyDown(event.code)
        useGameStore.getState().togglePause()
        return
      }

      const target = event.target
      const isInteractive =
        target instanceof Element &&
        target.closest(
          'button, input, select, textarea, a[href], [contenteditable="true"]',
        ) !== null
      if (
        !isActiveGameplayPhase(useGameStore.getState().phase) ||
        isInteractive
      )
        return

      input.current.keyDown(event.code, event.repeat)
      if (event.code === 'Space') event.preventDefault()
      if (['KeyW', 'KeyA', 'KeyS', 'KeyD'].includes(event.code)) {
        runtime.pressedKeys.add(event.code)
      }
    }
    const handleKeyUp = (event: KeyboardEvent) => {
      input.current.keyUp(event.code)
      runtime.pressedKeys.delete(event.code)
    }
    const handlePointerMove = (event: PointerEvent) => {
      input.current.pointerMoved()
      updatePointerNdc(event)
    }
    const handleContextMenu = (event: Event) => event.preventDefault()
    const handleBlur = () => {
      runtime.pressedKeys.clear()
      input.current.reset()
      if (isActiveGameplayPhase(useGameStore.getState().phase))
        useGameStore.getState().togglePause()
    }

    window.addEventListener('keydown', handleKeyDown)
    window.addEventListener('keyup', handleKeyUp)
    window.addEventListener('blur', handleBlur)
    canvas.addEventListener('pointermove', handlePointerMove)
    canvas.addEventListener('contextmenu', handleContextMenu)
    runtime.playerInputReady = true
    return () => {
      runtime.playerInputReady = false
      window.removeEventListener('keydown', handleKeyDown)
      window.removeEventListener('keyup', handleKeyUp)
      window.removeEventListener('blur', handleBlur)
      canvas.removeEventListener('pointermove', handlePointerMove)
      canvas.removeEventListener('contextmenu', handleContextMenu)
    }
  }, [gl.domElement, updateAimFromPointer, updatePointerNdc])

  useBeforePhysicsStep(() => {
    const body = bodyRef.current
    if (!body) return

    const state = useGameStore.getState()
    if (!isActiveGameplayPhase(state.phase)) {
      input.current.reset()
      body.setLinvel({ x: 0, y: 0, z: 0 }, true)
      return
    }

    // getGamepads() already returns an indexable snapshot; Array.from only
    // added a second throwaway array to every one of the 60 steps per second.
    const gamepad =
      typeof navigator !== 'undefined' && navigator.getGamepads
        ? getPrimaryGamepad(
            navigator.getGamepads() as unknown as readonly (GamepadLike | null)[],
          )
        : null
    const actionFrame = input.current.sample(gamepad)
    if (actionFrame.device !== runtime.activeInputDevice) {
      runtime.activeInputDevice = actionFrame.device
      state.setLastInputDevice(actionFrame.device)
    }
    if (actionFrame.pausePressed) {
      state.togglePause()
      body.setLinvel({ x: 0, y: 0, z: 0 }, true)
      return
    }
    if (actionFrame.dashPressed) dashRequestedAt.current = runtime.elapsed
    // Any deliberate input skips the rest of the gate reveal: the pan jumps
    // to its return leg so control never feels taken away.
    if (
      roomIntroProgress.current < 0.82 &&
      (Math.abs(actionFrame.moveX) > 0.1 || Math.abs(actionFrame.moveZ) > 0.1)
    ) {
      roomIntroProgress.current = 0.82
    }
    if (actionFrame.aimActive) {
      runtime.playerFacing
        .set(actionFrame.aimX, 0, actionFrame.aimZ)
        .normalize()
    }
    const translation = body.translation()
    simulatedPosition.current.set(translation.x, 0.8, translation.z)
    runtime.playerPosition.copy(simulatedPosition.current)

    physicsMove.set(actionFrame.moveX, 0, actionFrame.moveZ)
    if (physicsMove.lengthSq() > 1) physicsMove.normalize()
    const isStaggered = runtime.presentationElapsed < hitStaggerEndsAt.current
    const bufferedDash =
      runtime.elapsed - dashRequestedAt.current <= DASH_INPUT_BUFFER_SECONDS
    if (
      bufferedDash &&
      hitstopScale() > 0 &&
      runtime.presentationElapsed >= dashReadyAt.current &&
      !isStaggered
    ) {
      dashDirection.copy(
        physicsMove.lengthSq() > 0.01 ? physicsMove : runtime.playerFacing,
      )
      if (dashDirection.lengthSq() < 0.001) dashDirection.set(0, 0, -1)
      dashDirection.normalize()
      resolvePlayerVisualFacing(
        runtime.playerFacing,
        dashDirection,
        true,
        visualFacingTarget,
      )
      quaternionFromNegativeZForward(visualFacingTarget, targetRotation)
      visualRef.current?.quaternion.copy(targetRotation)
      runtime.playerVisualFacing.copy(visualFacingTarget)
      runtime.playerDashVisualActive = true
      dashRequestedAt.current = Number.NEGATIVE_INFINITY
      dashMovementEndsAt.current =
        runtime.presentationElapsed + DASH_DURATION_SECONDS
      dashActionEndsAt.current =
        runtime.presentationElapsed + DASH_ACTION_SECONDS
      dashCooldownSeconds.current = Math.max(
        DASH_DURATION_SECONDS,
        state.stats.dodgeCooldownMs / 1_000,
      )
      dashReadyAt.current =
        runtime.presentationElapsed + dashCooldownSeconds.current
      runtime.playerInvulnerableUntil = Math.max(
        runtime.playerInvulnerableUntil,
        runtime.elapsed + DASH_INVULNERABILITY_SECONDS,
      )
      requestCameraImpact(dashDirection, 0.28, 0.18)
      state.setDashCooldownProgress(0)
      lastDashProgress.current = 0
      state.spawnEffect({
        id: `player-dash-${runtime.elapsed}`,
        kind: 'dash',
        position: [
          simulatedPosition.current.x,
          0.08,
          simulatedPosition.current.z,
        ],
        direction: [dashDirection.x, 0, dashDirection.z],
        color: TOON_PALETTE.cyanLight,
        durationMs: 220,
        length: 1.9,
        width: 0.9,
      })
      audioEngine.play('dash')
      rumbleGamepad(gamepad, state.settings.gamepadVibration, 0.15, 40)
      setCharacterMotion(motionRef, 'dash', true, DASH_ACTION_SECONDS)
    }

    const dashProgress = Math.min(
      1,
      Math.max(
        0,
        1 -
          (dashReadyAt.current - runtime.presentationElapsed) /
            Math.max(0.001, dashCooldownSeconds.current),
      ),
    )
    if (
      Math.abs(dashProgress - lastDashProgress.current) >= 0.05 ||
      (dashProgress === 1 && lastDashProgress.current !== 1)
    ) {
      const becameReady = dashProgress === 1 && lastDashProgress.current < 1
      lastDashProgress.current = dashProgress
      state.setDashCooldownProgress(dashProgress)
      if (becameReady) audioEngine.play('dash-ready')
    }

    const dashActive = runtime.presentationElapsed < dashMovementEndsAt.current
    if (
      !dashActive &&
      physicsMove.lengthSq() > 0.01 &&
      runtime.presentationElapsed - lastFootstepAt.current >= 0.34
    ) {
      lastFootstepAt.current = runtime.presentationElapsed
      audioEngine.play('footstep')
    }

    let direction = physicsMove
    let speed = state.stats.moveSpeed
    if (dashActive) {
      direction = dashDirection
      speed *= DASH_SPEED_MULTIPLIER
    } else if (isStaggered) {
      direction = physicsVelocity.set(0, 0, 0)
      speed = 0
    }
    if (hitstopScale() === 0) speed = 0

    physicsVelocity.copy(direction).multiplyScalar(speed)
    body.setLinvel({ x: physicsVelocity.x, y: 0, z: physicsVelocity.z }, true)
    locomotionRef.current.speed01 = resolveLocomotionSpeed01(
      physicsVelocity.x,
      physicsVelocity.z,
      state.stats.moveSpeed,
    )
    if (physicsVelocity.lengthSq() > 0.001) {
      // Signed facing-to-movement angle for the twin-stick gait (legs face
      // the travel direction while the body keeps aiming with the mouse).
      const facing = runtime.playerFacing
      locomotionRef.current.moveAngle = Math.atan2(
        facing.z * physicsVelocity.x - facing.x * physicsVelocity.z,
        facing.x * physicsVelocity.x + facing.z * physicsVelocity.z,
      )
    }
    if (
      !isStaggered &&
      runtime.presentationElapsed >= dashActionEndsAt.current
    ) {
      setCharacterMotion(motionRef, 'locomotion')
    }
  })

  useFrame((_, frameDelta) => {
    const state = useGameStore.getState()
    const rawDelta = Math.min(frameDelta, 0.1)
    const delta = applyHitstop(rawDelta)
    const body = bodyRef.current
    if (body) {
      const translation = body.translation()
      simulatedPosition.current.set(translation.x, 0.8, translation.z)
      runtime.playerPosition.copy(simulatedPosition.current)
    }
    // The arena is bounded again, so the frame is held off its walls: without
    // this the camera swings past the boundary and fills a third of the screen
    // with nothing whenever the player fights along an edge.
    const cameraTarget = simulatedPosition.current
    cameraAnchor.set(
      clampCameraAnchorToRoom(
        cameraTarget.x,
        -ARENA_HALF_X,
        ARENA_HALF_X,
        cameraFramingInsetsRef.current.x,
      ),
      0,
      clampCameraAnchorToRoom(
        cameraTarget.z,
        -ARENA_HALF_Z,
        ARENA_HALF_Z,
        cameraFramingInsetsRef.current.z,
      ),
    )
    const trauma = state.settings.reducedMotion ? 0 : runtime.cameraTrauma
    const cameraKick = state.settings.reducedMotion ? 0 : runtime.cameraKick
    const shakeX =
      Math.sin(runtime.presentationElapsed * 79) * trauma * trauma * 0.16
    const shakeZ =
      Math.cos(runtime.presentationElapsed * 91) * trauma * trauma * 0.12
    // Round-start beat, one timeline: the camera opens high, slides out to
    // the exit gate so the objective is read before the first step, holds,
    // then hands the frame back to the player as the lift settles.
    //
    // Gated on 'playing', and deliberately *not* with an else-snap. This ran
    // on raw frame delta before, so its whole budget burned during shader
    // compilation, the two screen-transition covers, and the first-run guide's
    // pause — the pan was always finished by the time the player could see
    // anything. Holding at zero until the frame is actually theirs is the
    // entire fix.
    if (state.settings.reducedMotion) {
      roomIntroProgress.current = 1
    } else if (
      roomIntroProgress.current < 1 &&
      isActiveGameplayPhase(state.phase)
    ) {
      roomIntroProgress.current = Math.min(
        1,
        roomIntroProgress.current + delta / 2.1,
      )
    }
    const introProgress = roomIntroProgress.current
    const introEase = 1 - Math.pow(1 - introProgress, 3)
    const introLift = (1 - introEase) * 7.5
    const gateFocus = introFocusRef.current
    let gateWeight = 0
    if (gateFocus && introProgress < 1) {
      // Rise 0→0.26, dwell on the gate to 0.55, return by 0.85.
      gateWeight =
        introProgress < 0.26
          ? introProgress / 0.26
          : introProgress < 0.55
            ? 1
            : Math.max(0, 1 - (introProgress - 0.55) / 0.3)
      gateWeight = gateWeight * gateWeight * (3 - 2 * gateWeight)
    }
    if (gateWeight > 0 && gateFocus) {
      cameraAnchor.set(
        MathUtils.lerp(cameraAnchor.x, gateFocus.x, gateWeight),
        0,
        MathUtils.lerp(cameraAnchor.z, gateFocus.z, gateWeight),
      )
    }
    desiredCamera.set(
      cameraAnchor.x + shakeX,
      14.2 + introLift,
      cameraAnchor.z + 10.2 + introLift * 0.55 + shakeZ,
    )
    smoothedCameraPosition.current.lerp(desiredCamera, 1 - Math.exp(-delta * 6))
    cameraImpactOffset.set(
      -runtime.cameraImpactDirection.x * cameraKick * 0.38,
      0,
      -runtime.cameraImpactDirection.z * cameraKick * 0.3,
    )
    camera.position.copy(smoothedCameraPosition.current).add(cameraImpactOffset)
    desiredLookTarget.set(cameraAnchor.x, 0, cameraAnchor.z - 0.7)
    smoothedLookTarget.current.lerp(
      desiredLookTarget,
      1 - Math.exp(-delta * 10),
    )
    camera.lookAt(smoothedLookTarget.current)
    const operatorFeedElement = operatorFeedRef?.current
    if (operatorFeedElement) {
      updateOperatorFeedProjection(
        operatorFeedElement,
        camera,
        simulatedPosition.current,
        size,
        operatorFeedProjection,
        operatorFeedProjectionState,
        delta,
      )
    } else if (operatorFeedProjectionState.element) {
      disconnectOperatorFeedProjection(operatorFeedProjectionState)
    }
    runtime.cameraTrauma = Math.max(0, runtime.cameraTrauma - delta * 2.8)
    runtime.cameraKick = Math.max(0, runtime.cameraKick - delta * 7.5)

    if (dashRingRef.current) {
      const progress = state.dashCooldownProgress
      const material = dashRingRef.current.material as MeshBasicMaterial
      material.opacity = progress < 1 ? 0.18 + progress * 0.5 : 0
      const scale = 0.78 + progress * 0.32
      dashRingRef.current.scale.setScalar(scale)
      dashRingRef.current.rotation.z = runtime.presentationElapsed * 1.8
    }

    const reactionRemaining = hitReactionRemaining.current
    if (hitReactionRef.current) {
      if (reactionRemaining > 0 && !state.settings.reducedMotion) {
        const progress = 1 - reactionRemaining / PLAYER_HIT_REACTION_SECONDS
        const impulse = Math.sin(Math.min(1, progress) * Math.PI)
        hitReactionRef.current.position.set(
          -runtime.playerHitDirection.x * impulse * 0.2,
          impulse * 0.065,
          -runtime.playerHitDirection.z * impulse * 0.2,
        )
        hitReactionRef.current.scale.set(
          1 + impulse * 0.08,
          1 - impulse * 0.12,
          1 + impulse * 0.08,
        )
        hitReactionRef.current.rotation.z =
          runtime.playerHitDirection.x * impulse * 0.1
      } else {
        hitReactionRef.current.position.set(0, 0, 0)
        hitReactionRef.current.scale.set(1, 1, 1)
        hitReactionRef.current.rotation.z = 0
      }
    }
    hitReactionRemaining.current = Math.max(0, reactionRemaining - delta)

    // Death throw: the body sails backward and slams down while the iris
    // closes around it. Physics is paused in defeat, so this animates the
    // visual group directly — the collider no longer matters to a corpse.
    if (state.phase === 'defeat') {
      const visual = visualRef.current
      if (visual) {
        if (deathFlyProgress.current < 1) {
          deathFlyProgress.current = Math.min(
            1,
            deathFlyProgress.current + delta / 0.7,
          )
          const flight = deathFlyProgress.current
          const glide = 1 - Math.pow(1 - flight, 2.4)
          visual.position.set(
            deathFlyDirection.current.x * glide * 2.6,
            Math.sin(Math.min(1, flight) * Math.PI) * 0.85,
            deathFlyDirection.current.z * glide * 2.6,
          )
          visual.rotation.x = -glide * 0.9
        }

        // The authored Death clip moves the skinned body away from this outer
        // group's origin. Follow its pelvis/root bone through the complete
        // animation, including after the 0.7s throw has finished.
        const cachedAnchor = deathFocusAnchor.current
        const anchor =
          cachedAnchor && isPlayerDeathFocusAnchorAttached(visual, cachedAnchor)
            ? cachedAnchor
            : findPlayerDeathFocusAnchor(visual)
        deathFocusAnchor.current = anchor === visual ? null : anchor
        writePlayerDeathFocusPosition(anchor, runtime.playerFocusPosition)
      } else {
        runtime.playerFocusPosition.copy(simulatedPosition.current)
      }
    } else {
      runtime.playerFocusPosition.copy(simulatedPosition.current)
    }

    if (runtime.activeInputDevice === 'keyboard-mouse') updateAimFromPointer()
    // Aim, camera, collider, and weapon hardpoints remain on playerFacing.
    // The rendered silhouette alone owns dashDirection for the entire Roll
    // action, including the authored follow-through after movement stops.
    const dashVisualActive =
      state.phase !== 'defeat' &&
      runtime.presentationElapsed < dashActionEndsAt.current
    resolvePlayerVisualFacing(
      runtime.playerFacing,
      dashDirection,
      dashVisualActive,
      visualFacingTarget,
    )
    quaternionFromNegativeZForward(visualFacingTarget, targetRotation)
    runtime.playerDashVisualActive = dashVisualActive
    if (state.phase !== 'defeat') {
      const visual = visualRef.current
      if (visual) {
        if (dashVisualActive) {
          visual.quaternion.copy(targetRotation)
        } else {
          visual.quaternion.slerp(targetRotation, 1 - Math.exp(-delta * 24))
        }
        runtime.playerVisualFacing
          .set(0, 0, -1)
          .applyQuaternion(visual.quaternion)
          .setY(0)
          .normalize()
      }
    } else {
      runtime.playerDashVisualActive = false
    }

    if (!isActiveGameplayPhase(state.phase)) {
      runtime.pressedKeys.clear()
      input.current.reset()
      bodyRef.current?.setLinvel({ x: 0, y: 0, z: 0 }, true)
      return
    }
    runtime.elapsed = advanceGameplayElapsed(
      state.phase,
      runtime.elapsed,
      rawDelta,
    )
  })

  return (
    <RigidBody
      ref={bodyRef}
      type="dynamic"
      colliders={false}
      position={[spawn.x, 0.8, spawn.z]}
      enabledRotations={[false, false, false]}
      enabledTranslations={[true, false, true]}
      gravityScale={0}
      linearDamping={8}
      dominanceGroup={10}
      name="player"
    >
      <CapsuleCollider
        args={[0.42, 0.34]}
        collisionGroups={interactionGroups(1, [0, 2, 3])}
      />
      <mesh
        ref={dashRingRef}
        name="player-dash-cooldown"
        position={[0, -0.785, 0]}
        rotation={[-Math.PI / 2, 0, 0]}
      >
        <ringGeometry args={[0.48, 0.55, 40, 1, 0, Math.PI * 1.72]} />
        <meshBasicMaterial
          color={TOON_PALETTE.cyanLight}
          transparent
          opacity={0}
          depthWrite={false}
          side={DoubleSide}
          toneMapped={false}
        />
      </mesh>
      <group ref={hitReactionRef} name="player-hit-reaction">
        <group ref={visualRef} name="player-visual">
          <PlayerVisual
            motionRef={motionRef}
            locomotionRef={locomotionRef}
            hitFlashRevision={lastPlayerHit?.id}
          />
        </group>
      </group>
      <EquippedWeaponHardpoints />
    </RigidBody>
  )
}
