import { Object3D, Vector3 } from 'three'

/** The embedded player rig's pelvis/root, which stays near the rendered body. */
export const PLAYER_DEATH_FOCUS_BONE = 'Body'
/** Explicit torso point used by the non-rigged loading/error fallback. */
export const PLAYER_DEATH_FOCUS_FALLBACK_ANCHOR = 'player-death-focus-anchor'

/**
 * Returns the animated rig anchor used by the death iris.
 *
 * The procedural loading/error fallback has no skeleton, so its visual group
 * remains a safe focus rather than leaving the iris on a stale run position.
 */
export function findPlayerDeathFocusAnchor(visual: Object3D): Object3D {
  return (
    visual.getObjectByName(PLAYER_DEATH_FOCUS_BONE) ??
    visual.getObjectByName(PLAYER_DEATH_FOCUS_FALLBACK_ANCHOR) ??
    visual
  )
}

/** True while a cached anchor still belongs to the currently rendered visual. */
export function isPlayerDeathFocusAnchorAttached(
  visual: Object3D,
  anchor: Object3D,
): boolean {
  let current: Object3D | null = anchor
  while (current) {
    if (current === visual) return true
    current = current.parent
  }
  return false
}

/** Writes the anchor's current world position after refreshing its hierarchy. */
export function writePlayerDeathFocusPosition(
  anchor: Object3D,
  target: Vector3,
): Vector3 {
  anchor.updateWorldMatrix(true, false)
  return target.setFromMatrixPosition(anchor.matrixWorld)
}
