export function isFlatDarkFrame(pixels: Uint8Array): boolean {
  if (pixels.length < 4) return false

  let minimum = 255
  let maximum = 0
  let total = 0
  let samples = 0
  for (let offset = 0; offset <= pixels.length - 4; offset += 4) {
    const luminance =
      pixels[offset] * 0.2126 +
      pixels[offset + 1] * 0.7152 +
      pixels[offset + 2] * 0.0722
    minimum = Math.min(minimum, luminance)
    maximum = Math.max(maximum, luminance)
    total += luminance
    samples += 1
  }

  const average = total / Math.max(1, samples)
  return average <= 24 && maximum <= 32 && maximum - minimum <= 8
}

export type PostProcessingMode = 'full' | 'render-safe' | 'raw'

export function nextPostProcessingMode(
  current: PostProcessingMode,
): PostProcessingMode {
  if (current === 'full') return 'render-safe'
  return 'raw'
}
