export function isActiveGameplayPhase(phase: unknown): boolean {
  return phase === 'playing'
}

export function advanceGameplayElapsed(
  phase: unknown,
  elapsed: number,
  deltaSeconds: number,
): number {
  if (!isActiveGameplayPhase(phase)) return elapsed
  if (!Number.isFinite(deltaSeconds) || deltaSeconds <= 0) return elapsed
  return elapsed + Math.min(deltaSeconds, 0.1)
}
