export interface VisionConeStyle {
  readonly fillOpacity: number
  readonly accentOpacity: number
}

/** Enemies held at once before the cone reads as fully engaged. */
export const FULL_ENGAGEMENT_TARGETS = 3

/**
 * Brightness carries two signals: the accessibility setting, and how much the
 * field is currently holding. `engagement` is the second one, normalized — it
 * replaced an optic charge meter that no longer exists now that the field is a
 * standing rule rather than a cooldown.
 */
export function getVisionConeStyle(
  visionAssist: number,
  engagement: number,
): VisionConeStyle {
  const normalized = Number.isFinite(visionAssist)
    ? Math.min(1, Math.max(0, visionAssist))
    : 0
  const eased = normalized * normalized * (3 - 2 * normalized)
  const held = Number.isFinite(engagement)
    ? Math.min(1, Math.max(0, engagement))
    : 0
  return {
    // Halved against the old values. The fill is additive, so on the light
    // deck it was blowing a quarter of the frame to white and hiding the very
    // enemies it exists to mark. It only has to read as a tint now.
    fillOpacity: 0.09 + eased * 0.09 + held * 0.11,
    accentOpacity: 0.62 + eased * 0.18 + held * 0.2,
  }
}
