type SceneRoom = GeneratedRoom | GeneratedRunNode

function toError(cause: unknown, fallback: string): Error {
  return cause instanceof Error ? cause : new Error(fallback)
}

class SceneErrorBoundary extends Component<
  { children: ReactNode; onError?: (error: Error) => void },
  { failed: boolean }
> {
  state = { failed: false }

  static getDerivedStateFromError() {
    return { failed: true }
  }

  componentDidCatch(error: Error, _info: ErrorInfo) {
    void _info
    this.props.onError?.(error)
  }

  render() {
    return this.state.failed ? null : this.props.children
  }
}

function ContentReadySignal({ onReady }: { onReady: () => void }) {
  useEffect(() => onReady(), [onReady])
  return null
}

function nextFrame(): Promise<void> {
  return new Promise((resolve) => requestAnimationFrame(() => resolve()))
}

const SCENE_COMPILATION_TIMEOUT_MS = 30_000
/** Run-clock resolution. Whole seconds are all the HUD ever shows. */
const RUN_TICK_MS = 200
const reportedContextLossEvents = new WeakSet<Event>()

function reportContextLoss(
  event: Event,
  onFatalError?: (error: Error) => void,
): void {
  event.preventDefault()
  if (reportedContextLossEvents.has(event)) return
  reportedContextLossEvents.add(event)
  onFatalError?.(new Error('WebGL context was lost while loading STILLSEEN.'))
}

function SceneWarmup({
  contentReady,
  postProcessingReady,
  enabled,
  onLoadProgress,
  onReady,
  onFatalError,
}: {
  contentReady: boolean
  postProcessingReady: boolean
  enabled: boolean
  onLoadProgress?: (update: SceneLoadProgress) => void
  onReady?: () => void
  onFatalError?: (error: Error) => void
}) {
  const gl = useThree((state) => state.gl)
  const scene = useThree((state) => state.scene)
  const camera = useThree((state) => state.camera)
  const completed = useRef(false)
  const activeAttempt = useRef<object | null>(null)
  const compilationRef = useRef<SceneMaterialCompilationTask | null>(null)
  const contextLost = useRef(false)

  useEffect(() => {
    const canvas = gl.domElement
    const handleContextLost = (event: Event) => {
      contextLost.current = true
      compilationRef.current?.cancel()
      reportContextLoss(event, onFatalError)
    }
    canvas.addEventListener('webglcontextlost', handleContextLost)
    return () =>
      canvas.removeEventListener('webglcontextlost', handleContextLost)
  }, [gl, onFatalError])

  useEffect(() => {
    if (
      !contentReady ||
      !postProcessingReady ||
      completed.current ||
      activeAttempt.current
    ) {
      return
    }
    const attempt = {}
    activeAttempt.current = attempt
    let active = true
    let compilation: SceneMaterialCompilationTask | null = null

    const warm = async () => {
      try {
        onLoadProgress?.({
          stage: 'shader-compilation',
          progress: enabled ? 0.72 : 0.9,
          message: enabled ? '셰이더를 준비하는 중' : '렌더러 준비 완료',
        })
        if (enabled) {
          if (contextLost.current) return
          compilation = startSceneMaterialCompilation(
            () => gl.compile(scene, camera),
            { timeoutMs: SCENE_COMPILATION_TIMEOUT_MS },
          )
          compilationRef.current = compilation
          const outcome = await compilation.promise
          if (outcome === 'cancelled') return
        }
        if (!active) return
        onLoadProgress?.({
          stage: 'post-processing-warmup',
          progress: 0.91,
          message: '화면 효과를 예열하는 중',
        })
        // These frames are rendered by the persistent composer on this same
        // Canvas, so no throwaway WebGL context or duplicate shader cache exists.
        await nextFrame()
        await nextFrame()
        if (!active) return
        onLoadProgress?.({
          stage: 'ready',
          progress: 1,
          message: '임무 준비 완료',
        })
        onReady?.()
        completed.current = true
      } catch (cause) {
        if (active) {
          onFatalError?.(toError(cause, 'STILLSEEN renderer warmup failed.'))
        }
      } finally {
        if (compilationRef.current === compilation) {
          compilationRef.current = null
        }
        if (activeAttempt.current === attempt) {
          activeAttempt.current = null
        }
      }
    }

    void warm()
    return () => {
      active = false
      compilation?.cancel()
      if (compilationRef.current === compilation) {
        compilationRef.current = null
      }
      if (activeAttempt.current === attempt) {
        activeAttempt.current = null
      }
    }
  }, [
    camera,
    contentReady,
    enabled,
    gl,
    onFatalError,
    onLoadProgress,
    onReady,
    postProcessingReady,
    scene,
  ])

  return null
}

function ScenePreparation({
  preparationKey,
  onReady,
  onFatalError,
}: {
  preparationKey?: string | null
  onReady?: (key: string) => void
  onFatalError?: (error: Error) => void
}) {
  const gl = useThree((state) => state.gl)
  const scene = useThree((state) => state.scene)
  const camera = useThree((state) => state.camera)
  const completedKey = useRef<string | null>(null)

  useEffect(() => {
    if (!preparationKey || completedKey.current === preparationKey) return
    let active = true
    let contextLost = false
    let compilation: SceneMaterialCompilationTask | null = null
    const canvas = gl.domElement
    const handleContextLost = (event: Event) => {
      contextLost = true
      compilation?.cancel()
      reportContextLoss(event, onFatalError)
    }
    canvas.addEventListener('webglcontextlost', handleContextLost)

    const prepare = async () => {
      try {
        await nextFrame()
        if (!active || contextLost) return
        compilation = startSceneMaterialCompilation(
          () => gl.compile(scene, camera),
          { timeoutMs: SCENE_COMPILATION_TIMEOUT_MS },
        )
        const outcome = await compilation.promise
        if (outcome === 'cancelled') return
        await nextFrame()
        if (!active) return
        completedKey.current = preparationKey
        onReady?.(preparationKey)
      } catch (cause) {
        if (active) {
          onFatalError?.(
            toError(cause, 'STILLSEEN room shader preparation failed.'),
          )
        }
      }
    }
    void prepare()
    return () => {
      active = false
      compilation?.cancel()
      canvas.removeEventListener('webglcontextlost', handleContextLost)
    }
  }, [camera, gl, onFatalError, onReady, preparationKey, scene])

  return null
}

function transformDirection(
  direction: CardinalDirection,
  variant: LayoutVariant,
): CardinalDirection {
  if (variant === 'original') return direction
  if (variant === 'mirror-x') {
    if (direction === 'east') return 'west'
    if (direction === 'west') return 'east'
    return direction
  }
  const opposite: Record<CardinalDirection, CardinalDirection> = {
    north: 'south',
    east: 'west',
    south: 'north',
    west: 'east',
  }
  return opposite[direction]
}

function transformRoomLayout(
  room: RoomTemplate,
  variant: LayoutVariant,
): RoomTemplate {
  if (variant === 'original') return room
  return {
    ...room,
    sockets: room.sockets.map((socket) => ({
      ...socket,
      position: applyLayoutVariant(socket.position, variant),
      direction: transformDirection(socket.direction, variant),
    })),
    spawns: room.spawns.map((spawn) => ({
      ...spawn,
      position: applyLayoutVariant(spawn.position, variant),
    })),
    occluders: room.occluders.map((occluder) => ({
      ...occluder,
      center: applyLayoutVariant(occluder.center, variant),
    })),
    waypoints: room.waypoints.map((waypoint) => ({
      ...waypoint,
      position: applyLayoutVariant(waypoint.position, variant),
    })),
  }
}

/**
 * Death iris. On defeat a camera-facing ring closes around the thrown
 * silhouette until only the body is left in a disc of light — the world is
 * masked out, the failure is personal. It tracks `playerFocusPosition`, not
 * the frozen collider, or it would close on empty floor. The rim is emissive so the selective bloom pass
 * burns a thin hostile-red halo at the aperture's edge; everything else about
 * the mask is flat black and deliberately outside the bloom selection.
 */
function DeathIris() {
  const phase = useGameStore((state) => state.phase)
  const maskRef = useRef<Mesh>(null)
  const rimRef = useRef<Mesh>(null)
  const progress = useRef(0)

  useEffect(() => {
    if (phase === 'defeat') progress.current = 0
  }, [phase])

  useFrame(({ camera, clock }, delta) => {
    if (phase !== 'defeat') return
    progress.current = Math.min(1, progress.current + delta / 1.1)
    const eased = 1 - Math.pow(1 - progress.current, 3)
    // Once shut the aperture breathes rather than freezing, so the held beat
    // before the defeat card reads as a live frame instead of a stall.
    const held = progress.current >= 1
    const pulse = held ? Math.sin(clock.elapsedTime * 4.4) : 0
    // The ring geometry has inner radius 1; scaling the mesh scales the
    // aperture with it while the outer edge stays far past the viewport.
    const aperture = 26 - (26 - 1.35) * eased
    const mask = maskRef.current
    const rim = rimRef.current
    if (mask) {
      mask.position.copy(runtime.playerFocusPosition)
      mask.quaternion.copy(camera.quaternion)
      mask.scale.setScalar(aperture)
    }
    if (rim) {
      rim.position.copy(mask?.position ?? rim.position)
      rim.quaternion.copy(camera.quaternion)
      rim.scale.setScalar(aperture * (1 + pulse * 0.02))
      const material = rim.material as MeshBasicMaterial
      material.opacity = 0.9 + pulse * 0.25
    }
  })

  if (phase !== 'defeat') return null
  return (
    <>
      <mesh ref={maskRef} renderOrder={90} frustumCulled={false}>
        <ringGeometry args={[1, 60, 48]} />
        <meshBasicMaterial
          color="#020608"
          transparent
          opacity={0.96}
          depthTest={false}
          depthWrite={false}
        />
      </mesh>
      <mesh ref={rimRef} renderOrder={91} frustumCulled={false}>
        <ringGeometry args={[0.985, 1.02, 48]} />
        <meshBasicMaterial
          color={TOON_PALETTE.hostileLight}
          transparent
          opacity={0.9}
          depthTest={false}
          depthWrite={false}
          toneMapped={false}
        />
      </mesh>
    </>
  )
}

function RoomEncounter({
  room,
  runId,
  onEncounterEvent,
  operatorFeedRef,
}: {
  room: SceneRoom
  runId: number
  onEncounterEvent?: (event: EncounterPresentationEvent) => void
  operatorFeedRef?: RefObject<HTMLDivElement | null>
}) {
  const difficulty = useGameStore((state) => state.difficulty)
  const mode = useGameStore((state) => state.mode)
  const roomIndex = useGameStore((state) => state.roomIndex)
  const roomIndexForScale = 'depth' in room ? room.depth : roomIndex + 1
  const template = useMemo(
    () =>
      // Scale after the layout variant so mirrored rooms grow identically.
      // Depth is the escape game's difficulty dial: same enemy roster, more
      // floor between the player and the way out.
      scaleRoomTemplate(
        transformRoomLayout(
          getRoomTemplate(room.templateId),
          room.layoutVariant,
        ),
        getRoomScale(roomIndexForScale),
      ),
    [room.layoutVariant, room.templateId, roomIndexForScale],
  )
  /**
   * The graph hostiles route on.
   *
   * Not the room's own five nodes: those are authored for a 22×16 chamber, and
   * the survival arena is 76×52 with a scattered cover field the template knows
   * nothing about. Routing on the template's graph would send everything toward
   * the same handful of points near the origin and leave anything that met a
   * crate with nowhere to go.
   */
  const waypoints = useMemo(() => buildArenaWaypoints(), [])
  const phase = useGameStore((state) => state.phase)
  const runElapsedSeconds = useGameStore((state) => state.runElapsedSeconds)
  const setRoomPopulation = useGameStore((state) => state.setRoomPopulation)
  const spawnEffect = useGameStore((state) => state.spawnEffect)
  const [ready, setReady] = useState(false)
  const [bossReinforcements, setBossReinforcements] = useState<
    GeneratedEnemySpawn[]
  >([])
  const completionHandled = useRef(false)
  const spawnedSurvivalBosses = useRef(0)
  const survivalBossPending = useRef(false)
  const startSignaled = useRef(false)
  const clearSignaled = useRef(false)
  const encounterTier: AttackDirectorTier =
    room.kind === 'boss' ? 'boss' : room.chamberLevel
  const absoluteChamber = 'depth' in room ? room.depth : roomIndex + 1
  const scaling = useMemo(
    () => getCombatScaling(absoluteChamber, difficulty),
    [absoluteChamber, difficulty],
  )
  const attackDirector = useMemo(
    () => createAttackDirector(encounterTier, difficulty),
    [difficulty, encounterTier],
  )

  const playerSpawn = useMemo(
    () =>
      template.spawns.find((spawn) => spawn.role === 'player')?.position ?? {
        x: 0,
        z: 5,
      },
    [template.spawns],
  )
  /**
   * Stealth opening. Generated spawn positions are template-space: scale them
   * with the room, then push anything inside the player's opening pocket out
   * to its edge, so every sector begins in cleared ground.
   */
  const enemySpawns = useMemo(() => {
    const scale = getRoomScale(roomIndexForScale)
    const scaled = room.enemies.map((spawn) => ({
      x: spawn.position.x * scale,
      z: spawn.position.z * scale,
    }))
    const cleared = pushSpawnsOutOfClearZone(scaled, playerSpawn, {
      minDistance: OPENING_ENEMY_MIN_DISTANCE,
      halfX: ARENA_HALF_X,
      halfZ: ARENA_HALF_Z,
      margin: 2,
    })
    return room.enemies.map((spawn, index) => ({
      ...spawn,
      position: cleared[index] ?? spawn.position,
    }))
  }, [playerSpawn, room.enemies, roomIndexForScale])
  const roomId = 'id' in room ? room.id : `${room.index}:${room.templateId}`
  const encounterId = `${runId}:${roomId}`
  const roomBossId =
    room.kind === 'boss'
      ? (room.enemies.map((enemy) => enemy.archetypeId).find(isSceneBoss) ??
        null)
      : null
  const encounterPresentation = useMemo(
    () => ({
      endless: mode === 'endless',
      chamber: absoluteChamber,
      roomId,
      roomName: template.name,
      boss: room.kind === 'boss',
      risk:
        'routeRisk' in room
          ? room.routeRisk
          : room.kind === 'boss'
            ? 'boss'
            : 'fixed',
      mutationId: 'mutationId' in room ? room.mutationId : null,
      eliteCount:
        'eliteCount' in room
          ? room.eliteCount
          : room.enemies.filter((enemy) => enemy.eliteAffixId != null).length,
    }),
    [absoluteChamber, mode, room, roomId, template.name],
  )

  useEffect(() => {
    completionHandled.current = false
    startSignaled.current = false
    clearSignaled.current = false
    spawnedSurvivalBosses.current = 0
    survivalBossPending.current = false
    setRoomPopulation(room.enemies.length)
    const timer = window.setTimeout(() => {
      setReady(true)
    }, 180)
    return () => {
      window.clearTimeout(timer)
      attackDirector.clear()
    }
  }, [attackDirector, encounterId, room.enemies.length, setRoomPopulation])

  /** Five-minute milestones spawn real bosses, including the 20-minute final
   * boss and increasingly reinforced bosses for every endless cycle after it. */
  useEffect(() => {
    if (!ready || phase !== 'playing') return
    const due = bossesDueBy(runElapsedSeconds)
    if (due <= spawnedSurvivalBosses.current) return
    // Milestones can stack while a long boss fight is in progress. They queue
    // instead of piling multiple bosses into one unreadable damage cloud.
    if (
      survivalBossPending.current ||
      [...runtime.enemies.values()].some((enemy) =>
        isSceneBoss(enemy.archetypeId),
      )
    )
      return
    const sequence = spawnedSurvivalBosses.current + 1
    const position = ringSpawnPosition(
      runtime.playerPosition.x,
      runtime.playerPosition.z,
      sequence,
      Math.max(4, due),
      sequence * 7,
    )
    const spawn: GeneratedEnemySpawn = {
      spawnId: `survival-boss-${sequence}`,
      position,
      archetypeId: survivalBossArchetype(sequence),
      eliteAffixId: survivalBossAffix(sequence),
    }
    spawnedSurvivalBosses.current = sequence
    survivalBossPending.current = true
    setBossReinforcements((current) => [...current, spawn])
    const state = useGameStore.getState()
    state.setRoomPopulation(state.aliveEnemies + 1)
    state.spawnEffect({
      id: `${encounterId}:${spawn.spawnId}:arrival`,
      kind: 'seal',
      position: [spawn.position.x, 0.05, spawn.position.z],
      color: '#ffffff',
      durationMs: 1_100,
      width: 3.2,
      label: sequence === FINAL_SURVIVAL_BOSS ? 'FINAL BOSS' : 'BOSS SIGNAL',
    })
    audioEngine.play('warning-boss')
  }, [encounterId, phase, ready, runElapsedSeconds])

  useEffect(() => {
    if (room.kind !== 'boss' || roomBossId === null || !ready) return

    // Hoisted declarations below cannot see the null check above, so the
    // narrowed value is captured here rather than re-read inside them.
    const bossArchetypeId = roomBossId
    let active = true
    let waveIndex = 0
    let timer = 0
    // Declarations, not consts: `schedule` calls `summonWave` and `summonWave`
    // calls `schedule`, so with `const` the pair only works because the first
    // call happens to sit below both. Hoisting removes that ordering trap.
    function schedule(delayMs: number) {
      timer = window.setTimeout(summonWave, delayMs)
    }
    function summonWave() {
      if (!active) return
      if (useGameStore.getState().phase !== 'playing') {
        schedule(500)
        return
      }
      const bossAlive = [...runtime.enemies.values()].some((enemy) =>
        isSceneBoss(enemy.archetypeId),
      )
      if (!bossAlive) return

      const activeReinforcements = [...runtime.enemies.keys()].filter((id) =>
        id.includes('-boss-reinforcement-'),
      ).length
      const lanes = canSpawnBossReinforcementWave(activeReinforcements)
        ? getBossReinforcementWave(
            bossArchetypeId,
            template.size.x / 2,
            template.size.z / 2,
            waveIndex,
          )
        : []
      const wave = lanes.map((lane, index): GeneratedEnemySpawn => ({
        spawnId: `boss-reinforcement-${waveIndex}-${lane.side}-${index}`,
        position: lane.position,
        archetypeId: lane.archetypeId,
        eliteAffixId: null,
      }))

      if (wave.length > 0) {
        waveIndex += 1
        setBossReinforcements((current) => [...current, ...wave])
        const state = useGameStore.getState()
        state.setRoomPopulation(state.aliveEnemies + wave.length)
        // Arrival seals are pooled, but publishing one store event per body is
        // still needless work for twelve-unit late waves. Four evenly sampled
        // seals communicate the ring arrival without scaling VFX traffic with
        // swarm size.
        const sealStride = Math.max(1, Math.ceil(wave.length / 4))
        for (let index = 0; index < wave.length; index += sealStride) {
          const spawn = wave[index]
          if (!spawn) continue
          spawnEffect({
            id: `${encounterId}:${spawn.spawnId}:arrival`,
            kind: 'seal',
            position: [spawn.position.x, 0.05, spawn.position.z],
            color: '#ffffff',
            durationMs: 900,
          })
        }
        audioEngine.play('warning-boss')
      }
      schedule(BOSS_REINFORCEMENT_INTERVAL_MS)
    }

    schedule(BOSS_REINFORCEMENT_FIRST_WAVE_MS)
    return () => {
      active = false
      window.clearTimeout(timer)
    }
  }, [
    encounterId,
    ready,
    roomBossId,
    room.kind,
    spawnEffect,
    template.size.x,
    template.size.z,
  ])

  /**
   * The survival clock. Reaching zero completes a normal sector.
   *
   * It accumulates its own ticks rather than sampling a wall clock, so a
   * paused game, a reward screen, or a backgrounded tab cannot burn the sector
   * down while the player is not actually playing it. A 200ms tick is plenty
   * for a countdown read in whole seconds and keeps this off the render loop.
   */
  /**
   * The run clock.
   *
   * There are no sectors, so nothing here completes — this counts up for as
   * long as the player lives, and every difficulty curve reads off it. It
   * accumulates its own ticks rather than sampling a wall clock, so a pause,
   * a level-up choice, or a backgrounded tab cannot burn the run down while
   * the player is not actually playing it.
   */
  useEffect(() => {
    if (!ready) return
    const tick = window.setInterval(() => {
      const state = useGameStore.getState()
      if (state.phase !== 'playing') return
      // Accumulate off the store rather than a local of our own. Both count
      // ticks — neither samples a wall clock — but a private accumulator makes
      // this the second writer of a value the store already owns, and it wins
      // every 200ms: anything else that moves the clock is silently undone
      // before the next wave reads it.
      state.setRunElapsedSeconds(state.runElapsedSeconds + RUN_TICK_MS / 1_000)
      if (state.healthRegenPerSecond > 0) {
        state.healPlayer(state.healthRegenPerSecond * (RUN_TICK_MS / 1_000))
      }
    }, RUN_TICK_MS)
    return () => window.clearInterval(tick)
  }, [ready])

  const removeBossReinforcement = useCallback((spawnId: string) => {
    setBossReinforcements((current) =>
      current.filter((spawn) => spawn.spawnId !== spawnId),
    )
  }, [])

  const markSurvivalBossRegistered = useCallback(() => {
    survivalBossPending.current = false
  }, [])

  /**
   * The survivor spawner.
   *
   * A normal sector is no longer a fixed roster to clear — with no walls the
   * player could simply walk away from one. Bodies now arrive continuously on
   * a ring around the player, from outside the frame, tightening as the
   * sector's clock runs down. See `survivorWaves.ts` for the pacing curves.
   *
   * The cast comes from the clock, not from the room. A survival run never
   * leaves the chamber it started in, so reading the roster off that chamber
   * pinned every run in every arena to the same two archetypes for its whole
   * length; `survivalRoster` widens the pool as the run gets older instead.
   */
  useEffect(() => {
    if (room.kind === 'boss' || !ready) return

    let active = true
    let waveIndex = 0
    let timer = 0

    function schedule(delayMs: number) {
      timer = window.setTimeout(summonWave, delayMs)
    }
    function summonWave() {
      if (!active) return
      const state = useGameStore.getState()
      if (state.phase !== 'playing') {
        schedule(400)
        return
      }
      const elapsed = state.runElapsedSeconds

      // At cap, skip this arrival rather than queueing it. A backlog that
      // drains the instant a kill lands is worse than a brief lull.
      const headroom = activeEnemyCap(elapsed) - state.aliveEnemies
      if (headroom > 0) {
        const size = Math.min(headroom, waveSize(elapsed))
        const roster = survivalRoster(elapsed)
        const wave: GeneratedEnemySpawn[] = []
        for (let index = 0; index < size; index += 1) {
          const position = ringSpawnPosition(
            runtime.playerPosition.x,
            runtime.playerPosition.z,
            index,
            size,
            waveIndex,
          )
          wave.push({
            spawnId: `survivor-${waveIndex}-${index}`,
            position,
            archetypeId: roster[(waveIndex + index) % roster.length],
            eliteAffixId: survivalEliteAffix(elapsed, waveIndex, index),
          })
        }
        waveIndex += 1
        setBossReinforcements((current) => [...current, ...wave])
        state.setRoomPopulation(state.aliveEnemies + wave.length)
        for (const spawn of wave) {
          spawnEffect({
            id: `${encounterId}:${spawn.spawnId}:arrival`,
            kind: 'seal',
            position: [spawn.position.x, 0.05, spawn.position.z],
            color: '#ffffff',
            durationMs: 700,
          })
        }
      }
      schedule(spawnIntervalMs(elapsed))
    }

    schedule(600)
    return () => {
      active = false
      window.clearTimeout(timer)
    }
  }, [absoluteChamber, encounterId, ready, room.kind, spawnEffect])

  useEffect(() => {
    if (!ready || phase !== 'playing' || startSignaled.current) {
      return
    }

    startSignaled.current = true
    const event: EncounterPresentationEvent = {
      id: `${encounterId}:start`,
      kind: 'start',
      ...encounterPresentation,
    }
    onEncounterEvent?.(event)
    spawnEffect({
      id: `${event.id}:sigil`,
      kind: 'burst',
      position: [playerSpawn.x, 0.08, playerSpawn.z],
      color: '#7fffef',
      durationMs: 620,
      variant: 'sigil',
    })
    // No exit ping any more: the objective is a clock, not a place. The
    // banner and the HUD countdown carry it.
    audioEngine.play('room-start')
  }, [
    room.kind,
    encounterId,
    encounterPresentation,
    onEncounterEvent,
    phase,
    playerSpawn.x,
    playerSpawn.z,
    ready,
    room,
    room.enemies.length,
    spawnEffect,
  ])

  // Endless: nothing completes. Bodies arrive for as long as the player is
  // alive, so there is no objective to meet and no next room to advance to —
  // the run ends only on death, and its length is the score. The arena had a
  // completion branch here (shrine / rune reward / route / victory); every
  // path through it was unreachable once the objective became a clock, so it
  // was removed rather than left as a dead switch.

  return (
    <>
      <RoomEnvironment
        room={template}
        biomeId={'biomeId' in room ? room.biomeId : template.biomeId}
        risk={'routeRisk' in room ? room.routeRisk : undefined}
        mutationId={'mutationId' in room ? room.mutationId : undefined}
      />
      {/*
        No exit gate. A gate is a fixed point, and the arena no longer has
        fixed points — the sector ends on its clock wherever the player
        happens to be standing.
      */}
      <Player spawn={playerSpawn} operatorFeedRef={operatorFeedRef} />
      {/*
        The optic field is the game's standing rule, so its cone is always
        drawn: it is the only thing that tells the player where the rule
        currently reaches.
      */}
      <VisionCone />
      <PlayerProjectileSystem />
      {[...enemySpawns, ...bossReinforcements].map((spawn) => (
        <Enemy
          key={spawn.spawnId}
          id={`${room.index}-${spawn.spawnId}`}
          archetypeId={spawn.archetypeId}
          position={spawn.position}
          waypoints={waypoints}
          attackDirector={attackDirector}
          encounterTier={encounterTier}
          difficultyRank={difficulty}
          absoluteChamber={absoluteChamber}
          healthMultiplier={
            spawn.spawnId.startsWith('survival-boss-')
              ? scaling.healthMultiplier *
                enemyHealthMultiplier(runElapsedSeconds) *
                bossHealthMultiplier(
                  Number(spawn.spawnId.replace('survival-boss-', '')),
                )
              : spawn.archetypeId === 'blind-thrall'
                ? scaling.weakEnemyHealthMultiplier *
                  enemyHealthMultiplier(runElapsedSeconds)
                : scaling.healthMultiplier *
                  enemyHealthMultiplier(runElapsedSeconds)
          }
          damageMultiplier={enemyDamageMultiplier(runElapsedSeconds)}
          eliteAffixId={spawn.eliteAffixId}
          mutationId={'mutationId' in room ? room.mutationId : null}
          onRegistered={
            spawn.spawnId.startsWith('survival-boss-')
              ? markSurvivalBossRegistered
              : undefined
          }
          onDefeated={
            bossReinforcements.some(
              (dynamic) => dynamic.spawnId === spawn.spawnId,
            )
              ? () => removeBossReinforcement(spawn.spawnId)
              : undefined
          }
        />
      ))}
      <ShardPickups />
      <Projectiles />
      <Effects />
      <DeathIris />
    </>
  )
}

function SceneContent({
  onEncounterEvent,
  operatorFeedRef,
}: {
  onEncounterEvent?: (event: EncounterPresentationEvent) => void
  operatorFeedRef?: RefObject<HTMLDivElement | null>
}) {
  const seed = useGameStore((state) => state.seed)
  const difficulty = useGameStore((state) => state.difficulty)
  const roomIndex = useGameStore((state) => state.roomIndex)
  const runId = useGameStore((state) => state.runId)
  const phase = useGameStore((state) => state.phase)
  const generatedRun = useGameStore((state) => state.generatedRun)
  const currentNodeId = useGameStore((state) => state.currentNodeId)
  const fallbackRun = useMemo(
    () => createRun(seed || 'STILLSEEN', difficulty),
    [difficulty, seed],
  )
  const run = generatedRun ?? fallbackRun
  const requestedNodeId =
    currentNodeId ?? (generatedRun ? generatedRun.startNodeId : null)
  const room =
    (requestedNodeId
      ? run.rooms.find((candidate) => candidate.id === requestedNodeId)
      : undefined) ??
    run.rooms[roomIndex] ??
    run.rooms[0]

  if (!room) return null

  return (
    <Physics
      key={`${runId}-${room.id ?? room.index}`}
      gravity={[0, -20, 0]}
      timeStep={1 / 60}
      paused={phase !== 'playing'}
      interpolate
      debug={import.meta.env.VITE_PHYSICS_DEBUG === '1'}
    >
      <RoomEncounter
        room={room}
        runId={runId}
        onEncounterEvent={onEncounterEvent}
        operatorFeedRef={operatorFeedRef}
      />
    </Physics>
  )
}

function GameSceneImpl({
  onLoadProgress,
  onReady,
  onFatalError,
  preparationKey,
  onPreparationReady,
  onEncounterEvent,
  operatorFeedRef,
  warmup = true,
}: GameSceneProps = {}) {
  const [contentReady, setContentReady] = useState(false)
  const [postProcessingReady, setPostProcessingReady] = useState(false)
  const [renderQualityFactor, setRenderQualityFactor] = useState(1)
  const markContentReady = useCallback(() => setContentReady(true), [])
  const markPostProcessingReady = useCallback(
    () => setPostProcessingReady(true),
    [],
  )

  useEffect(() => {
    onLoadProgress?.({
      stage: 'scene-bootstrap',
      progress: 0.08,
      message: '게임 장면을 구성하는 중',
    })
  }, [onLoadProgress])

  return (
    <div className="stillseen-canvas" data-testid="game-canvas">
      <SceneErrorBoundary onError={onFatalError}>
        <Canvas
          shadows="basic"
          dpr={[0.6, 1.5]}
          camera={{ position: [0, 14.2, 10.2], fov: 44, near: 0.1, far: 110 }}
          gl={{
            // The finishing pass already applies SMAA. Disabling WebGL MSAA
            // avoids shading every post-processed pixel twice.
            antialias: false,
            powerPreference: 'high-performance',
            alpha: false,
          }}
          onCreated={({ gl }) => {
            try {
              gl.outputColorSpace = SRGBColorSpace
              // Neutral tone mapping keeps the authored cyan/gold/coral palette
              // aligned with the DOM UI instead of bleaching it through ACES.
              gl.toneMapping = NeutralToneMapping
              gl.toneMappingExposure = 0.96
              onLoadProgress?.({
                stage: 'webgl-context',
                progress: 0.28,
                message: '렌더링 장치 연결 완료',
              })
            } catch (cause) {
              onFatalError?.(toError(cause, 'WebGL initialization failed.'))
            }
          }}
        >
          <FrameBudgetProbe />
          {/*
            60fps defence. PerformanceMonitor watches the actual frame rate and
            AdaptiveDpr drops resolution rather than dropping frames, so a
            weaker GPU loses some sharpness instead of responsiveness. The 0.6
            floor remains comfortably above the intentionally pixelated range.
          */}
          <PerformanceMonitor
            onChange={({ factor }) => {
              setPerformanceFactor(factor)
              setRenderQualityFactor((current) =>
                Math.abs(current - factor) >= 0.05 ? factor : current,
              )
            }}
          />
          <AdaptiveDpr pixelated={false} />
          <color attach="background" args={[SCENE_BACKDROP_COLOR]} />
          {/* Pushed back and lightened: the diorama blur now does the depth work, and dense fog would fight it. */}
          <fog attach="fog" args={[SCENE_BACKDROP_COLOR, 27, 68]} />
          {/*
            High-key diorama lighting, in the Echoes of Wisdom sense: the model
            is lit like an object on a table rather than a place you are inside.
            Ambient and hemisphere carry most of the exposure so nothing falls
            to black, and the key is softened to a shaping light rather than the
            source of the image. Shadows stay present but light — that family
            never crushes a shadow, which is most of why it reads as a toy.
          */}
          {/*
            Near-neutral fill. These used to be cyan (#8cb7bf / #c7e9ef /
            #d5f4ff), which was invisible on a near-black deck but turns a
            light grey one mint — the surface stopped reading as grey the
            moment it had enough luminance to take a tint. Teal now enters the
            frame only as the rim light and the gaze cone, so it means
            "optics", not "everything".
          */}
          <ambientLight intensity={0.34} color="#eef2f3" />
          {/* Ground bounce, not a void: the deck is bright enough to throw
              light back up under props instead of swallowing their undersides. */}
          <hemisphereLight args={['#ffffff', '#828e93', 0.5]} />
          <directionalLight
            castShadow={renderQualityFactor >= 0.25}
            position={[-10, 17, 7]}
            intensity={1.55}
            color="#ffffff"
            shadow-mapSize={[1024, 1024]}
            shadow-camera-left={-16}
            shadow-camera-right={16}
            shadow-camera-top={16}
            shadow-camera-bottom={-16}
            shadow-bias={-0.00035}
            shadow-normalBias={0.025}
          />
          {/*
            Back-rim from the opposite side. Pushed up so SD silhouettes get a
            cool edge separating them from the ground — the single cheapest way
            to make a chibi model read as drawn rather than extruded.
          */}
          <directionalLight
            position={[9, 10, -11]}
            intensity={0.5}
            color="#28e0d0"
          />
          <directionalLight
            position={[-7, 5, -9]}
            intensity={0.18}
            color="#7fffef"
          />
          <Suspense fallback={null}>
            <SceneContent
              onEncounterEvent={onEncounterEvent}
              operatorFeedRef={operatorFeedRef}
            />
            <ContentReadySignal onReady={markContentReady} />
            <ScenePreparation
              preparationKey={preparationKey}
              onReady={onPreparationReady}
              onFatalError={onFatalError}
            />
          </Suspense>
          <PostProcessing
            onReady={markPostProcessingReady}
            performanceFactor={renderQualityFactor}
          />
          <SceneWarmup
            contentReady={contentReady}
            postProcessingReady={postProcessingReady}
            enabled={warmup}
            onLoadProgress={onLoadProgress}
            onReady={onReady}
            onFatalError={onFatalError}
          />
        </Canvas>
      </SceneErrorBoundary>
    </div>
  )
}

/**
 * Memoized because App renders it alongside state that changes during combat.
 * Callback and scalar props are stable at the call site, so the
 * comparison actually bails out rather than re-pushing the whole scene graph.
 */
export const GameScene = memo(GameSceneImpl)
