/* eslint-disable react-refresh/only-export-components -- dropExperienceCore is the
   spawner half of this system; splitting it into its own module would leave
   two files that only make sense read together. */
import { useFrame } from '@react-three/fiber'
import { useRef } from 'react'
import { Color, type Mesh, type MeshBasicMaterial, type Group } from 'three'

import { makeRuntimeId, useGameStore } from '../runtime/gameStore'
import { runtime } from '../runtime/registry'
import { audioEngine } from '../runtime/audio'
import { applyHitstop } from './hitstop'
import { TOON_PALETTE } from './toonMaterials'
import { experienceForKill, type KillKind } from '../game/endlessRun'

/**
 * Kill loot. Every defeated hostile scatters data shards; walk near one and
 * it flies to the player and banks score on contact. This is the escape
 * game's whole risk economy made physical — the reward for a fight lies on
 * the floor of the fight, and collecting it costs the seconds the fight
 * already made dangerous.
 *
 * Rendering uses a fixed mesh pool driven imperatively from useFrame: shards
 * spawn and die every few seconds in combat, and cycling React children at
 * that rate would churn the reconciler for objects with a two-second life.
 */
export const XP_CORE_POOL_SIZE = 128
/** Seconds before a fresh shard can be collected — lets the scatter read. */
const SHARD_ARM_SECONDS = 0.3
/** Inside this range an armed shard homes on the player. */
const SHARD_COLLECT_RADIUS = 0.72
const SHARD_HOMING_SPEED = 11
const SHARD_COLOR = new Color(TOON_PALETTE.cyanLight)

export function ShardPickups() {
  const groupRef = useRef<Group>(null)
  const poolRef = useRef<(Mesh | null)[]>([])
  // Per-shard homing displacement, keyed by shard id. A ref, not memo state:
  // it is frame-loop scratch that React must never render from.
  const homingRef = useRef(new Map<string, { x: number; z: number }>())
  const visualTime = useRef(0)

  useFrame((_, rawDelta) => {
    const delta = applyHitstop(rawDelta)
    visualTime.current += delta
    const meshes = poolRef.current
    const shards = runtime.shards
    const store = useGameStore.getState()
    const playing = store.phase === 'playing'
    const time = visualTime.current

    for (let index = 0; index < XP_CORE_POOL_SIZE; index += 1) {
      const mesh = meshes[index]
      if (!mesh) continue
      const shard = shards[index]
      if (!shard) {
        mesh.visible = false
        continue
      }

      const age = runtime.elapsed - shard.bornAt
      const drift = homingRef.current.get(shard.id) ?? { x: 0, z: 0 }
      const shardX = shard.x + drift.x
      const shardZ = shard.z + drift.z

      if (playing && age >= SHARD_ARM_SECONDS) {
        const dx = runtime.playerPosition.x - shardX
        const dz = runtime.playerPosition.z - shardZ
        const distance = Math.hypot(dx, dz)
        if (distance <= SHARD_COLLECT_RADIUS) {
          shards.splice(index, 1)
          homingRef.current.delete(shard.id)
          store.gainExperience(shard.value)
          store.spawnEffect({
            id: makeRuntimeId('shard-collect'),
            kind: 'burst',
            position: [shardX, 0.4, shardZ],
            color: TOON_PALETTE.cyanLight,
            durationMs: 300,
            variant: 'rune',
            label: `+${shard.value} XP`,
          })
          audioEngine.play('reward')
          mesh.visible = false
          index -= 1
          continue
        }
        if (distance <= store.pickupRadius && distance > 0.001) {
          const step = (SHARD_HOMING_SPEED * delta) / distance
          homingRef.current.set(shard.id, {
            x: drift.x + dx * step,
            z: drift.z + dz * step,
          })
        }
      }

      mesh.visible = true
      // Each pooled mesh owns its material, so the drop's kind can be read
      // off its colour without swapping materials or re-rendering.
      const material = mesh.material as MeshBasicMaterial
      material.color.copy(SHARD_COLOR)
      mesh.scale.setScalar(
        Math.min(1.65, 0.9 + Math.log2(shard.value + 1) * 0.14),
      )
      mesh.position.set(
        shardX,
        0.42 + Math.sin(time * 3.4 + shard.bornAt * 7) * 0.07,
        shardZ,
      )
      mesh.rotation.y = time * 1.9 + shard.bornAt
    }
  })

  return (
    <group ref={groupRef} name="shard-pickups">
      {Array.from({ length: XP_CORE_POOL_SIZE }, (_, index) => (
        <mesh
          key={index}
          ref={(mesh) => {
            poolRef.current[index] = mesh
          }}
          visible={false}
        >
          <octahedronGeometry args={[0.15, 0]} />
          {/* toneMapped: false — shards are light, so the selective bloom
              pass gives every drop its own small halo on the deck. */}
          <meshBasicMaterial
            color={TOON_PALETTE.cyanLight}
            toneMapped={false}
          />
        </mesh>
      ))}
    </group>
  )
}

/**
 * Scatters kill loot around a defeated enemy. Values and counts are the
 * risk-pay knob: an ordinary kill drops two shards, elites add a third.
 */
export function dropExperienceCore(
  x: number,
  z: number,
  kind: KillKind = 'normal',
): void {
  const value = experienceForKill(kind)
  if (runtime.shards.length >= XP_CORE_POOL_SIZE) {
    let nearest = runtime.shards[0]
    let nearestDistanceSq = Number.POSITIVE_INFINITY
    for (const core of runtime.shards) {
      const dx = core.x - x
      const dz = core.z - z
      const distanceSq = dx * dx + dz * dz
      if (distanceSq < nearestDistanceSq) {
        nearest = core
        nearestDistanceSq = distanceSq
      }
    }
    if (nearest) nearest.value += value
    return
  }
  runtime.shards.push({
    id: makeRuntimeId('xp-core'),
    x,
    z,
    bornAt: runtime.elapsed,
    value,
  })
}
