import { useFrame } from '@react-three/fiber'
import { useRapier } from '@react-three/rapier'
import { useEffect, useRef, useState } from 'react'
import {
  BufferAttribute,
  BufferGeometry,
  DoubleSide,
  AdditiveBlending,
  DynamicDrawUsage,
  Group,
} from 'three'

import { useGameStore } from '../runtime/gameStore'
import { runtime } from '../runtime/registry'
import { getPerformanceFactor } from './frameBudget'
import { TOON_PALETTE } from './toonMaterials'
import { FULL_ENGAGEMENT_TARGETS, getVisionConeStyle } from './visionConeStyle'

const SEGMENTS = 48
const UPDATE_INTERVAL = 1 / 20
const GUIDE_RAY_FRACTIONS: readonly number[] = []
const ACCENT_SEGMENTS = SEGMENTS + 2 + GUIDE_RAY_FRACTIONS.length + 2
/**
 * Height the sight rays are cast at.
 *
 * Must match the height Enemy.tsx casts its line-of-sight segment at, or the
 * drawn cone and what the gaze can actually reach disagree: a low prop would
 * carve a shadow out of the cone while enemies standing in that shadow still
 * froze. The cone is drawn flat on the deck, but it represents eye-level
 * sight.
 */
export const VISION_RAY_Y = 0.72

const FILL_Y = 0.032
const ACCENT_Y = 0.052
const EDGE_WIDTH = 0.1
const GUIDE_WIDTH = 0.008
/** How much of the centre brightness survives at the cone's rim. */
const CONE_RIM_FALLOFF = 0.22

function createDynamicGeometry(positionCount: number): BufferGeometry {
  const positions = new Float32Array(positionCount * 3)
  const attribute = new BufferAttribute(positions, 3)
  attribute.setUsage(DynamicDrawUsage)
  const geometry = new BufferGeometry()
  geometry.setAttribute('position', attribute)
  return geometry
}

/**
 * Radial falloff baked into vertex colours.
 *
 * The fill is a triangle fan: for segment i the vertices are [centre, previous
 * rim, current rim]. Weighting the centre vertex bright and both rim vertices
 * dim gives the interior a gradient that reads as light thrown from the player
 * rather than a flat translucent wash. It is written once — only positions
 * change per frame — so this costs nothing at runtime.
 */
function createFillFalloff(segments: number): BufferAttribute {
  const colors = new Float32Array(segments * 3 * 3)
  for (let segment = 0; segment < segments; segment += 1) {
    const offset = segment * 9
    colors[offset] = 1
    colors[offset + 1] = 1
    colors[offset + 2] = 1
    for (let rim = 1; rim <= 2; rim += 1) {
      const rimOffset = offset + rim * 3
      colors[rimOffset] = CONE_RIM_FALLOFF
      colors[rimOffset + 1] = CONE_RIM_FALLOFF
      colors[rimOffset + 2] = CONE_RIM_FALLOFF
    }
  }
  return new BufferAttribute(colors, 3)
}

function writeRibbonSegment(
  target: Float32Array,
  segmentIndex: number,
  startX: number,
  startZ: number,
  endX: number,
  endZ: number,
  width: number,
): void {
  const dx = endX - startX
  const dz = endZ - startZ
  const length = Math.hypot(dx, dz)
  const halfWidth = width * 0.5
  const normalX = length > 0.0001 ? (-dz / length) * halfWidth : 0
  const normalZ = length > 0.0001 ? (dx / length) * halfWidth : 0
  const offset = segmentIndex * 18

  target[offset] = startX + normalX
  target[offset + 1] = ACCENT_Y
  target[offset + 2] = startZ + normalZ
  target[offset + 3] = startX - normalX
  target[offset + 4] = ACCENT_Y
  target[offset + 5] = startZ - normalZ
  target[offset + 6] = endX + normalX
  target[offset + 7] = ACCENT_Y
  target[offset + 8] = endZ + normalZ

  target[offset + 9] = endX + normalX
  target[offset + 10] = ACCENT_Y
  target[offset + 11] = endZ + normalZ
  target[offset + 12] = startX - normalX
  target[offset + 13] = ACCENT_Y
  target[offset + 14] = startZ - normalZ
  target[offset + 15] = endX - normalX
  target[offset + 16] = ACCENT_Y
  target[offset + 17] = endZ - normalZ
}

export function VisionCone() {
  const [geometry] = useState(() => {
    const fill = createDynamicGeometry(SEGMENTS * 3)
    fill.setAttribute('color', createFillFalloff(SEGMENTS))
    return fill
  })
  const [accentGeometry] = useState(() =>
    createDynamicGeometry(ACCENT_SEGMENTS * 6),
  )
  const endpointXs = useRef(new Float32Array(SEGMENTS + 1))
  const endpointZs = useRef(new Float32Array(SEGMENTS + 1))
  const { world, rapier } = useRapier()
  const rayRef = useRef(
    new rapier.Ray({ x: 0, y: VISION_RAY_Y, z: 0 }, { x: 1, y: 0, z: 0 }),
  )
  const groupRef = useRef<Group>(null)
  const accumulator = useRef(0)
  const visionRange = useGameStore((state) => state.stats.visionRange)
  const visionFovDeg = useGameStore((state) => state.stats.visionFovDeg)
  const visionAssist = useGameStore((state) => state.settings.visionAssist)
  const observedEnemies = useGameStore((state) => state.observedEnemies)
  const reducedMotion = useGameStore((state) => state.settings.reducedMotion)
  const style = getVisionConeStyle(
    visionAssist,
    reducedMotion ? 0 : observedEnemies / FULL_ENGAGEMENT_TARGETS,
  )
  // One identity colour whether or not the field holds anything: what it is
  // holding reads through brightness, never a hue change.
  const opticColor = TOON_PALETTE.cyan
  const opticAccentColor = TOON_PALETTE.cyanLight

  useEffect(() => {
    return () => {
      geometry.dispose()
      accentGeometry.dispose()
    }
  }, [accentGeometry, geometry])

  useFrame((_, delta) => {
    // Unthrottled: the apex sits exactly on the player every single frame.
    // Only the cone's shape is rebuilt on the interval below, so occlusion can
    // lag a little without the origin ever drifting behind a moving player.
    const group = groupRef.current
    if (group) {
      group.position.set(runtime.playerPosition.x, 0, runtime.playerPosition.z)
    }

    // The buffers are sized at construction, so a struggling frame stretches
    // the rebuild interval rather than dropping segments.
    const interval = UPDATE_INTERVAL / Math.max(0.4, getPerformanceFactor())
    accumulator.current += delta
    if (accumulator.current < interval) return
    accumulator.current %= interval

    // Rays are cast from where the player actually is; the geometry is written
    // in LOCAL space with its apex at the origin, and the group below is moved
    // onto the player every frame. Building the fan in world space meant the
    // apex only caught up on the throttled rebuild, so it visibly lagged and
    // snapped behind a moving player.
    const originX = runtime.playerPosition.x
    const originZ = runtime.playerPosition.z
    const centerX = 0
    const centerZ = 0
    const facingAngle = Math.atan2(
      runtime.playerFacing.z,
      runtime.playerFacing.x,
    )
    const clampedFovDeg = Math.min(360, Math.max(1, visionFovDeg))
    const halfAngle = (clampedFovDeg * Math.PI) / 360
    const queryFlags =
      rapier.QueryFilterFlags.EXCLUDE_DYNAMIC |
      rapier.QueryFilterFlags.EXCLUDE_KINEMATIC
    const attribute = geometry.getAttribute('position')
    const accentAttribute = accentGeometry.getAttribute('position')
    if (
      !(attribute instanceof BufferAttribute) ||
      !(accentAttribute instanceof BufferAttribute)
    ) {
      return
    }
    const positions = attribute.array as Float32Array
    const accentPositions = accentAttribute.array as Float32Array
    const ray = rayRef.current
    let previousX = centerX
    let previousZ = centerZ

    ray.origin.x = originX
    ray.origin.y = VISION_RAY_Y
    ray.origin.z = originZ

    for (let index = 0; index <= SEGMENTS; index += 1) {
      const angle = facingAngle - halfAngle + (index / SEGMENTS) * halfAngle * 2
      ray.dir.x = Math.cos(angle)
      ray.dir.y = 0
      ray.dir.z = Math.sin(angle)
      const hit = world.castRay(ray, visionRange, true, queryFlags)
      const distance = hit ? Math.max(0, hit.timeOfImpact - 0.06) : visionRange
      const endpointX = centerX + ray.dir.x * distance
      const endpointZ = centerZ + ray.dir.z * distance
      endpointXs.current[index] = endpointX
      endpointZs.current[index] = endpointZ

      if (index > 0) {
        const offset = (index - 1) * 9
        positions[offset] = centerX
        positions[offset + 1] = FILL_Y
        positions[offset + 2] = centerZ
        positions[offset + 3] = previousX
        positions[offset + 4] = FILL_Y
        positions[offset + 5] = previousZ
        positions[offset + 6] = endpointX
        positions[offset + 7] = FILL_Y
        positions[offset + 8] = endpointZ
      }

      previousX = endpointX
      previousZ = endpointZ
    }

    let accentIndex = 0
    writeRibbonSegment(
      accentPositions,
      accentIndex,
      centerX,
      centerZ,
      endpointXs.current[0],
      endpointZs.current[0],
      EDGE_WIDTH,
    )
    accentIndex += 1
    for (let index = 0; index < SEGMENTS; index += 1) {
      writeRibbonSegment(
        accentPositions,
        accentIndex,
        endpointXs.current[index],
        endpointZs.current[index],
        endpointXs.current[index + 1],
        endpointZs.current[index + 1],
        EDGE_WIDTH,
      )
      accentIndex += 1
    }
    writeRibbonSegment(
      accentPositions,
      accentIndex,
      endpointXs.current[SEGMENTS],
      endpointZs.current[SEGMENTS],
      centerX,
      centerZ,
      EDGE_WIDTH,
    )
    accentIndex += 1

    for (const fraction of GUIDE_RAY_FRACTIONS) {
      const sampleIndex = Math.round(fraction * SEGMENTS)
      const endpointX = endpointXs.current[sampleIndex]
      const endpointZ = endpointZs.current[sampleIndex]
      const dx = endpointX - centerX
      const dz = endpointZ - centerZ
      const distance = Math.hypot(dx, dz)
      const inverseDistance = distance > 0.0001 ? 1 / distance : 0
      const startDistance = Math.min(0.62, distance * 0.2)
      const endDistance = Math.max(startDistance, distance - 0.14)
      writeRibbonSegment(
        accentPositions,
        accentIndex,
        centerX + dx * inverseDistance * startDistance,
        centerZ + dz * inverseDistance * startDistance,
        centerX + dx * inverseDistance * endDistance,
        centerZ + dz * inverseDistance * endDistance,
        GUIDE_WIDTH,
      )
      accentIndex += 1
    }

    const facingX = Math.cos(facingAngle)
    const facingZ = Math.sin(facingAngle)
    const sideX = -facingZ
    const sideZ = facingX
    const cueTipX = centerX + facingX * 1.16
    const cueTipZ = centerZ + facingZ * 1.16
    const cueBaseX = centerX + facingX * 0.74
    const cueBaseZ = centerZ + facingZ * 0.74
    writeRibbonSegment(
      accentPositions,
      accentIndex,
      cueBaseX + sideX * 0.24,
      cueBaseZ + sideZ * 0.24,
      cueTipX,
      cueTipZ,
      GUIDE_WIDTH * 1.45,
    )
    accentIndex += 1
    writeRibbonSegment(
      accentPositions,
      accentIndex,
      cueTipX,
      cueTipZ,
      cueBaseX - sideX * 0.24,
      cueBaseZ - sideZ * 0.24,
      GUIDE_WIDTH * 1.45,
    )

    attribute.needsUpdate = true
    accentAttribute.needsUpdate = true
  })

  return (
    <group ref={groupRef}>
      <mesh geometry={geometry} frustumCulled={false} renderOrder={1}>
        <meshBasicMaterial
          blending={AdditiveBlending}
          color={opticColor}
          depthWrite={false}
          opacity={style.fillOpacity}
          polygonOffset
          polygonOffsetFactor={-1}
          side={DoubleSide}
          toneMapped={false}
          transparent
          vertexColors
        />
      </mesh>
      <mesh geometry={accentGeometry} frustumCulled={false} renderOrder={2}>
        <meshBasicMaterial
          blending={AdditiveBlending}
          color={opticAccentColor}
          depthWrite={false}
          opacity={style.accentOpacity}
          polygonOffset
          polygonOffsetFactor={-2}
          side={DoubleSide}
          toneMapped={false}
          transparent
        />
      </mesh>
    </group>
  )
}
