import { Quaternion, Vector3 } from 'three'

const UP = new Vector3(0, 1, 0)

/** Authored slash sprite basis: clockwise quarter-turn on the ground plane. */
export const SLASH_ART_ROTATION_Z = -Math.PI / 2

/**
 * All authored actors and forward-offset effects in STILLSEEN use local -Z as their
 * forward axis. Three's usual atan2(x, z) helper aligns local +Z, so applying
 * it directly turns those visuals exactly 180 degrees away from gameplay aim.
 */
export function yawFromNegativeZForward(direction: {
  x: number
  z: number
}): number {
  if (!Number.isFinite(direction.x) || !Number.isFinite(direction.z)) return 0
  if (Math.abs(direction.x) + Math.abs(direction.z) < 1e-8) return 0
  return Math.atan2(-direction.x, -direction.z)
}

export function quaternionFromNegativeZForward(
  direction: { x: number; z: number },
  target = new Quaternion(),
): Quaternion {
  return target.setFromAxisAngle(UP, yawFromNegativeZForward(direction))
}
