import { useFrame } from '@react-three/fiber'

import { useGameStore } from '../runtime/gameStore'
import { runtime } from '../runtime/registry'
import { recordFrame } from './frameBudget'
import { applyHitstop, tickHitstop } from './hitstop'

/**
 * The scene's once-per-frame driver, running before every other subscriber.
 *
 * R3F sorts useFrame subscribers by ascending priority, so -1000 runs first.
 * That ordering is what makes this the right place to advance the hit-stop
 * clock: every enemy scales its own delta by the current hold, and the hold
 * has to be consumed exactly once per frame rather than once per enemy.
 * Frame sampling lives here for the same guarantee — one sample per frame.
 */
export function FrameBudgetProbe() {
  useFrame((_, delta) => {
    tickHitstop(delta)
    // Loading, shader preparation, reward overlays, and route selection do not
    // accept combat input. Keep the responsiveness budget scoped to frames in
    // which the player can actually move, aim, or attack.
    if (useGameStore.getState().phase === 'playing') {
      runtime.presentationElapsed += applyHitstop(delta)
      recordFrame(delta)
    }
  }, -1000)
  return null
}
