import { useFrame } from '@react-three/fiber'
import { useEffect, useMemo, useRef } from 'react'
import {
  Color,
  DynamicDrawUsage,
  InstancedMesh,
  MathUtils,
  Object3D,
  Vector3,
} from 'three'

import { audioEngine } from '../runtime/audio'
import {
  deriveGlobalWeaponModifiers,
  getEquippedWeapons,
  resolveWeaponStats,
  type RunWeapon,
  type WeaponId,
  type WeaponStats,
} from '../game/runBuild'
import { useGameStore } from '../runtime/gameStore'
import { runtime } from '../runtime/registry'
import {
  PLAYER_PROJECTILE_POOL_SIZE,
  playerProjectilePool,
  type PlayerProjectileKind,
  type ProjectileTarget,
} from './playerProjectilePool'
import {
  getProjectileBloomColor,
  PROJECTILE_BLOOM_TONE_MAPPED,
} from './projectileVisual'
import { TOON_PALETTE } from './toonMaterials'
import { ORBIT_RADIUS, ORBIT_WORLD_Y, orbitAngle } from './weapons/weaponHover'
import { findNearestEnemy } from './weapons/weaponTargeting'
import { applyHitstop } from './hitstop'

const CYAN = new Color(TOON_PALETTE.cyanLight)
const WHITE = new Color('#ffffff')
const CYAN_BLOOM = getProjectileBloomColor(TOON_PALETTE.cyanLight)
const WHITE_BLOOM = getProjectileBloomColor('#edf7f5')
const GREY_BLOOM = getProjectileBloomColor('#8b999c')
const Y_AXIS = new Vector3(0, 1, 0)
function projectileKind(weaponId: WeaponId): PlayerProjectileKind {
  switch (weaponId) {
    case 'scatter-cannon':
      return 'pellet'
    case 'micro-missiles':
      return 'missile'
    case 'rail-lance':
      return 'rail'
    case 'arc-emitter':
      return 'arc'
    case 'orbit-drone':
      return 'drone-bolt'
    default:
      return 'bullet'
  }
}

function spreadRadians(
  weaponId: WeaponId,
  index: number,
  count: number,
): number {
  if (count <= 1) return 0
  const spread = weaponId === 'scatter-cannon' ? 30 : 6
  return MathUtils.degToRad(-spread / 2 + (spread * index) / (count - 1))
}

/** Arsenal controller and fixed-pool projectile renderer in one frame owner. */
export function PlayerProjectileSystem() {
  const meshRef = useRef<InstancedMesh>(null)
  const missileBodyRef = useRef<InstancedMesh>(null)
  const missileFinRef = useRef<InstancedMesh>(null)
  const missileTrailRef = useRef<InstancedMesh>(null)
  const nextFireAt = useRef(new Map<WeaponId, number>())
  const lastCooldown = useRef(new Map<WeaponId, number>())
  const impactSerial = useRef(0)
  const priorRunId = useRef(-1)
  const dummy = useMemo(() => new Object3D(), [])
  const originRef = useRef(new Vector3())
  const directionRef = useRef(new Vector3())
  const missileTrailPosition = useMemo(() => new Vector3(), [])
  const storeRunId = useGameStore((state) => state.runId)

  useEffect(() => {
    playerProjectilePool.reset()
    nextFireAt.current.clear()
    priorRunId.current = storeRunId
  }, [storeRunId])

  useEffect(() => {
    const meshes = [
      meshRef.current,
      missileBodyRef.current,
      missileFinRef.current,
      missileTrailRef.current,
    ]
    if (meshes.some((mesh) => mesh === null)) return
    for (const mesh of meshes) mesh!.instanceMatrix.setUsage(DynamicDrawUsage)
    for (let index = 0; index < PLAYER_PROJECTILE_POOL_SIZE; index += 1) {
      meshRef.current!.setColorAt(index, CYAN)
    }
    if (meshRef.current!.instanceColor) {
      meshRef.current!.instanceColor.needsUpdate = true
    }
  }, [])

  const fire = (weapon: RunWeapon, stats: WeaponStats) => {
    const weaponId = weapon.weaponId
    const origin = originRef.current
    const direction = directionRef.current
    const mountedMuzzle = runtime.weaponMuzzles.get(weaponId)
    origin.copy(mountedMuzzle ?? runtime.playerPosition)
    if (!mountedMuzzle) origin.y = 0.92

    if (weaponId === 'orbit-drone') {
      const orbit = orbitAngle(runtime.elapsed, 0, 1)
      origin.set(
        runtime.playerPosition.x + Math.cos(orbit) * ORBIT_RADIUS,
        ORBIT_WORLD_Y,
        runtime.playerPosition.z + Math.sin(orbit) * ORBIT_RADIUS,
      )
    }

    const sharedTarget = runtime.weaponTargetId
      ? runtime.enemies.get(runtime.weaponTargetId)
      : null
    const targetDx =
      (sharedTarget?.position.x ?? Number.POSITIVE_INFINITY) - origin.x
    const targetDz =
      (sharedTarget?.position.z ?? Number.POSITIVE_INFINITY) - origin.z
    const primaryTarget =
      sharedTarget &&
      targetDx * targetDx + targetDz * targetDz <= stats.range * stats.range
        ? (sharedTarget as ProjectileTarget)
        : (findNearestEnemy(
            origin,
            runtime.enemies,
            stats.range,
          ) as ProjectileTarget | null)
    if (!primaryTarget) return false

    const count = Math.max(1, stats.projectileCount)
    let fired = false
    for (let shot = 0; shot < count; shot += 1) {
      const target = primaryTarget
      if (weaponId === 'orbit-drone') {
        const orbit = orbitAngle(runtime.elapsed, shot, count)
        // Ring offset around the player, at the ring's own world height. The
        // previous form copied the player position, overwrote it with .set,
        // then added it back — which doubled the player's Y and put the muzzle
        // 0.8m above the drone that was supposedly firing it.
        origin.set(
          runtime.playerPosition.x + Math.cos(orbit) * ORBIT_RADIUS,
          ORBIT_WORLD_Y,
          runtime.playerPosition.z + Math.sin(orbit) * ORBIT_RADIUS,
        )
      }
      direction.copy(target.position).sub(origin).setY(0).normalize()
      direction.applyAxisAngle(Y_AXIS, spreadRadians(weaponId, shot, count))
      const kind = projectileKind(weaponId)
      const projectile = playerProjectilePool.spawn({
        weaponId,
        kind,
        origin,
        direction,
        stats,
        targetId:
          kind === 'missile' || kind === 'arc' || kind === 'drone-bolt'
            ? target.id
            : undefined,
        homingTurnRate: kind === 'missile' ? 4.8 : kind === 'arc' ? 12 : 0,
        straightSeconds: kind === 'missile' ? 0.2 : 0,
        collisionRadius: kind === 'rail' ? 0.28 : 0.2,
        explosionRadius: kind === 'missile' ? stats.areaRadius : 0,
        chainRadius: kind === 'arc' ? stats.areaRadius : 0,
      })
      fired ||= projectile !== null
    }
    // Once per volley, not once per projectile: a scatter shot is one bang, and
    // its pellet count is a build stat, not a loudness dial.
    if (fired) {
      const pan = Math.max(
        -1,
        Math.min(1, (origin.x - runtime.playerPosition.x) / 3),
      )
      audioEngine.playWeaponFire(weaponId, pan)
    }
    return fired
  }

  useFrame((_, delta) => {
    const state = useGameStore.getState()
    const playing = state.phase === 'playing'
    if (playing) {
      const presentationDelta = applyHitstop(delta)
      const targetModifiers = deriveGlobalWeaponModifiers(
        state.runBuild.passives,
      )
      playerProjectilePool.setTargetDamageModifiers(
        targetModifiers.frozenTargetDamageMultiplier,
        targetModifiers.unfrozenTargetDamageMultiplier,
      )
      if (presentationDelta > 0) {
        playerProjectilePool.update(
          presentationDelta,
          runtime.enemies as unknown as ReadonlyMap<string, ProjectileTarget>,
          (impact) => {
            if (impact.reason !== 'wall') return
            state.publishImpact({
              id: `weapon-impact-${impact.weaponId}-${runtime.elapsed}-${impactSerial.current++}`,
              tier: 'wall',
              source: 'player',
              weaponId: impact.weaponId,
              wallCollision: true,
              position: [
                impact.position.x,
                impact.position.y,
                impact.position.z,
              ],
              direction: [
                impact.direction.x,
                impact.direction.y,
                impact.direction.z,
              ],
              color: TOON_PALETTE.cyanLight,
            })
          },
        )
      }
      for (const weapon of getEquippedWeapons(state.runBuild)) {
        const stats = resolveWeaponStats(weapon, targetModifiers)
        const nextAt = nextFireAt.current.get(weapon.weaponId) ?? 0
        const interval = stats.cooldownMs / 1_000
        if (
          presentationDelta > 0 &&
          runtime.elapsed >= nextAt &&
          fire(weapon, stats)
        ) {
          nextFireAt.current.set(weapon.weaponId, runtime.elapsed + interval)
        }
        const remaining = Math.max(
          0,
          (nextFireAt.current.get(weapon.weaponId) ?? 0) - runtime.elapsed,
        )
        const progress = 1 - Math.min(1, remaining / Math.max(0.001, interval))
        const previous = lastCooldown.current.get(weapon.weaponId) ?? -1
        if (Math.abs(previous - progress) >= 0.05 || progress === 1) {
          lastCooldown.current.set(weapon.weaponId, progress)
          state.setWeaponCooldown(weapon.weaponId, progress)
        }
      }
    }

    const mesh = meshRef.current
    const missileBody = missileBodyRef.current
    const missileFin = missileFinRef.current
    const missileTrail = missileTrailRef.current
    if (!mesh || !missileBody || !missileFin || !missileTrail) return
    for (let index = 0; index < PLAYER_PROJECTILE_POOL_SIZE; index += 1) {
      const projectile = playerProjectilePool.slots[index]
      const missileActive =
        projectile?.active === true && projectile.kind === 'missile'
      if (!projectile?.active || missileActive) {
        dummy.position.set(0, -100, 0)
        dummy.scale.setScalar(0.001)
      } else {
        dummy.position.copy(projectile.position)
        dummy.rotation.set(
          0,
          Math.atan2(projectile.direction.x, projectile.direction.z),
          0,
        )
        switch (projectile.kind) {
          case 'rail':
            dummy.scale.set(0.65, 0.65, 4.6)
            break
          case 'arc':
            dummy.scale.set(1.7, 1.7, 1.7)
            break
          default:
            dummy.scale.set(0.85, 0.85, 2.1)
        }
        mesh.setColorAt(index, projectile.packet?.critical ? WHITE : CYAN)
      }
      dummy.updateMatrix()
      mesh.setMatrixAt(index, dummy.matrix)

      if (missileActive && projectile) {
        const yaw = Math.atan2(projectile.direction.x, projectile.direction.z)
        dummy.position.copy(projectile.position)
        dummy.rotation.set(0, yaw, 0)
        dummy.scale.set(1, 1, 1)
        dummy.updateMatrix()
        missileBody.setMatrixAt(index, dummy.matrix)
        missileFin.setMatrixAt(index, dummy.matrix)

        missileTrailPosition
          .copy(projectile.position)
          .addScaledVector(projectile.direction, -0.48)
        dummy.position.copy(missileTrailPosition)
        dummy.scale.set(1, 1, 1)
        dummy.updateMatrix()
        missileTrail.setMatrixAt(index, dummy.matrix)
      } else {
        dummy.position.set(0, -100, 0)
        dummy.scale.setScalar(0.001)
        dummy.updateMatrix()
        missileBody.setMatrixAt(index, dummy.matrix)
        missileFin.setMatrixAt(index, dummy.matrix)
        missileTrail.setMatrixAt(index, dummy.matrix)
      }
    }
    mesh.instanceMatrix.needsUpdate = true
    if (mesh.instanceColor) mesh.instanceColor.needsUpdate = true
    missileBody.instanceMatrix.needsUpdate = true
    missileFin.instanceMatrix.needsUpdate = true
    missileTrail.instanceMatrix.needsUpdate = true
  })

  return (
    <>
      <instancedMesh
        ref={meshRef}
        args={[undefined, undefined, PLAYER_PROJECTILE_POOL_SIZE]}
        frustumCulled={false}
        name="player-projectile-pool"
      >
        <boxGeometry args={[0.12, 0.12, 0.34]} />
        <meshBasicMaterial
          color={CYAN_BLOOM}
          toneMapped={PROJECTILE_BLOOM_TONE_MAPPED}
        />
      </instancedMesh>
      <instancedMesh
        ref={missileBodyRef}
        args={[undefined, undefined, PLAYER_PROJECTILE_POOL_SIZE]}
        frustumCulled={false}
        name="player-missile-body-pool"
      >
        <boxGeometry args={[0.16, 0.14, 0.54]} />
        <meshBasicMaterial
          color={WHITE_BLOOM}
          toneMapped={PROJECTILE_BLOOM_TONE_MAPPED}
        />
      </instancedMesh>
      <instancedMesh
        ref={missileFinRef}
        args={[undefined, undefined, PLAYER_PROJECTILE_POOL_SIZE]}
        frustumCulled={false}
        name="player-missile-fin-pool"
      >
        <boxGeometry args={[0.42, 0.035, 0.2]} />
        <meshBasicMaterial
          color={GREY_BLOOM}
          toneMapped={PROJECTILE_BLOOM_TONE_MAPPED}
        />
      </instancedMesh>
      <instancedMesh
        ref={missileTrailRef}
        args={[undefined, undefined, PLAYER_PROJECTILE_POOL_SIZE]}
        frustumCulled={false}
        name="player-missile-trail-pool"
      >
        <boxGeometry args={[0.07, 0.07, 0.58]} />
        <meshBasicMaterial
          color={CYAN_BLOOM}
          toneMapped={PROJECTILE_BLOOM_TONE_MAPPED}
        />
      </instancedMesh>
    </>
  )
}
