// Speed-based locomotion blending. The free Quaternius Standard tiers ship
// forward locomotion only (strafes are Pro-only), so the character yaws
// toward its movement direction and the locomotion layer blends by speed:
// idle -> walk -> run. Swarm-type enemies use the shambling zombie pair.

export type LocomotionSet = 'standard' | 'zombie'

export type LocomotionClipName =
  'idle' | 'walk' | 'run' | 'zombieIdle' | 'zombieWalk'

export const LOCOMOTION_CLIPS: Record<
  LocomotionSet,
  readonly LocomotionClipName[]
> = {
  standard: ['idle', 'walk', 'run'],
  zombie: ['zombieIdle', 'zombieWalk'],
}

// speed01 thresholds: below walkStart the character is idle; walk peaks at
// walkFull; run takes over as speed approaches 1.
const WALK_START = 0.02
const WALK_FULL = 0.35
const RUN_FULL = 0.85

function clamp01(value: number) {
  return Math.min(1, Math.max(0, value))
}

/**
 * Resolves locomotion layer weights for a normalized speed. Weights always
 * sum to 1 across the set's clips.
 */
export function resolveLocomotionWeights(
  speed01: number,
  set: LocomotionSet = 'standard',
): Record<string, number> {
  const speed = clamp01(speed01)
  if (set === 'zombie') {
    const walk = clamp01((speed - WALK_START) / (WALK_FULL - WALK_START))
    return { zombieIdle: 1 - walk, zombieWalk: walk }
  }

  if (speed <= WALK_START) return { idle: 1, walk: 0, run: 0 }
  if (speed <= WALK_FULL) {
    const walk = (speed - WALK_START) / (WALK_FULL - WALK_START)
    return { idle: 1 - walk, walk, run: 0 }
  }
  const run = clamp01((speed - WALK_FULL) / (RUN_FULL - WALK_FULL))
  return { idle: 0, walk: 1 - run, run }
}

/**
 * Normalized speed for the locomotion blend. Facing is handled by the
 * caller (visual yaw turns toward the movement direction with the existing
 * quaternionFromNegativeZForward helper).
 */
export function resolveLocomotionSpeed01(
  moveX: number,
  moveZ: number,
  maxSpeed: number,
): number {
  if (maxSpeed <= 0) return 0
  return clamp01(Math.hypot(moveX, moveZ) / maxSpeed)
}
