import { useFrame, useThree } from '@react-three/fiber'
import {
  EffectComposer,
  EffectPass,
  KernelSize,
  RenderPass,
  SelectiveBloomEffect,
  SMAAEffect,
  SMAAPreset,
} from 'postprocessing'
import type { Material, Mesh, Object3D } from 'three'
import { useCallback, useEffect, useRef, useState } from 'react'

import { useGameStore } from '../runtime/gameStore'
import {
  ToonGradeEffect,
  TOON_GRADE_FULL,
  TOON_GRADE_REDUCED_MOTION,
} from './ToonGradeEffect'
import {
  isFlatDarkFrame,
  nextPostProcessingMode,
  type PostProcessingMode,
} from './postProcessingHealth'

// Selection decides what blooms; the threshold only shapes falloff inside it.
const BLOOM_LUMINANCE_THRESHOLD = 0.12
const HEALTH_CHECK_START_FRAME = 45
const HEALTH_CHECK_INTERVAL = 90
const HEALTH_CHECK_FAILURE_LIMIT = 3
const HEALTH_SAMPLE_SIZE = 48
/**
 * The readback below is a synchronous `readPixels`, which stalls the whole GPU
 * pipeline. It exists to catch a composer that renders flat black — a failure
 * that shows up in the first seconds or not at all. Running it forever bought
 * nothing and put a recurring frame spike in the render loop for the entire
 * session, so it retires after this many consecutive clean samples.
 */
const HEALTH_CHECK_CLEAN_SAMPLES = 6
/** Fast projectiles must enter the selection before they cross the arena. */
const BLOOM_SELECTION_INTERVAL = 4
/** Drop a rung below this frame-budget factor, climb back above the other. */
const ADAPTIVE_DEGRADE_FACTOR = 0.28
const ADAPTIVE_RESTORE_FACTOR = 0.55

export function PostProcessing({
  onReady,
  performanceFactor = 1,
}: {
  onReady?: () => void
  performanceFactor?: number
}) {
  // No `onFatalError` here on purpose. Every failure path below degrades from
  // the spatial finishing chain to a render-only composer and finally raw
  // WebGL. Nothing post-processing does is fatal to the run.
  const gl = useThree((state) => state.gl)
  const scene = useThree((state) => state.scene)
  const camera = useThree((state) => state.camera)
  const size = useThree((state) => state.size)
  const dpr = useThree((state) => state.viewport.dpr)
  const reducedMotion = useGameStore((state) => state.settings.reducedMotion)
  const composerRef = useRef<EffectComposer | null>(null)
  const gradeRef = useRef<ToonGradeEffect | null>(null)
  const bloomRef = useRef<SelectiveBloomEffect | null>(null)
  const onReadyRef = useRef(onReady)
  const renderModeRef = useRef<PostProcessingMode>('full')
  const createSafeComposerRef = useRef<(() => EffectComposer) | null>(null)
  const warnedModesRef = useRef(new Set<PostProcessingMode>())
  const healthFrameRef = useRef(0)
  const darkFrameCountRef = useRef(0)
  const cleanSampleCountRef = useRef(0)
  const selectionFrameRef = useRef(0)
  /** Bumped to rebuild the full chain after an adaptive downgrade recovers. */
  const [composerGeneration, setComposerGeneration] = useState(0)

  useEffect(() => {
    onReadyRef.current = onReady
  }, [onReady])

  const clearEffectRefs = useCallback(() => {
    gradeRef.current = null
    bloomRef.current = null
  }, [])

  /**
   * Rebuilds the bloom membership list from the live scene.
   *
   * A material opts in by carrying emission, or by setting `toneMapped: false`
   * — the flag this codebase already uses to mean "this colour is light, do
   * not expose it like a surface". That makes the selection a consequence of
   * how the art is authored rather than a list this file has to maintain.
   */
  const refreshBloomSelection = useCallback(() => {
    const bloom = bloomRef.current
    if (!bloom) return
    const emitters: Object3D[] = []
    scene.traverse((object) => {
      const mesh = object as Mesh
      if (!mesh.isMesh || !mesh.visible) return
      const materials: Material[] = Array.isArray(mesh.material)
        ? mesh.material
        : [mesh.material]
      const emits = materials.some((material) => {
        if (!material) return false
        if (material.toneMapped === false) return true
        const emissive = (material as { emissive?: { getHex(): number } })
          .emissive
        return emissive !== undefined && emissive.getHex() !== 0x000000
      })
      if (emits) emitters.push(object)
    })
    bloom.selection.set(emitters)
  }, [scene])

  const transitionAfterFailure = useCallback(
    (reason: string) => {
      const nextMode = nextPostProcessingMode(renderModeRef.current)
      composerRef.current?.dispose()
      composerRef.current = null
      clearEffectRefs()
      healthFrameRef.current = 0
      darkFrameCountRef.current = 0
      cleanSampleCountRef.current = 0

      if (nextMode === 'render-safe') {
        try {
          const safeComposer = createSafeComposerRef.current?.()
          if (!safeComposer) throw new Error('safe composer unavailable')
          composerRef.current = safeComposer
          renderModeRef.current = nextMode
          if (!warnedModesRef.current.has(nextMode)) {
            warnedModesRef.current.add(nextMode)
            console.warn(
              `[STILLSEEN] Spatial post-processing disabled; keeping render-safe mode: ${reason}`,
            )
          }
          return
        } catch (cause) {
          reason = cause instanceof Error ? cause.message : reason
        }
      }

      renderModeRef.current = 'raw'
      if (!warnedModesRef.current.has('raw')) {
        warnedModesRef.current.add('raw')
        console.warn(
          `[STILLSEEN] Post-processing disabled; using raw WebGL: ${reason}`,
        )
      }
    },
    [clearEffectRefs],
  )

  useEffect(() => {
    renderModeRef.current = 'full'
    healthFrameRef.current = 0
    darkFrameCountRef.current = 0
    cleanSampleCountRef.current = 0

    createSafeComposerRef.current = () => {
      const composer = new EffectComposer(gl, { multisampling: 0 })
      try {
        composer.addPass(new RenderPass(scene, camera))
        composer.setSize(size.width, size.height)
        return composer
      } catch (cause) {
        composer.dispose()
        throw cause
      }
    }

    const warnOptionalPass = (name: string, cause: unknown) => {
      console.warn(`[STILLSEEN] ${name} post-process pass unavailable`, cause)
    }

    try {
      const composer = new EffectComposer(gl, { multisampling: 0 })
      composerRef.current = composer
      composer.addPass(new RenderPass(scene, camera))

      try {
        const grade = new ToonGradeEffect(
          reducedMotion ? TOON_GRADE_REDUCED_MOTION : TOON_GRADE_FULL,
        )
        gradeRef.current = grade
        composer.addPass(new EffectPass(camera, grade))
      } catch (cause) {
        warnOptionalPass('toon grade', cause)
      }

      try {
        /*
         * Selective bloom driven by what the scene declares as light.
         *
         * A luminance threshold cannot work here. It was set to 0.82, which
         * after the renderer's neutral tone mapping sat above everything the
         * game actually draws, so nothing bloomed at all. Lowering it made the
         * light grey deck bloom instead — the floor is genuinely brighter than
         * most emissives once they are tone-mapped, so no single cutoff
         * separates "a lamp" from "a well-lit tile".
         *
         * Membership, not brightness, is the right signal: an object glows
         * because it was authored as a light source. `refreshBloomSelection`
         * below collects exactly those, so torches, lantern cores, the gaze
         * cone, sigils, and the hostile footing rings bloom while the deck
         * never can, whatever its exposure.
         */
        const bloom = new SelectiveBloomEffect(scene, camera, {
          luminanceThreshold: BLOOM_LUMINANCE_THRESHOLD,
          luminanceSmoothing: 0.2,
          intensity: 2.4,
          radius: 0.78,
          kernelSize: KernelSize.LARGE,
          mipmapBlur: true,
        })
        bloom.ignoreBackground = true
        bloomRef.current = bloom
        refreshBloomSelection()
        const smaa = new SMAAEffect({ preset: SMAAPreset.MEDIUM })
        composer.addPass(new EffectPass(camera, bloom, smaa))
      } catch (cause) {
        warnOptionalPass('finishing', cause)
      }

      composer.setSize(size.width, size.height)
      onReadyRef.current?.()
    } catch (cause) {
      transitionAfterFailure(
        cause instanceof Error
          ? cause.message
          : 'post-processing initialization failed',
      )
      onReadyRef.current?.()
    }

    return () => {
      composerRef.current?.dispose()
      composerRef.current = null
      createSafeComposerRef.current = null
      clearEffectRefs()
    }
    // Reduced-motion values are pushed imperatively below to avoid rebuilding
    // and recompiling the shader chain in the middle of a run.
    // eslint-disable-next-line react-hooks/exhaustive-deps
  }, [
    camera,
    gl,
    scene,
    transitionAfterFailure,
    refreshBloomSelection,
    composerGeneration,
  ])

  useEffect(() => {
    composerRef.current?.setSize(size.width, size.height)
  }, [size.height, size.width])

  useEffect(() => {
    gl.setPixelRatio(dpr)
  }, [dpr, gl])

  /*
   * Adaptive quality, and the way back up.
   *
   * This used to fire two transitions back to back, which took a single frame
   * rate dip straight from the full chain to raw WebGL — no bloom and no
   * toon grade — and left it there permanently, because nothing ever rebuilt
   * the composer. A momentary hitch or a WebGL context loss during loading was
   * enough to spend the rest of the session with post-processing silently off.
   *
   * Now it steps down one rung at a time and climbs back when the budget
   * recovers. The gap between the two thresholds is the hysteresis that stops
   * a borderline machine oscillating between chains every second.
   */
  useEffect(() => {
    if (
      performanceFactor < ADAPTIVE_DEGRADE_FACTOR &&
      renderModeRef.current === 'full'
    ) {
      transitionAfterFailure('adaptive performance budget engaged')
      return
    }
    if (
      performanceFactor >= ADAPTIVE_RESTORE_FACTOR &&
      renderModeRef.current !== 'full'
    ) {
      setComposerGeneration((generation) => generation + 1)
    }
  }, [performanceFactor, transitionAfterFailure])

  useEffect(() => {
    gradeRef.current?.applyValues(
      reducedMotion ? TOON_GRADE_REDUCED_MOTION : TOON_GRADE_FULL,
    )
    // Bloom is light, not motion. Keeping it stable also preserves projectile
    // readability when reduced motion comes from the operating system.
    if (bloomRef.current) bloomRef.current.intensity = 2.4
  }, [reducedMotion])

  useFrame((state, delta) => {
    const composer = composerRef.current
    if (!composer) {
      state.gl.render(state.scene, state.camera)
      return
    }

    try {
      composer.render(delta)
    } catch (cause) {
      transitionAfterFailure(
        cause instanceof Error ? cause.message : 'composer render failed',
      )
      if (!composerRef.current) state.gl.render(state.scene, state.camera)
      return
    }

    // Enemies spawn and die, rooms swap, torches unmount — the bloom
    // membership has to follow the live scene rather than a snapshot taken
    // when the composer was built. Fast bolts need a much tighter refresh than
    // static environment lights or they can travel visibly before they glow.
    selectionFrameRef.current += 1
    if (selectionFrameRef.current >= BLOOM_SELECTION_INTERVAL) {
      selectionFrameRef.current = 0
      refreshBloomSelection()
    }

    healthFrameRef.current += 1
    const healthFrame = healthFrameRef.current
    if (
      healthFrame < HEALTH_CHECK_START_FRAME ||
      healthFrame % HEALTH_CHECK_INTERVAL !== 0
    ) {
      return
    }

    let visibleMeshes = 0
    state.scene.traverse((object) => {
      if (
        object.visible &&
        (object as typeof object & { isMesh?: boolean }).isMesh
      ) {
        visibleMeshes += 1
      }
    })
    if (visibleMeshes < 3) return

    try {
      const context = state.gl.getContext()
      const width = Math.min(HEALTH_SAMPLE_SIZE, state.gl.domElement.width)
      const height = Math.min(HEALTH_SAMPLE_SIZE, state.gl.domElement.height)
      if (width <= 0 || height <= 0) return
      const pixels = new Uint8Array(width * height * 4)
      const x = Math.max(0, Math.floor((state.gl.domElement.width - width) / 2))
      const y = Math.max(
        0,
        Math.floor((state.gl.domElement.height - height) / 2),
      )
      context.readPixels(
        x,
        y,
        width,
        height,
        context.RGBA,
        context.UNSIGNED_BYTE,
        pixels,
      )
      if (isFlatDarkFrame(pixels)) {
        cleanSampleCountRef.current = 0
        darkFrameCountRef.current += 1
        if (darkFrameCountRef.current >= HEALTH_CHECK_FAILURE_LIMIT) {
          transitionAfterFailure('flat black output detected')
        }
        return
      }
      darkFrameCountRef.current = 0
      cleanSampleCountRef.current += 1
      if (cleanSampleCountRef.current >= HEALTH_CHECK_CLEAN_SAMPLES) {
        // Proven healthy: stop paying a GPU stall every 90 frames.
        healthFrameRef.current = Number.NEGATIVE_INFINITY
      }
    } catch {
      // Readback is diagnostic only; render exceptions still use the fallback.
      healthFrameRef.current = Number.NEGATIVE_INFINITY
    }
  }, 1)

  return null
}
