import { Color, Vector3 } from 'three'

import type { EffectSpawn } from '../../runtime/gameStore'
import {
  getImpactVisualProfile,
  isImpactEffect,
  type ImpactEffectSpawn,
} from './impactFeedback'

export type VfxParticleKind =
  'blade' | 'core' | 'shard' | 'ring' | 'afterimage' | 'optic'

export interface VfxParticle {
  active: boolean
  kind: VfxParticleKind
  age: number
  duration: number
  x: number
  y: number
  z: number
  velocityX: number
  velocityY: number
  velocityZ: number
  scale: number
  stretch: number
  rotation: number
  spin: number
  hdrIntensity: number
  priority: number
  color: Color
}

export type VfxParticleCounts = Record<VfxParticleKind, number>

export interface VfxParticlePoolTelemetry {
  readonly capacity: number
  readonly active: number
  readonly byKind: Readonly<VfxParticleCounts>
}

const DEFAULT_COUNTS: Readonly<VfxParticleCounts> = {
  blade: 10,
  core: 1,
  shard: 12,
  ring: 1,
  afterimage: 5,
  optic: 14,
}

const IMPACT_TIER_PRIORITY: Readonly<
  Record<ImpactEffectSpawn['impactTier'], number>
> = {
  wall: 0,
  normal: 10,
  critical: 30,
  kill: 50,
  'player-hit': 60,
  'boss-kill': 70,
}

function impactParticlePriority(
  effect: ImpactEffectSpawn,
  kind: 'core' | 'shard' | 'ring',
): number {
  const rolePriority = kind === 'ring' ? 200 : kind === 'core' ? 100 : 0
  return rolePriority + IMPACT_TIER_PRIORITY[effect.impactTier]
}

const directionScratch = new Vector3()

function safeDirection(effect: EffectSpawn): Vector3 {
  directionScratch.set(...(effect.direction ?? [0, 0, -1]))
  if (directionScratch.lengthSq() < 0.000_001) directionScratch.set(0, 0, -1)
  return directionScratch.normalize()
}

function effectParticleKind(effect: EffectSpawn): VfxParticleKind {
  if (effect.kind === 'slash' || effect.kind === 'trail') return 'blade'
  if (effect.kind === 'dash') return 'afterimage'
  if (
    effect.kind === 'seal' ||
    effect.kind === 'shatter' ||
    effect.kind === 'drain'
  ) {
    return 'optic'
  }
  return 'shard'
}

function particleCount(effect: EffectSpawn, reducedMotion: boolean): number {
  const base = DEFAULT_COUNTS[effectParticleKind(effect)]
  if (effect.kind === 'telegraph') return 0
  // A restrained three-beat trail reads as speed without turning the fixed
  // pool into a row of enemy-like silhouettes. Reduced motion keeps one cue.
  if (effect.kind === 'dash') return reducedMotion ? 1 : 3
  if (effect.kind === 'trail') return reducedMotion ? 1 : 3
  return reducedMotion ? Math.max(2, Math.ceil(base * 0.35)) : base
}

function emptyCounts(): VfxParticleCounts {
  return { blade: 0, core: 0, shard: 0, ring: 0, afterimage: 0, optic: 0 }
}

/**
 * Fixed-capacity presentation pool. Spawning mutates preallocated slots and
 * wraps when saturated, so a busy encounter cannot grow memory use over time.
 */
export class VfxParticlePool {
  readonly slots: VfxParticle[]
  private cursor = 0
  private readonly telemetryCounts = emptyCounts()
  private readonly telemetrySnapshot: {
    capacity: number
    active: number
    byKind: VfxParticleCounts
  }

  constructor(capacity = 192) {
    const safeCapacity = Math.max(1, Math.floor(capacity))
    this.slots = Array.from({ length: safeCapacity }, () => ({
      active: false,
      kind: 'shard' as const,
      age: 0,
      duration: 0.3,
      x: 0,
      y: 0,
      z: 0,
      velocityX: 0,
      velocityY: 0,
      velocityZ: 0,
      scale: 0,
      stretch: 1,
      rotation: 0,
      spin: 0,
      hdrIntensity: 1.6,
      priority: 0,
      color: new Color('#ffffff'),
    }))
    this.telemetrySnapshot = {
      capacity: safeCapacity,
      active: 0,
      byKind: this.telemetryCounts,
    }
  }

  private claimSlot(
    kind: VfxParticleKind,
    effect: EffectSpawn,
    duration: number,
    hdrIntensity: number,
    priority: number,
  ): VfxParticle | null {
    let slotIndex = -1
    for (let offset = 0; offset < this.slots.length; offset += 1) {
      const index = (this.cursor + offset) % this.slots.length
      if (!this.slots[index].active) {
        slotIndex = index
        break
      }
    }
    if (slotIndex < 0) {
      let lowestPriority = Number.POSITIVE_INFINITY
      for (let offset = 0; offset < this.slots.length; offset += 1) {
        const index = (this.cursor + offset) % this.slots.length
        const candidatePriority = this.slots[index].priority
        if (candidatePriority < lowestPriority) {
          lowestPriority = candidatePriority
          slotIndex = index
        }
      }
      if (lowestPriority > priority) return null
    }
    const slot = this.slots[slotIndex]
    this.cursor = (slotIndex + 1) % this.slots.length
    slot.active = true
    slot.kind = kind
    slot.age = 0
    slot.duration = duration
    slot.x = effect.position[0]
    slot.y = effect.position[1]
    slot.z = effect.position[2]
    slot.velocityX = 0
    slot.velocityY = 0
    slot.velocityZ = 0
    slot.scale = 0
    slot.stretch = 1
    slot.rotation = 0
    slot.spin = 0
    slot.hdrIntensity = hdrIntensity
    slot.priority = priority
    slot.color.set(effect.color).multiplyScalar(hdrIntensity)
    return slot
  }

  private spawnImpact(effect: ImpactEffectSpawn, reducedMotion: boolean): void {
    const profile = getImpactVisualProfile(effect.impactTier)
    const duration = profile.durationMs / 1000
    const direction = safeDirection(effect)
    const yaw = Math.atan2(-direction.x, -direction.z)
    const motionScale = reducedMotion ? 0.18 : 1
    const shardCount = reducedMotion
      ? Math.max(2, Math.ceil(profile.shardCount * 0.4))
      : profile.shardCount

    const core = this.claimSlot(
      'core',
      effect,
      Math.min(duration, 0.22),
      profile.hdrIntensity,
      impactParticlePriority(effect, 'core'),
    )
    if (core) {
      core.y += 0.08
      core.scale = profile.coreScale
      core.spin = 2.8
    }

    for (let index = 0; index < shardCount; index += 1) {
      const phase = shardCount <= 1 ? 0.5 : index / (shardCount - 1)
      const radialAngle = phase * Math.PI * 2 + (index % 3) * 0.31
      const speed = 1.15 + (index % 5) * 0.34
      const slot = this.claimSlot(
        'shard',
        effect,
        duration,
        profile.hdrIntensity,
        impactParticlePriority(effect, 'shard'),
      )
      if (!slot) continue
      const recoil = effect.impactTier === 'player-hit' ? -0.85 : 0
      slot.y += 0.1
      slot.velocityX =
        (Math.cos(radialAngle) * speed + direction.x * recoil) * motionScale
      slot.velocityY = (0.4 + (index % 4) * 0.2) * motionScale
      slot.velocityZ =
        (Math.sin(radialAngle) * speed + direction.z * recoil) * motionScale
      slot.scale = profile.coreScale * (0.42 + (index % 4) * 0.08)
      slot.stretch = 2.6 + (index % 3) * 0.7
      slot.rotation = yaw + radialAngle
      slot.spin = (index % 2 === 0 ? 1 : -1) * (2.4 + (index % 4) * 0.7)
    }

    if (profile.hasRing) {
      const ring = this.claimSlot(
        'ring',
        effect,
        duration,
        profile.hdrIntensity,
        impactParticlePriority(effect, 'ring'),
      )
      if (ring) {
        ring.y += 0.06
        ring.scale = profile.ringScale
        ring.rotation = yaw
      }
    }
  }

  private spawnLegacy(effect: EffectSpawn, reducedMotion: boolean): void {
    const kind = effectParticleKind(effect)
    const count = particleCount(effect, reducedMotion)
    const direction = safeDirection(effect)
    const yaw = Math.atan2(-direction.x, -direction.z)
    const baseDuration = Math.max(0.08, (effect.durationMs ?? 320) / 1000)

    for (let index = 0; index < count; index += 1) {
      const phase = count <= 1 ? 0.5 : index / (count - 1)
      const radialAngle = phase * Math.PI * 2 + (index % 3) * 0.31
      const side = (phase - 0.5) * (effect.width ?? 1.15)
      const forward = phase * (effect.length ?? 1.8)
      const rightX = -direction.z
      const rightZ = direction.x
      const duration = reducedMotion
        ? Math.min(0.14, baseDuration)
        : baseDuration
      const hdrIntensity =
        effect.kind === 'death' || effect.kind === 'shatter' ? 2.3 : 1.6
      const legacyPriority =
        effect.kind === 'death' || effect.kind === 'shatter' ? 50 : 20
      const slot = this.claimSlot(
        kind,
        effect,
        duration,
        hdrIntensity,
        legacyPriority,
      )
      if (!slot) continue
      slot.rotation = yaw + (kind === 'shard' ? radialAngle : 0)
      slot.spin = (index % 2 === 0 ? 1 : -1) * (2.2 + (index % 4) * 0.7)

      if (kind === 'blade') {
        const arc = -0.85 + phase * 1.7
        const radius = 0.55 + forward * 0.35
        slot.x += Math.sin(yaw + arc) * radius
        slot.y += 0.12 + Math.sin(phase * Math.PI) * 0.32
        slot.z += Math.cos(yaw + arc) * radius
        slot.velocityX = direction.x * 0.55 + rightX * side * 0.2
        slot.velocityY = 0.12
        slot.velocityZ = direction.z * 0.55 + rightZ * side * 0.2
        slot.scale = 0.13 + (index % 3) * 0.025
        slot.stretch = 3.2 + phase * 2.4
      } else if (kind === 'afterimage') {
        const spacing = index * 0.28
        slot.x -= direction.x * spacing
        slot.y += 0.3
        slot.z -= direction.z * spacing
        slot.velocityX = -direction.x * 0.18
        slot.velocityY = 0.02
        slot.velocityZ = -direction.z * 0.18
        slot.scale = 0.46 - phase * 0.2
        slot.stretch = 1.8 + phase
      } else if (kind === 'optic') {
        const radius = effect.kind === 'drain' ? 0.16 : 0.38 + phase * 0.45
        slot.x +=
          Math.cos(radialAngle) * radius +
          (effect.kind === 'drain' ? direction.x * forward : 0)
        slot.y += 0.12 + (index % 5) * 0.18
        slot.z +=
          Math.sin(radialAngle) * radius +
          (effect.kind === 'drain' ? direction.z * forward : 0)
        slot.velocityX = Math.cos(radialAngle) * 0.75
        slot.velocityY = effect.kind === 'shatter' ? 0.9 : 0.24
        slot.velocityZ = Math.sin(radialAngle) * 0.75
        slot.scale = 0.09 + (index % 3) * 0.025
        slot.stretch = effect.kind === 'shatter' ? 3.4 : 1.8
      } else {
        const speed = 1.1 + (index % 5) * 0.38
        slot.y += 0.22
        slot.velocityX = Math.cos(radialAngle) * speed
        slot.velocityY = 0.35 + (index % 4) * 0.22
        slot.velocityZ = Math.sin(radialAngle) * speed
        slot.scale = 0.07 + (index % 4) * 0.018
        slot.stretch = 2.5 + (index % 3)
      }
    }
  }

  spawn(effect: EffectSpawn, reducedMotion = false): void {
    if (isImpactEffect(effect)) {
      this.spawnImpact(effect, reducedMotion)
      return
    }
    this.spawnLegacy(effect, reducedMotion)
  }

  update(deltaSeconds: number): void {
    const delta = Math.max(0, Math.min(0.05, deltaSeconds))
    for (const slot of this.slots) {
      if (!slot.active) continue
      slot.age += delta
      if (slot.age >= slot.duration) {
        slot.active = false
        continue
      }
      slot.x += slot.velocityX * delta
      slot.y += slot.velocityY * delta
      slot.z += slot.velocityZ * delta
      slot.velocityY -= (slot.kind === 'shard' ? 2.8 : 0.35) * delta
      slot.rotation += slot.spin * delta
    }
  }

  activeCount(kind?: VfxParticleKind): number {
    return this.slots.reduce(
      (count, slot) =>
        count + (slot.active && (!kind || slot.kind === kind) ? 1 : 0),
      0,
    )
  }

  telemetry(): VfxParticlePoolTelemetry {
    for (const kind of Object.keys(this.telemetryCounts) as VfxParticleKind[]) {
      this.telemetryCounts[kind] = 0
    }
    let active = 0
    for (const slot of this.slots) {
      if (!slot.active) continue
      active += 1
      this.telemetryCounts[slot.kind] += 1
    }
    this.telemetrySnapshot.active = active
    return this.telemetrySnapshot
  }
}
