import type { EnemyRuntimeHandle } from '../../runtime/registry'

export interface GroundPoint {
  readonly x: number
  readonly z: number
}

/**
 * Allocation-free nearest-target selection shared by the weapon rig and the
 * projectile controller. Stable id ordering prevents equal-distance enemies
 * from making the floating arsenal flick between two headings every frame.
 */
export function findNearestEnemy(
  origin: GroundPoint,
  enemies: ReadonlyMap<string, EnemyRuntimeHandle>,
  range = Number.POSITIVE_INFINITY,
): EnemyRuntimeHandle | null {
  let selected: EnemyRuntimeHandle | null = null
  let selectedDistanceSq = range * range

  for (const enemy of enemies.values()) {
    const dx = enemy.position.x - origin.x
    const dz = enemy.position.z - origin.z
    const distanceSq = dx * dx + dz * dz
    if (distanceSq > selectedDistanceSq) continue
    if (
      distanceSq < selectedDistanceSq ||
      selected === null ||
      enemy.id.localeCompare(selected.id) < 0
    ) {
      selected = enemy
      selectedDistanceSq = distanceSq
    }
  }
  return selected
}
