import { InstancedMesh, Matrix4, Quaternion, Vector3 } from 'three'

import type { VfxParticleKind, VfxParticlePool } from './particlePool'

const scratchMatrix = new Matrix4()
const scratchPosition = new Vector3()
const scratchScale = new Vector3()
const scratchQuaternion = new Quaternion()
const scratchAxis = new Vector3(0, 1, 0)
const scratchRingAxis = new Vector3(1, 0, 0)

/** Synchronizes one visual channel and lowers the GPU draw count to its active instances. */
export function writeParticleInstances(
  mesh: InstancedMesh,
  pool: VfxParticlePool,
  kind: VfxParticleKind,
): void {
  let instance = 0
  for (const particle of pool.slots) {
    if (!particle.active || particle.kind !== kind) continue
    const progress = particle.age / particle.duration
    const fade = Math.max(0, 1 - progress)
    scratchPosition.set(particle.x, particle.y, particle.z)
    scratchQuaternion.setFromAxisAngle(
      kind === 'ring' ? scratchRingAxis : scratchAxis,
      kind === 'ring' ? -Math.PI / 2 : particle.rotation,
    )
    const growth = kind === 'ring' ? 0.18 + progress * 1.82 : 1
    const corePulse =
      kind === 'core'
        ? 0.7 + Math.sin(Math.min(1, progress * 2) * Math.PI) * 0.3
        : 1
    scratchScale.set(
      particle.scale * fade * growth * corePulse,
      particle.scale *
        (kind === 'optic' || kind === 'ring' ? 1 : particle.stretch) *
        fade *
        growth *
        corePulse,
      particle.scale *
        (kind === 'afterimage' ? particle.stretch : 1) *
        fade *
        growth *
        corePulse,
    )
    scratchMatrix.compose(scratchPosition, scratchQuaternion, scratchScale)
    mesh.setMatrixAt(instance, scratchMatrix)
    mesh.setColorAt(instance, particle.color)
    instance += 1
  }
  mesh.count = instance
  mesh.instanceMatrix.needsUpdate = true
  if (mesh.instanceColor) mesh.instanceColor.needsUpdate = true
}
