import { useFrame } from '@react-three/fiber'
import { useLayoutEffect, useMemo, useRef } from 'react'
import {
  AdditiveBlending,
  Color,
  DoubleSide,
  DynamicDrawUsage,
  InstancedMesh,
  Matrix4,
} from 'three'

import { useGameStore } from '../runtime/gameStore'
import { writeParticleInstances } from './vfx/instanceWriter'
import { VfxParticlePool } from './vfx/particlePool'
import { drainVfx } from './vfx/vfxQueue'
import { reportVfxRendererTelemetry } from './vfx/vfxTelemetry'
import { applyHitstop } from './hitstop'

const INSTANCE_CAPACITY = 192
const hiddenMatrix = new Matrix4().makeScale(0, 0, 0)

function PooledParticleField({ pool }: { pool: VfxParticlePool }) {
  const bladeRef = useRef<InstancedMesh>(null)
  const coreRef = useRef<InstancedMesh>(null)
  const shardRef = useRef<InstancedMesh>(null)
  const ringRef = useRef<InstancedMesh>(null)
  const afterimageRef = useRef<InstancedMesh>(null)
  const opticRef = useRef<InstancedMesh>(null)

  useLayoutEffect(() => {
    for (const mesh of [
      bladeRef.current,
      coreRef.current,
      shardRef.current,
      ringRef.current,
      afterimageRef.current,
      opticRef.current,
    ]) {
      if (!mesh) continue
      mesh.instanceMatrix.setUsage(DynamicDrawUsage)
      for (let index = 0; index < INSTANCE_CAPACITY; index += 1) {
        mesh.setMatrixAt(index, hiddenMatrix)
        mesh.setColorAt(index, new Color('#ffffff'))
      }
      mesh.count = 0
      mesh.instanceMatrix.needsUpdate = true
    }
  }, [])

  useFrame((_, delta) => {
    pool.update(applyHitstop(delta))
    if (bladeRef.current)
      writeParticleInstances(bladeRef.current, pool, 'blade')
    if (coreRef.current) writeParticleInstances(coreRef.current, pool, 'core')
    if (shardRef.current)
      writeParticleInstances(shardRef.current, pool, 'shard')
    if (ringRef.current) writeParticleInstances(ringRef.current, pool, 'ring')
    if (afterimageRef.current)
      writeParticleInstances(afterimageRef.current, pool, 'afterimage')
    if (opticRef.current)
      writeParticleInstances(opticRef.current, pool, 'optic')
    reportVfxRendererTelemetry(pool.telemetry())
  })

  return (
    <group name="pooled-combat-vfx">
      <instancedMesh
        ref={bladeRef}
        args={[undefined, undefined, INSTANCE_CAPACITY]}
        frustumCulled={false}
        name="blade-trail-pool"
      >
        <boxGeometry args={[0.13, 0.04, 1]} />
        <meshBasicMaterial
          vertexColors
          transparent
          opacity={0.78}
          depthWrite={false}
          blending={AdditiveBlending}
          toneMapped={false}
        />
      </instancedMesh>
      <instancedMesh
        ref={coreRef}
        args={[undefined, undefined, INSTANCE_CAPACITY]}
        frustumCulled={false}
        name="impact-core-pool"
      >
        <octahedronGeometry args={[0.64, 1]} />
        <meshBasicMaterial
          vertexColors
          transparent
          opacity={1}
          depthWrite={false}
          blending={AdditiveBlending}
          toneMapped={false}
        />
      </instancedMesh>
      <instancedMesh
        ref={shardRef}
        args={[undefined, undefined, INSTANCE_CAPACITY]}
        frustumCulled={false}
        name="impact-shard-pool"
      >
        <tetrahedronGeometry args={[0.5, 0]} />
        <meshBasicMaterial
          vertexColors
          transparent
          opacity={0.94}
          depthWrite={false}
          blending={AdditiveBlending}
          toneMapped={false}
        />
      </instancedMesh>
      <instancedMesh
        ref={ringRef}
        args={[undefined, undefined, INSTANCE_CAPACITY]}
        frustumCulled={false}
        name="impact-ring-pool"
      >
        <ringGeometry args={[0.72, 1, 32]} />
        <meshBasicMaterial
          vertexColors
          transparent
          opacity={0.88}
          depthWrite={false}
          side={DoubleSide}
          blending={AdditiveBlending}
          toneMapped={false}
        />
      </instancedMesh>
      <instancedMesh
        ref={afterimageRef}
        args={[undefined, undefined, INSTANCE_CAPACITY]}
        frustumCulled={false}
        name="dash-afterimage-pool"
      >
        <octahedronGeometry args={[0.75, 0]} />
        <meshBasicMaterial
          vertexColors
          transparent
          opacity={0.22}
          depthWrite={false}
          blending={AdditiveBlending}
          toneMapped={false}
        />
      </instancedMesh>
      <instancedMesh
        ref={opticRef}
        args={[undefined, undefined, INSTANCE_CAPACITY]}
        frustumCulled={false}
        name="optic-lock-pool"
      >
        <octahedronGeometry args={[0.55, 0]} />
        <meshBasicMaterial
          vertexColors
          transparent
          opacity={0.8}
          depthWrite={false}
          blending={AdditiveBlending}
          toneMapped={false}
        />
      </instancedMesh>
    </group>
  )
}

/**
 * Combat VFX.
 *
 * Everything runs through one pre-allocated instanced pool. There used to be a
 * second path: "signature" effects — slash arcs, seals, shatters, death bursts
 * — were mounted as a React component per spawn, each bringing its own
 * geometry and material. That is why attacking stuttered for the first few
 * swings and then went smooth: every new effect variant paid a one-time shader
 * compile the moment it first appeared, and hitting several enemies at once
 * mounted several at once. Once every variant had compiled, the hitching
 * stopped for the rest of the session.
 *
 * The pool has no such cliff — its instances and materials exist from the
 * first frame — so all of it goes through the pool now.
 */
export function Effects() {
  const pool = useMemo(() => new VfxParticlePool(INSTANCE_CAPACITY), [])
  const reducedMotion = useGameStore((state) => state.settings.reducedMotion)

  useFrame(() => {
    const spawned = drainVfx()
    if (spawned.length === 0) return
    for (const effect of spawned) pool.spawn(effect, reducedMotion)
  })

  return (
    <group name="combat-vfx-system">
      <PooledParticleField pool={pool} />
    </group>
  )
}
