import type { Vec2 } from './types'

/**
 * Encounter opening rules.
 *
 * Sectors are survivor fights, not infiltration: every hostile charges the
 * player from frame one. What this module owns is the *fairness* of that
 * start — a pocket of cleared ground the player spawns into, so an opening
 * frame is never an ambush the player had no chance to read.
 *
 * A 1.6s opening hold used to live here too, covering an exit gate's reveal
 * pan. There is no gate any more, and in a survivor arena that pause only made
 * the hostiles look asleep.
 */

export interface ClearZoneOptions {
  /** Radius around the player spawn that must hold no hostiles. */
  readonly minDistance: number
  readonly halfX: number
  readonly halfZ: number
  /** Kept clear of the walls so pushed spawns never clip into them. */
  readonly margin?: number
}

/**
 * Pushes any spawn inside the player's opening pocket out to its edge,
 * clamped to the room. The authored direction is tried first so placement
 * intent survives; if the walls clamp that push back inside the pocket — a
 * spawn near a corner, say — nearby directions are swept until one clears,
 * falling back to whichever clamped candidate lands farthest.
 */
export function pushSpawnsOutOfClearZone(
  spawns: readonly Vec2[],
  playerSpawn: Vec2,
  options: ClearZoneOptions,
): Vec2[] {
  const margin = options.margin ?? 1
  const limitX = Math.max(0, options.halfX - margin)
  const limitZ = Math.max(0, options.halfZ - margin)
  const clampToRoom = (x: number, z: number): Vec2 => ({
    x: Math.max(-limitX, Math.min(limitX, x)),
    z: Math.max(-limitZ, Math.min(limitZ, z)),
  })
  const distanceToPlayer = (point: Vec2) =>
    Math.hypot(point.x - playerSpawn.x, point.z - playerSpawn.z)

  return spawns.map((spawn) => {
    const dx = spawn.x - playerSpawn.x
    const dz = spawn.z - playerSpawn.z
    const distance = Math.hypot(dx, dz)
    if (distance >= options.minDistance) return spawn

    const baseAngle =
      distance > 0.001
        ? Math.atan2(dz, dx)
        : Math.atan2(-playerSpawn.z, -playerSpawn.x)
    let best: Vec2 | null = null
    let bestDistance = -1
    // Sweep outward from the authored direction in alternating steps, so the
    // first legal candidate is also the one closest to the original intent.
    for (let step = 0; step < 16; step += 1) {
      const offset = Math.ceil(step / 2) * (Math.PI / 8)
      const angle = baseAngle + (step % 2 === 0 ? offset : -offset)
      const candidate = clampToRoom(
        playerSpawn.x + Math.cos(angle) * options.minDistance,
        playerSpawn.z + Math.sin(angle) * options.minDistance,
      )
      const candidateDistance = distanceToPlayer(candidate)
      if (candidateDistance >= options.minDistance - 0.001) return candidate
      if (candidateDistance > bestDistance) {
        bestDistance = candidateDistance
        best = candidate
      }
    }
    return best ?? spawn
  })
}
