import type { BiomeId, EliteAffixId, RoomMutationId } from '../game'

// Derived rather than re-declared, so adding a biome or affix to the domain
// cannot leave the scene layer silently behind.
export type SceneBiomeId = BiomeId
export type SceneEliteAffixId = EliteAffixId
export type SceneMutationId = RoomMutationId

/**
 * Deliberately narrower than the domain RouteRisk: this is a presentation
 * bucket where `fixed` and `boss` both render as `stable`.
 */
export type SceneNodeRisk = 'stable' | 'volatile'

export interface SceneRoomPresentation {
  readonly biomeId: SceneBiomeId
  readonly risk: SceneNodeRisk
  readonly mutationId: SceneMutationId | null
  readonly floorColors: readonly string[]
  readonly floorBase: string
  readonly wallColor: string
  readonly accent: string
  readonly ambient: string
}

export interface EliteBadgePresentation {
  readonly id: SceneEliteAffixId
  readonly label: string
  readonly shape: 'chevrons' | 'shield' | 'spikes'
  readonly accent: string
}

interface RoomLike {
  readonly id?: unknown
  readonly templateId?: unknown
  readonly biomeId?: unknown
  readonly risk?: unknown
  readonly routeRisk?: unknown
  readonly mutationId?: unknown
}

/*
 * Environment colour stays low-chroma and cool so warmth — torch light, gold,
 * skin — reads as an accent rather than the dominant note, and so the cyan
 * gaze cone reads as light instead of as a wireframe over a coloured floor.
 *
 * Deck surfaces sit in a light neutral band on purpose.
 *
 * These used to run #07–#30, i.e. near-black. At that value the directional
 * shadow and the ground contact decals had nothing to darken, so every prop,
 * enemy, and wall merged into one silhouette-less mass. Holding the tiles
 * around 70–85% luminance gives them somewhere to go, which is what separates
 * a figure from the floor it stands on. Tile-to-tile steps stay small (a few
 * percent) so the checker reads as a machined surface rather than a
 * chessboard.
 */
const CRYPT_FLOOR = ['#c6d0d0', '#d3dcdb', '#bcc7c7', '#dee5e4', '#b2bdbd']
const MOON_FLOOR = ['#c8c9d6', '#d5d6e1', '#bec0ce', '#e0e1e9', '#b4b7c6']
const VOLATILE_MOON_FLOOR = [
  '#d2c6d4',
  '#dfd3e0',
  '#c6b9c9',
  '#e8dde9',
  '#bcaebe',
]

function normalizedString(value: unknown): string {
  return typeof value === 'string' ? value.trim().toLowerCase() : ''
}

export function normalizeSceneBiome(value: unknown): SceneBiomeId | null {
  const normalized = normalizedString(value)
  if (
    normalized === 'moon-garden' ||
    normalized === 'moon_garden' ||
    normalized === 'moon garden' ||
    normalized === 'moon'
  ) {
    return 'moon-garden'
  }
  if (normalized === 'crypt' || normalized === 'graveyard') return 'crypt'
  return null
}

export function normalizeSceneRisk(value: unknown): SceneNodeRisk | null {
  const normalized = normalizedString(value)
  if (normalized === 'volatile' || normalized === 'corrupted') return 'volatile'
  if (
    normalized === 'stable' ||
    normalized === 'safe' ||
    normalized === 'fixed' ||
    normalized === 'boss'
  )
    return 'stable'
  return null
}

export function normalizeSceneMutation(value: unknown): SceneMutationId | null {
  const normalized = normalizedString(value)
  if (normalized === 'open-ground' || normalized === 'open_ground') {
    return 'open-ground'
  }
  if (normalized === 'restless-swarm' || normalized === 'restless_swarm') {
    return 'restless-swarm'
  }
  if (normalized === 'elite-oath' || normalized === 'elite_oath') {
    return 'elite-oath'
  }
  return null
}

export function normalizeEliteAffix(value: unknown): SceneEliteAffixId | null {
  const normalized = normalizedString(value)
  if (normalized === 'swift') return 'swift'
  if (normalized === 'stalwart' || normalized === 'stout') return 'stalwart'
  if (normalized === 'frenzied' || normalized === 'berserk') return 'frenzied'
  return null
}

export function getEliteBadgePresentation(
  value: unknown,
): EliteBadgePresentation | null {
  const affix = normalizeEliteAffix(value)
  if (affix === 'swift') {
    return {
      id: affix,
      label: 'Swift',
      shape: 'chevrons',
      accent: '#ffffff',
    }
  }
  if (affix === 'stalwart') {
    return {
      id: affix,
      label: 'Stalwart',
      shape: 'shield',
      accent: '#b9b9c2',
    }
  }
  if (affix === 'frenzied') {
    return {
      id: affix,
      label: 'Frenzied',
      shape: 'spikes',
      accent: '#7fffef',
    }
  }
  return null
}

export function isMoonbriarQueen(value: unknown): boolean {
  return normalizedString(value) === 'moonbriar-queen'
}

export function getSceneRoomPresentation(
  room: RoomLike,
): SceneRoomPresentation {
  const templateId = normalizedString(room.templateId ?? room.id)
  const explicitBiome = normalizeSceneBiome(room.biomeId)
  const biomeId =
    explicitBiome ??
    (templateId.includes('moon') || templateId.includes('garden')
      ? 'moon-garden'
      : 'crypt')
  const mutationId = normalizeSceneMutation(room.mutationId)
  const risk =
    normalizeSceneRisk(room.risk ?? room.routeRisk) ??
    (mutationId === null ? 'stable' : 'volatile')

  if (biomeId === 'moon-garden' && risk === 'volatile') {
    return {
      biomeId,
      risk,
      mutationId,
      floorColors: VOLATILE_MOON_FLOOR,
      floorBase: '#a79aa9',
      wallColor: '#cfc4d1',
      accent: '#ffffff',
      ambient: '#9fb8c0',
    }
  }
  if (biomeId === 'moon-garden') {
    return {
      biomeId,
      risk,
      mutationId,
      floorColors: MOON_FLOOR,
      floorBase: '#9fa1b0',
      wallColor: '#c7c9d6',
      accent: '#57e8ff',
      ambient: '#a8bfd7',
    }
  }
  return {
    biomeId,
    risk,
    mutationId,
    floorColors: CRYPT_FLOOR,
    // A shade under the tiles so the bevel gaps stay legible as grout lines.
    floorBase: '#9daaaa',
    // Walls read lighter than the deck so the room boundary is the brightest
    // plane in frame — the player should never lose where the box ends.
    wallColor: '#cfd8d7',
    accent: risk === 'volatile' ? '#eafffc' : '#2be5d0',
    ambient: '#93bac1',
  }
}
