// Fallback only; rooms pass floorColors from sceneMetadata. Kept in sync with
// the crypt palette so a room without presentation data does not go warm.
const FLOOR_TILE_COLORS = [
  '#c6d0d0',
  '#d3dcdb',
  '#bcc7c7',
  '#dee5e4',
  '#b2bdbd',
] as const

/**
 * The arena deck.
 *
 * A static field of plates covering the whole arena. It used to ride under the
 * player and repaint itself as it re-anchored, which the endless field needed;
 * a bounded arena does not, so the matrices and colours are authored once and
 * never touched again. Colours still come from world tile coordinates, so the
 * pattern is identical every time this arena is built.
 */
function ArenaDeck({
  colors = FLOOR_TILE_COLORS,
  baseColor = '#9daaaa',
}: {
  colors?: readonly string[]
  baseColor?: string
}) {
  const meshRef = useRef<InstancedMesh>(null)
  const transform = useMemo(() => new Object3D(), [])
  const tileColor = useMemo(() => new Color(), [])
  const geometry = useMemo(
    () => new RoundedBoxGeometry(1.94, 0.14, 1.94, 1, 0.045),
    [],
  )
  const tileCount = ARENA_TILE_COLUMNS * ARENA_TILE_ROWS

  useEffect(() => () => geometry.dispose(), [geometry])

  useLayoutEffect(() => {
    const mesh = meshRef.current
    if (!mesh) return
    const palette = colors.length > 0 ? colors : FLOOR_TILE_COLORS
    const halfCols = ARENA_TILE_COLUMNS / 2
    const halfRows = ARENA_TILE_ROWS / 2
    let index = 0
    for (let row = 0; row < ARENA_TILE_ROWS; row += 1) {
      for (let column = 0; column < ARENA_TILE_COLUMNS; column += 1) {
        const worldCol = column - halfCols
        const worldRow = row - halfRows
        transform.position.set(
          (worldCol + 0.5) * GROUND_TILE_PITCH,
          -0.08,
          (worldRow + 0.5) * GROUND_TILE_PITCH,
        )
        transform.rotation.set(0, 0, 0)
        transform.scale.set(1, 1, 1)
        transform.updateMatrix()
        mesh.setMatrixAt(index, transform.matrix)
        tileColor.set(
          palette[tilePatternIndex(worldCol, worldRow, palette.length)] ??
            '#c6d0d0',
        )
        mesh.setColorAt(index, tileColor)
        index += 1
      }
    }
    mesh.instanceMatrix.needsUpdate = true
    if (mesh.instanceColor) mesh.instanceColor.needsUpdate = true
    mesh.computeBoundingSphere()
  }, [colors, tileColor, transform])

  return (
    <group name="arena-deck">
      <mesh receiveShadow position={[0, -0.13, 0]}>
        <boxGeometry args={[ARENA_HALF_X * 2, 0.12, ARENA_HALF_Z * 2]} />
        <meshToonMaterial
          color={baseColor}
          gradientMap={environmentGradientMap}
        />
      </mesh>
      <instancedMesh
        ref={meshRef}
        args={[geometry, undefined, tileCount]}
        receiveShadow
      >
        <meshToonMaterial
          color="#ffffff"
          gradientMap={environmentGradientMap}
        />
      </instancedMesh>
    </group>
  )
}

/** Shade per prop kind for the no-asset procedural fallback. */
const OBSTACLE_COLORS: Record<ObstacleKind, string> = {
  column: '#4a4a53',
  crate: '#5a5a62',
  terminal: '#43434c',
  relay: '#51515a',
  debris: '#3d3d45',
}

/**
 * Arena cover.
 *
 * The arena shipped as an empty box, which quietly removed half of the game's
 * one rule: hostiles are supposed to resume moving when a wall breaks the
 * sightline, and the only walls were the four at the boundary. There was
 * nothing to break line of sight behind, so "what do I stop and what do I turn
 * my back on" had no terrain to be answered against.
 *
 * Drawn as a single instanced box plus a single instanced cap — two draw calls
 * for the whole field, which is what lets it be dense enough to matter. Each
 * collider is authored from the same footprint the instance is scaled to, so
 * the silhouette, the physics, and the vision raycast are the same box.
 */
function ArenaObstacles() {
  const obstacles = useMemo(() => buildArenaObstacles(), [])
  const bodyRef = useRef<InstancedMesh>(null)
  const capRef = useRef<InstancedMesh>(null)
  const transform = useMemo(() => new Object3D(), [])
  const instanceColor = useMemo(() => new Color(), [])

  useLayoutEffect(() => {
    const body = bodyRef.current
    const cap = capRef.current
    if (!body || !cap) return
    obstacles.forEach((obstacle, index) => {
      const footprint = OBSTACLE_FOOTPRINT[obstacle.kind]
      const height = OBSTACLE_TARGET_HEIGHT[obstacle.kind]
      const width = footprint.x * 2 * obstacle.scale
      const depth = footprint.z * 2 * obstacle.scale

      transform.position.set(obstacle.x, height / 2, obstacle.z)
      transform.rotation.set(0, obstacle.rotation, 0)
      transform.scale.set(width, height, depth)
      transform.updateMatrix()
      body.setMatrixAt(index, transform.matrix)
      instanceColor.set(OBSTACLE_COLORS[obstacle.kind])
      body.setColorAt(index, instanceColor)

      // A machined lip, matching the wall caps, so the top plane catches the
      // key light instead of going flat against the deck.
      transform.position.set(obstacle.x, height + 0.04, obstacle.z)
      transform.scale.set(width * 1.12, 0.08, depth * 1.12)
      transform.updateMatrix()
      cap.setMatrixAt(index, transform.matrix)
    })
    body.instanceMatrix.needsUpdate = true
    if (body.instanceColor) body.instanceColor.needsUpdate = true
    cap.instanceMatrix.needsUpdate = true
    body.computeBoundingSphere()
    cap.computeBoundingSphere()
  }, [instanceColor, obstacles, transform])

  return (
    <group name="arena-obstacles">
      <instancedMesh
        ref={bodyRef}
        args={[undefined, undefined, obstacles.length]}
        castShadow
        receiveShadow
      >
        <boxGeometry args={[1, 1, 1]} />
        <meshToonMaterial
          color="#ffffff"
          gradientMap={environmentGradientMap}
        />
      </instancedMesh>
      <instancedMesh
        ref={capRef}
        args={[undefined, undefined, obstacles.length]}
      >
        <boxGeometry args={[1, 1, 1]} />
        <meshToonMaterial
          color="#e3e9e8"
          gradientMap={environmentGradientMap}
        />
      </instancedMesh>
      <RigidBody type="fixed" colliders={false}>
        {obstacles.map((obstacle) => {
          const footprint = OBSTACLE_FOOTPRINT[obstacle.kind]
          const height = OBSTACLE_TARGET_HEIGHT[obstacle.kind]
          return (
            <CuboidCollider
              key={obstacle.id}
              args={[
                footprint.x * obstacle.scale,
                height / 2,
                footprint.z * obstacle.scale,
              ]}
              position={[obstacle.x, height / 2, obstacle.z]}
              rotation={[0, obstacle.rotation, 0]}
              collisionGroups={interactionGroups(0, [1, 2, 3])}
            />
          )
        })}
      </RigidBody>
    </group>
  )
}

interface WallProps {
  center: [number, number, number]
  halfExtents: [number, number, number]
  color?: string
  fadeOpacityRef?: RefObject<number>
}

type WallFadeRefs = {
  north: RefObject<number>
  south: RefObject<number>
  west: RefObject<number>
  east: RefObject<number>
}

/**
 * Fades only the boundary segment that lies on the camera-to-player ray.
 * This keeps the rest of the room solid while the player stays visible at a
 * corner, instead of making every wall translucent whenever they approach an
 * edge.
 */
function ForegroundWallFades({ fadeRefs }: { fadeRefs: WallFadeRefs }) {
  const camera = useThree((state) => state.camera)

  useFrame((_, delta) => {
    const player = runtime.playerPosition
    const cameraX = camera.position.x
    const cameraZ = camera.position.z
    const dx = player.x - cameraX
    const dz = player.z - cameraZ
    const intersections = {
      north: false,
      south: false,
      west: false,
      east: false,
    }

    const crossesHorizontalWall = (z: number) => {
      if (Math.abs(dz) < 0.0001) return false
      const t = (z - cameraZ) / dz
      if (t <= 0 || t >= 1) return false
      const x = cameraX + dx * t
      return x >= -ARENA_HALF_X - 0.4 && x <= ARENA_HALF_X + 0.4
    }
    const crossesVerticalWall = (x: number) => {
      if (Math.abs(dx) < 0.0001) return false
      const t = (x - cameraX) / dx
      if (t <= 0 || t >= 1) return false
      const z = cameraZ + dz * t
      return z >= -ARENA_HALF_Z - 0.4 && z <= ARENA_HALF_Z + 0.4
    }

    intersections.north = crossesHorizontalWall(-ARENA_HALF_Z)
    intersections.south = crossesHorizontalWall(ARENA_HALF_Z)
    intersections.west = crossesVerticalWall(-ARENA_HALF_X)
    intersections.east = crossesVerticalWall(ARENA_HALF_X)

    for (const [wall, ref] of Object.entries(fadeRefs) as [
      keyof WallFadeRefs,
      RefObject<number>,
    ][]) {
      const target = intersections[wall] ? FOREGROUND_FADE_MIN_OPACITY : 1
      ref.current = dampForegroundFadeOpacity(ref.current ?? 1, target, delta)
    }
  })

  return null
}

function ProceduralWall({
  halfExtents,
  color,
  fadeOpacityRef,
}: Pick<WallProps, 'halfExtents' | 'color' | 'fadeOpacityRef'>) {
  const visualRef = useRef<Group>(null)
  const fadeControllerRef = useRef<ForegroundMaterialController | null>(null)

  useLayoutEffect(() => {
    if (!fadeOpacityRef || !visualRef.current) return
    const controller = isolateForegroundMaterials(visualRef.current)
    controller.setOpacity(fadeOpacityRef.current ?? 1)
    fadeControllerRef.current = controller
    return () => {
      controller.dispose()
      if (fadeControllerRef.current === controller) {
        fadeControllerRef.current = null
      }
    }
  }, [fadeOpacityRef])

  useFrame(() => {
    fadeControllerRef.current?.setOpacity(fadeOpacityRef?.current ?? 1)
  })

  return (
    <group ref={visualRef}>
      <mesh castShadow receiveShadow>
        <boxGeometry
          args={
            halfExtents.map((value) => value * 2) as [number, number, number]
          }
        />
        <meshToonMaterial color={color} gradientMap={environmentGradientMap} />
      </mesh>
      {/*
        Wall cap. This was a lit teal strip, which put a glowing line along the
        top of every wall in frame — teal stopped meaning "optics" when the
        architecture wore it too. It is a machined edge now: a shade lighter
        than the wall so the top plane still catches the key light and reads as
        a lip, with no emission of its own.
      */}
      <mesh position={[0, halfExtents[1] + 0.08, 0]}>
        <boxGeometry
          args={[halfExtents[0] * 1.8, 0.08, halfExtents[2] * 1.8]}
        />
        <meshToonMaterial
          color="#e3e9e8"
          gradientMap={environmentGradientMap}
        />
      </mesh>
    </group>
  )
}

function Wall({
  center,
  halfExtents,
  color = '#3f3f47',
  fadeOpacityRef,
}: WallProps) {
  return (
    <RigidBody type="fixed" colliders={false} position={center}>
      <CuboidCollider
        args={halfExtents}
        collisionGroups={interactionGroups(0, [1, 2, 3])}
      />
      <ProceduralWall
        halfExtents={halfExtents}
        color={color}
        fadeOpacityRef={fadeOpacityRef}
      />
    </RigidBody>
  )
}

function RouteRiskCue({ risk }: { risk: SceneNodeRisk }) {
  if (risk !== 'volatile') return null

  const accent = TOON_PALETTE.coral
  return (
    <group
      position={[0, 0.04, 6.3]}
      rotation={[-Math.PI / 2, 0, 0]}
      name={`route-risk-${risk}`}
    >
      <group name="route-risk-shape-three-spikes">
        {[0, 1, 2].map((index) => (
          <mesh
            key={index}
            position={[
              Math.cos((index / 3) * Math.PI * 2) * 0.47,
              Math.sin((index / 3) * Math.PI * 2) * 0.47,
              0,
            ]}
            rotation={[0, 0, (index / 3) * Math.PI * 2]}
          >
            <circleGeometry args={[0.3, 3]} />
            <meshBasicMaterial color={accent} transparent opacity={0.7} />
          </mesh>
        ))}
      </group>
    </group>
  )
}

function MutationCue({ mutationId }: { mutationId: SceneMutationId | null }) {
  if (!mutationId) return null
  if (mutationId === 'double-omen') {
    return (
      <group name="mutation-cue-double-omen">
        <MutationCue mutationId="restless-swarm" />
        <MutationCue mutationId="elite-oath" />
      </group>
    )
  }
  if (mutationId === 'open-ground') {
    return (
      <group position={[0, 0.045, 0]} name="mutation-cue-open-ground">
        {[-4.2, 4.2].map((x) => (
          <mesh key={x} position={[x, 0, 0]} rotation={[-Math.PI / 2, 0, 0]}>
            <ringGeometry args={[2.4, 2.47, 40, 1, -0.72, 1.44]} />
            <meshBasicMaterial
              color={TOON_PALETTE.cyanLight}
              transparent
              opacity={0.35}
              depthWrite={false}
            />
          </mesh>
        ))}
      </group>
    )
  }
  if (mutationId === 'restless-swarm') {
    return (
      <group position={[0, 0.05, 0]} name="mutation-cue-restless-swarm">
        {Array.from({ length: 8 }, (_, index) => {
          const angle = (index / 8) * Math.PI * 2
          return (
            <mesh
              key={index}
              position={[Math.cos(angle) * 4.8, 0, Math.sin(angle) * 4.8]}
              rotation={[-Math.PI / 2, 0, angle]}
            >
              <circleGeometry args={[0.26, 3]} />
              <meshBasicMaterial
                color={TOON_PALETTE.coralLight}
                transparent
                opacity={0.48}
                depthWrite={false}
              />
            </mesh>
          )
        })}
      </group>
    )
  }
  return (
    <group position={[0, 0.05, 0]} name="mutation-cue-elite-oath">
      {[2.25, 2.68].map((radius) => (
        <mesh key={radius} rotation={[-Math.PI / 2, 0, Math.PI / 4]}>
          <ringGeometry args={[radius - 0.065, radius, 4]} />
          <meshBasicMaterial
            color={TOON_PALETTE.goldLight}
            transparent
            opacity={0.5}
            depthWrite={false}
          />
        </mesh>
      ))}
    </group>
  )
}

export interface RoomEnvironmentProps {
  room: RoomTemplate
  biomeId?: unknown
  risk?: unknown
  mutationId?: unknown
}

export function RoomEnvironment({
  room,
  biomeId,
  risk,
  mutationId,
}: RoomEnvironmentProps) {
  const northFadeOpacityRef = useRef(1)
  const southFadeOpacityRef = useRef(1)
  const westFadeOpacityRef = useRef(1)
  const eastFadeOpacityRef = useRef(1)
  const presentation = useMemo(
    () =>
      getSceneRoomPresentation({
        id: room.id,
        biomeId: biomeId ?? room.biomeId,
        risk,
        mutationId,
      }),
    [biomeId, mutationId, risk, room.biomeId, room.id],
  )
  const fadeRefs = useMemo<WallFadeRefs>(
    () => ({
      north: northFadeOpacityRef,
      south: southFadeOpacityRef,
      west: westFadeOpacityRef,
      east: eastFadeOpacityRef,
    }),
    [],
  )

  return (
    <group>
      <ForegroundWallFades fadeRefs={fadeRefs} />
      <RigidBody type="fixed" colliders={false}>
        <CuboidCollider
          args={[ARENA_HALF_X, 0.1, ARENA_HALF_Z]}
          position={[0, -0.1, 0]}
          collisionGroups={interactionGroups(0, [1, 2, 3])}
        />
      </RigidBody>
      <ArenaDeck
        colors={presentation.floorColors}
        baseColor={presentation.floorBase}
      />
      <ArenaObstacles />
      {/*
        Arena boundary. Biome dressing stays stripped — the field carries cover
        and nothing decorative, so anything the player sees standing up is
        something that breaks a sightline.
        Kept deliberately low so the camera retains the arena silhouette
        without hiding combatants near a corner.
      */}
      <Wall
        center={[0, 1.1, -ARENA_HALF_Z]}
        halfExtents={[ARENA_HALF_X, 1.1, 0.4]}
        color={presentation.wallColor}
        fadeOpacityRef={northFadeOpacityRef}
      />
      <Wall
        center={[0, 1.1, ARENA_HALF_Z]}
        halfExtents={[ARENA_HALF_X, 1.1, 0.4]}
        color={presentation.wallColor}
        fadeOpacityRef={southFadeOpacityRef}
      />
      <Wall
        center={[-ARENA_HALF_X, 1.1, 0]}
        halfExtents={[0.4, 1.1, ARENA_HALF_Z]}
        color={presentation.wallColor}
        fadeOpacityRef={westFadeOpacityRef}
      />
      <Wall
        center={[ARENA_HALF_X, 1.1, 0]}
        halfExtents={[0.4, 1.1, ARENA_HALF_Z]}
        color={presentation.wallColor}
        fadeOpacityRef={eastFadeOpacityRef}
      />

      <RouteRiskCue risk={presentation.risk} />
      <MutationCue mutationId={presentation.mutationId} />
    </group>
  )
}
