import { useFrame } from '@react-three/fiber'
import { useRapier } from '@react-three/rapier'
import { useMemo, useRef } from 'react'
import { Group, Vector3 } from 'three'

import { useGameStore, type ProjectileSpawn } from '../runtime/gameStore'
import { runtime } from '../runtime/registry'
import { getArenaCoverHitFraction } from './arenaGround'
import { yawFromNegativeZForward } from './direction'
import {
  getProjectileBloomColor,
  getSimpleProjectileDimensions,
  PROJECTILE_BLOOM_TONE_MAPPED,
} from './projectileVisual'
import { TOON_PALETTE } from './toonMaterials'
import { applyHitstop } from './hitstop'

function SimpleProjectileVisual({
  projectile,
}: {
  projectile: ProjectileSpawn
}) {
  const dimensions = getSimpleProjectileDimensions(projectile.radius)
  const bloomColor = useMemo(
    () => getProjectileBloomColor(projectile.color),
    [projectile.color],
  )
  return (
    <mesh name="enemy-projectile-bloom-core">
      <boxGeometry args={[dimensions[0], dimensions[1], dimensions[2]]} />
      <meshBasicMaterial
        color={bloomColor}
        toneMapped={PROJECTILE_BLOOM_TONE_MAPPED}
      />
    </mesh>
  )
}

function EnemyProjectile({ projectile }: { projectile: ProjectileSpawn }) {
  const groupRef = useRef<Group>(null)
  const position = useMemo(
    () => new Vector3(...projectile.position),
    [projectile.position],
  )
  const direction = useMemo(
    () => new Vector3(...projectile.direction).normalize(),
    [projectile.direction],
  )
  const rotationY = yawFromNegativeZForward(direction)
  const lifetime = useRef(5)
  const activationDelay = useRef((projectile.activationDelayMs ?? 0) / 1_000)
  const targetDirection = useMemo(() => new Vector3(), [])
  const { world, rapier } = useRapier()
  /**
   * Reused rather than rebuilt each frame, mirroring `Enemy`'s pattern. This
   * allocated a Ray and two vector literals per projectile per frame, which in
   * a boss volley is dozens of allocations a second in the hot loop for no
   * reason. A ref rather than a memo because it is written every frame, and
   * memoized values are not ours to mutate.
   */
  const rayRef = useRef(
    new rapier.Ray({ x: 0, y: 0, z: 0 }, { x: 0, y: 0, z: 1 }),
  )

  useFrame((_, frameDelta) => {
    const phase = String(useGameStore.getState().phase)
    if (phase !== 'playing') return
    const delta = applyHitstop(Math.min(frameDelta, 0.08))
    if (delta === 0) return
    let liberationTargetDistance: number | undefined
    if (projectile.kind === 'liberation') {
      const target = projectile.targetEnemyId
        ? runtime.enemies.get(projectile.targetEnemyId)
        : undefined
      if (!target) {
        useGameStore.getState().removeProjectile(projectile.id)
        return
      }
      if (activationDelay.current > 0) {
        activationDelay.current -= delta
        return
      }

      targetDirection
        .set(target.position.x, 0.74, target.position.z)
        .sub(position)
      const targetDistance = targetDirection.length()
      liberationTargetDistance = targetDistance
      if (targetDistance > 0.001) direction.copy(targetDirection).normalize()
      if (groupRef.current) {
        groupRef.current.rotation.y = yawFromNegativeZForward(direction)
      }
      const impactDistance = 0.2
      if (targetDistance <= impactDistance) {
        target.dispelObservation(1_400)
        useGameStore.getState().spawnEffect({
          id: `liberated-${projectile.id}`,
          kind: 'shatter',
          position: [target.position.x, 0.34, target.position.z],
          color: TOON_PALETTE.coralLight,
          durationMs: 420,
        })
        runtime.cameraTrauma = Math.max(runtime.cameraTrauma, 0.12)
        useGameStore.getState().removeProjectile(projectile.id)
        return
      }
    }
    const stepDistance =
      liberationTargetDistance === undefined
        ? projectile.speed * delta
        : Math.min(projectile.speed * delta, liberationTargetDistance)
    const nextX = position.x + direction.x * stepDistance
    const nextZ = position.z + direction.z * stepDistance
    const coverHit = getArenaCoverHitFraction(
      position.x,
      position.z,
      nextX,
      nextZ,
      projectile.radius ?? 0.16,
    )
    if (coverHit !== null) {
      const store = useGameStore.getState()
      store.publishImpact({
        id: `enemy-wall-${projectile.id}`,
        tier: 'wall',
        source: 'enemy',
        wallCollision: true,
        position: [
          position.x + (nextX - position.x) * coverHit,
          position.y,
          position.z + (nextZ - position.z) * coverHit,
        ],
        direction: [direction.x, direction.y, direction.z],
        color: '#ffffff',
      })
      store.removeProjectile(projectile.id)
      return
    }
    const ray = rayRef.current
    ray.origin.x = position.x
    ray.origin.y = position.y
    ray.origin.z = position.z
    ray.dir.x = direction.x
    ray.dir.y = direction.y
    ray.dir.z = direction.z
    const flags =
      rapier.QueryFilterFlags.EXCLUDE_DYNAMIC |
      rapier.QueryFilterFlags.EXCLUDE_KINEMATIC
    const surfaceHit = world.castRay(ray, stepDistance + 0.08, true, flags)
    if (surfaceHit) {
      const store = useGameStore.getState()
      store.publishImpact({
        id: `enemy-surface-${projectile.id}`,
        tier: 'wall',
        source: 'enemy',
        wallCollision: true,
        position: [
          position.x + direction.x * surfaceHit.timeOfImpact,
          position.y + direction.y * surfaceHit.timeOfImpact,
          position.z + direction.z * surfaceHit.timeOfImpact,
        ],
        direction: [direction.x, direction.y, direction.z],
        color: '#ffffff',
      })
      store.removeProjectile(projectile.id)
      return
    }

    position.addScaledVector(direction, stepDistance)
    groupRef.current?.position.copy(position)
    lifetime.current -= delta

    if (projectile.kind === 'liberation') {
      const target = projectile.targetEnemyId
        ? runtime.enemies.get(projectile.targetEnemyId)
        : undefined
      if (!target) {
        useGameStore.getState().removeProjectile(projectile.id)
        return
      }
      const dx = position.x - target.position.x
      const dy = position.y - 0.74
      const dz = position.z - target.position.z
      if (dx * dx + dy * dy + dz * dz <= 0.04) {
        target.dispelObservation(1_400)
        useGameStore.getState().spawnEffect({
          id: `liberated-${projectile.id}`,
          kind: 'shatter',
          position: [target.position.x, 0.34, target.position.z],
          color: TOON_PALETTE.coralLight,
          durationMs: 420,
        })
        runtime.cameraTrauma = Math.max(runtime.cameraTrauma, 0.12)
        useGameStore.getState().removeProjectile(projectile.id)
      }
      if (lifetime.current <= 0)
        useGameStore.getState().removeProjectile(projectile.id)
      return
    }

    const dx = position.x - runtime.playerPosition.x
    const dz = position.z - runtime.playerPosition.z
    if (dx * dx + dz * dz < 0.38) {
      useGameStore
        .getState()
        .damagePlayer(projectile.damage, [
          position.x - direction.x * 1.5,
          position.y,
          position.z - direction.z * 1.5,
        ])
      useGameStore.getState().removeProjectile(projectile.id)
      return
    }
    if (lifetime.current <= 0)
      useGameStore.getState().removeProjectile(projectile.id)
  })

  return (
    <group
      ref={groupRef}
      position={projectile.position}
      rotation={[0, rotationY, 0]}
      name={`projectile-${projectile.kind ?? 'magic'}`}
    >
      <SimpleProjectileVisual projectile={projectile} />
    </group>
  )
}

export function Projectiles() {
  const projectiles = useGameStore((state) => state.projectiles)
  return projectiles.map((projectile) => (
    <EnemyProjectile key={projectile.id} projectile={projectile} />
  ))
}
