import type {
  VfxParticleCounts,
  VfxParticlePoolTelemetry,
} from './particlePool'
import { drainedVfxCount, droppedVfxCount, pendingVfxCount } from './vfxQueue'

export interface VfxTelemetry {
  readonly pending: number
  readonly drained: number
  readonly dropped: number
  readonly capacity: number
  readonly active: number
  readonly byKind: Readonly<VfxParticleCounts>
}

const EMPTY_COUNTS: Readonly<VfxParticleCounts> = Object.freeze({
  blade: 0,
  core: 0,
  shard: 0,
  ring: 0,
  afterimage: 0,
  optic: 0,
})

let rendererTelemetry: VfxParticlePoolTelemetry = {
  capacity: 192,
  active: 0,
  byKind: EMPTY_COUNTS,
}

/** Updated by the renderer after each pool tick; does not allocate per frame. */
export function reportVfxRendererTelemetry(
  telemetry: VfxParticlePoolTelemetry,
): void {
  rendererTelemetry = telemetry
}

/** Snapshot for the debug bridge and performance tests. */
export function getVfxTelemetry(): VfxTelemetry {
  return {
    pending: pendingVfxCount(),
    drained: drainedVfxCount(),
    dropped: droppedVfxCount(),
    capacity: rendererTelemetry.capacity,
    active: rendererTelemetry.active,
    byKind: rendererTelemetry.byKind,
  }
}

export function resetVfxRendererTelemetry(): void {
  rendererTelemetry = { capacity: 192, active: 0, byKind: EMPTY_COUNTS }
}
