import { Vector3 } from 'three'

import {
  createDamagePacket,
  type DamagePacket,
  type WeaponId,
  type WeaponStats,
} from '../game/runBuild'
import { getArenaCoverHitFraction } from './arenaGround'

export const PLAYER_PROJECTILE_POOL_SIZE = 512

type Mutable<T> = { -readonly [K in keyof T]: T[K] }

export type PlayerProjectileKind =
  'bullet' | 'pellet' | 'missile' | 'rail' | 'arc' | 'drone-bolt'

export interface ProjectileTarget {
  readonly id: string
  readonly position: Vector3
  /** Held still by any observation rule. Drives the weak-point multipliers. */
  readonly frozen: boolean
  takeHit: (
    packet: DamagePacket,
    direction: Vector3,
    knockback: number,
    impactPosition?: Vector3,
  ) => void
}

export interface PlayerProjectileSpawn {
  readonly weaponId: WeaponId
  readonly kind: PlayerProjectileKind
  readonly origin: Vector3
  readonly direction: Vector3
  readonly stats: WeaponStats
  readonly targetId?: string
  readonly homingTurnRate?: number
  readonly straightSeconds?: number
  readonly collisionRadius?: number
  readonly explosionRadius?: number
  readonly chainRadius?: number
}

export interface PlayerProjectileImpact {
  readonly kind: PlayerProjectileKind
  readonly weaponId: WeaponId
  readonly position: Vector3
  readonly direction: Vector3
  readonly radius: number
  readonly critical: boolean
  readonly reason: 'target' | 'wall'
}

export interface PooledPlayerProjectile {
  active: boolean
  id: number
  hitId: string
  weaponId: WeaponId
  kind: PlayerProjectileKind
  position: Vector3
  previousPosition: Vector3
  direction: Vector3
  speed: number
  age: number
  lifetime: number
  collisionRadius: number
  explosionRadius: number
  chainRadius: number
  remainingHits: number
  remainingChains: number
  targetId: string | null
  homingTurnRate: number
  straightSeconds: number
  packet: DamagePacket | null
  alreadyHit: Set<string>
}

function createSlot(id: number): PooledPlayerProjectile {
  return {
    active: false,
    id,
    hitId: '',
    weaponId: 'pulse-carbine',
    kind: 'bullet',
    position: new Vector3(),
    previousPosition: new Vector3(),
    direction: new Vector3(0, 0, -1),
    speed: 0,
    age: 0,
    lifetime: 0,
    collisionRadius: 0.15,
    explosionRadius: 0,
    chainRadius: 0,
    remainingHits: 1,
    remainingChains: 0,
    targetId: null,
    homingTurnRate: 0,
    straightSeconds: 0,
    packet: null,
    alreadyHit: new Set(),
  }
}

/**
 * Enemy runtime positions are body centres. This stands in for the smallest
 * hostile collider so a hit does not require the maths to pass through a
 * dimensionless point.
 */
const ENEMY_BODY_RADIUS = 0.38

/**
 * Fixed-capacity world simulation for every player weapon. Slots and vectors
 * are allocated once; firing, collision, expiry, and reset only mutate them.
 */
export class PlayerProjectilePool {
  readonly slots: readonly PooledPlayerProjectile[]
  private sequence = 0
  private readonly desiredDirection = new Vector3()
  private readonly impactDirection = new Vector3()
  private readonly contactPosition = new Vector3()
  private frozenDamageMultiplier = 1
  private unfrozenDamageMultiplier = 1
  /** Reused so a target-scaled hit costs no allocation. */
  private readonly scaledPacket: Mutable<DamagePacket> = {
    hitId: '',
    sourceWeaponId: 'pulse-carbine',
    weaponId: 'pulse-carbine',
    amount: 0,
    knockback: 0,
    critical: false,
    tags: [],
  }

  constructor(readonly capacity = PLAYER_PROJECTILE_POOL_SIZE) {
    this.slots = Array.from({ length: capacity }, (_, index) =>
      createSlot(index),
    )
  }

  get activeCount(): number {
    let count = 0
    for (const slot of this.slots) if (slot.active) count += 1
    return count
  }

  spawn(spawn: PlayerProjectileSpawn): PooledPlayerProjectile | null {
    const slot = this.slots.find((candidate) => !candidate.active)
    if (!slot) return null
    const speed = Math.max(0.01, spawn.stats.projectileSpeed || 11)
    const direction = slot.direction.copy(spawn.direction).setY(0)
    if (direction.lengthSq() < 0.0001) direction.set(0, 0, -1)
    direction.normalize()
    const critical = Math.random() < spawn.stats.criticalChance
    this.sequence += 1
    slot.active = true
    slot.hitId = `player-projectile-${this.sequence}`
    slot.weaponId = spawn.weaponId
    slot.kind = spawn.kind
    slot.position.copy(spawn.origin)
    slot.previousPosition.copy(spawn.origin)
    slot.speed = speed
    slot.age = 0
    slot.lifetime = Math.max(0.28, spawn.stats.range / speed + 0.35)
    slot.collisionRadius = Math.max(0.08, spawn.collisionRadius ?? 0.16)
    slot.explosionRadius = Math.max(0, spawn.explosionRadius ?? 0)
    slot.chainRadius = Math.max(0, spawn.chainRadius ?? 0)
    slot.remainingHits = Math.max(1, Math.floor(spawn.stats.maxHits))
    slot.remainingChains =
      spawn.kind === 'arc' ? Math.max(0, slot.remainingHits - 1) : 0
    slot.targetId = spawn.targetId ?? null
    slot.homingTurnRate = Math.max(0, spawn.homingTurnRate ?? 0)
    slot.straightSeconds = Math.max(0, spawn.straightSeconds ?? 0)
    slot.packet = createDamagePacket(
      slot.hitId,
      spawn.weaponId,
      spawn.stats,
      critical,
    )
    slot.alreadyHit.clear()
    return slot
  }

  reset(): void {
    for (const slot of this.slots) {
      slot.active = false
      slot.packet = null
      slot.alreadyHit.clear()
    }
  }

  private deactivate(slot: PooledPlayerProjectile): void {
    slot.active = false
    slot.packet = null
    slot.targetId = null
    slot.alreadyHit.clear()
  }

  private findTarget(
    id: string | null,
    targets: ReadonlyMap<string, ProjectileTarget>,
  ): ProjectileTarget | null {
    return id === null ? null : (targets.get(id) ?? null)
  }

  private findChainTarget(
    slot: PooledPlayerProjectile,
    targets: ReadonlyMap<string, ProjectileTarget>,
  ): ProjectileTarget | null {
    let nearest: ProjectileTarget | null = null
    let nearestDistanceSq = slot.chainRadius * slot.chainRadius
    for (const target of targets.values()) {
      if (slot.alreadyHit.has(target.id)) continue
      const distanceSq = slot.position.distanceToSquared(target.position)
      if (distanceSq <= nearestDistanceSq) {
        nearestDistanceSq = distanceSq
        nearest = target
      }
    }
    return nearest
  }

  /**
   * Weak-point multipliers depend on the target, not the weapon, so they are
   * applied at the single damage gate every projectile family passes through —
   * direct hits, explosion splash, and arc chains alike.
   */
  setTargetDamageModifiers(frozen: number, unfrozen: number): void {
    this.frozenDamageMultiplier = Number.isFinite(frozen) ? frozen : 1
    this.unfrozenDamageMultiplier = Number.isFinite(unfrozen) ? unfrozen : 1
  }

  private damageTarget(
    slot: PooledPlayerProjectile,
    target: ProjectileTarget,
    impactPosition = target.position,
  ): boolean {
    if (!slot.packet || slot.alreadyHit.has(target.id)) return false
    this.impactDirection.copy(slot.direction).setY(0)
    if (this.impactDirection.lengthSq() < 0.0001) {
      this.impactDirection.copy(target.position).sub(slot.position).setY(0)
    }
    this.impactDirection.normalize()
    slot.alreadyHit.add(target.id)

    const multiplier = target.frozen
      ? this.frozenDamageMultiplier
      : this.unfrozenDamageMultiplier
    // slot.packet is read by the renderer for its crit flag, so scale into a
    // reused scratch packet instead of mutating it. takeHit consumes every
    // field synchronously, which makes the shared object safe.
    let packet = slot.packet
    if (multiplier !== 1) {
      this.scaledPacket.hitId = slot.packet.hitId
      this.scaledPacket.sourceWeaponId = slot.packet.sourceWeaponId
      this.scaledPacket.weaponId = slot.packet.weaponId
      this.scaledPacket.amount = slot.packet.amount * multiplier
      this.scaledPacket.knockback = slot.packet.knockback
      this.scaledPacket.critical = slot.packet.critical
      this.scaledPacket.tags = slot.packet.tags
      packet = this.scaledPacket
    }
    target.takeHit(
      packet,
      this.impactDirection,
      packet.knockback,
      impactPosition,
    )
    return true
  }

  /** Returns the first segment fraction where the projectile enters a body. */
  private travelHitFraction(
    slot: PooledPlayerProjectile,
    target: ProjectileTarget,
  ): number | null {
    const segmentX = slot.position.x - slot.previousPosition.x
    const segmentZ = slot.position.z - slot.previousPosition.z
    const lengthSq = segmentX * segmentX + segmentZ * segmentZ
    const combinedRadius = slot.collisionRadius + ENEMY_BODY_RADIUS
    const offsetX = slot.previousPosition.x - target.position.x
    const offsetZ = slot.previousPosition.z - target.position.z
    const inside =
      offsetX * offsetX + offsetZ * offsetZ <= combinedRadius * combinedRadius
    if (inside) return 0
    if (lengthSq <= 0.000001) return null

    const b = 2 * (offsetX * segmentX + offsetZ * segmentZ)
    const c =
      offsetX * offsetX + offsetZ * offsetZ - combinedRadius * combinedRadius
    const discriminant = b * b - 4 * lengthSq * c
    if (discriminant < 0) return null
    const entry = (-b - Math.sqrt(discriminant)) / (2 * lengthSq)
    return entry >= 0 && entry <= 1 ? entry : null
  }

  private explode(
    slot: PooledPlayerProjectile,
    targets: ReadonlyMap<string, ProjectileTarget>,
  ): void {
    if (slot.explosionRadius <= 0) return
    const radiusSq = slot.explosionRadius * slot.explosionRadius
    for (const target of targets.values()) {
      if (
        !slot.alreadyHit.has(target.id) &&
        slot.position.distanceToSquared(target.position) <= radiusSq
      ) {
        this.damageTarget(slot, target)
      }
    }
  }

  update(
    deltaSeconds: number,
    targets: ReadonlyMap<string, ProjectileTarget>,
    onImpact?: (impact: PlayerProjectileImpact) => void,
  ): void {
    const delta = Math.max(0, Math.min(0.05, deltaSeconds))
    if (delta === 0) return

    for (const slot of this.slots) {
      if (!slot.active) continue
      slot.age += delta
      if (slot.age >= slot.lifetime) {
        this.deactivate(slot)
        continue
      }

      const homingTarget = this.findTarget(slot.targetId, targets)
      if (
        homingTarget &&
        slot.age >= slot.straightSeconds &&
        slot.homingTurnRate > 0
      ) {
        this.desiredDirection
          .copy(homingTarget.position)
          .sub(slot.position)
          .setY(0)
        if (this.desiredDirection.lengthSq() > 0.0001) {
          this.desiredDirection.normalize()
          slot.direction
            .lerp(
              this.desiredDirection,
              Math.min(1, slot.homingTurnRate * delta),
            )
            .normalize()
        }
      }

      slot.previousPosition.copy(slot.position)
      slot.position.addScaledVector(slot.direction, slot.speed * delta)
      const coverHit = getArenaCoverHitFraction(
        slot.previousPosition.x,
        slot.previousPosition.z,
        slot.position.x,
        slot.position.z,
        slot.collisionRadius,
      )
      if (coverHit !== null) {
        slot.position.lerpVectors(
          slot.previousPosition,
          slot.position,
          coverHit,
        )
      }
      for (const target of targets.values()) {
        if (slot.alreadyHit.has(target.id)) continue
        const hitFraction = this.travelHitFraction(slot, target)
        if (hitFraction === null) continue

        this.contactPosition.lerpVectors(
          slot.previousPosition,
          slot.position,
          hitFraction,
        )

        const damaged = this.damageTarget(slot, target, this.contactPosition)
        if (damaged) {
          onImpact?.({
            kind: slot.kind,
            weaponId: slot.weaponId,
            position: this.contactPosition,
            direction: slot.direction,
            radius:
              slot.kind === 'missile'
                ? Math.max(slot.collisionRadius, slot.explosionRadius)
                : slot.collisionRadius,
            critical: slot.packet?.critical === true,
            reason: 'target',
          })
        }
        if (slot.kind === 'missile') {
          slot.position.copy(this.contactPosition)
          this.explode(slot, targets)
          this.deactivate(slot)
          break
        }
        if (slot.kind === 'arc' && slot.remainingChains > 0) {
          const chainTarget = this.findChainTarget(slot, targets)
          if (chainTarget) {
            slot.remainingChains -= 1
            slot.targetId = chainTarget.id
            slot.direction
              .copy(chainTarget.position)
              .sub(slot.position)
              .setY(0)
              .normalize()
            break
          }
        }
        slot.remainingHits -= 1
        if (slot.remainingHits <= 0) {
          this.deactivate(slot)
          break
        }
      }
      if (slot.active && coverHit !== null) {
        onImpact?.({
          kind: slot.kind,
          weaponId: slot.weaponId,
          position: slot.position,
          direction: slot.direction,
          radius: slot.collisionRadius,
          critical: slot.packet?.critical === true,
          reason: 'wall',
        })
        this.deactivate(slot)
      }
    }
  }
}

/** One world-owned pool, reset whenever a new run is mounted. */
export const playerProjectilePool = new PlayerProjectilePool()
