import { Vector3 } from 'three'

export interface FlatFacingDirection {
  readonly x: number
  readonly z: number
}

/**
 * Selects the direction owned by the rendered character mesh.
 *
 * Gameplay aim stays on the player root and weapon rig. Only the rendered
 * silhouette temporarily follows travel while the full-body dash clip plays.
 */
export function resolvePlayerVisualFacing(
  aimFacing: FlatFacingDirection,
  dashDirection: FlatFacingDirection,
  dashVisualActive: boolean,
  target = new Vector3(),
): Vector3 {
  const source = dashVisualActive ? dashDirection : aimFacing
  target.set(source.x, 0, source.z)
  if (target.lengthSq() < 1e-8) target.set(0, 0, -1)
  return target.normalize()
}
