import { useFrame } from '@react-three/fiber'
import { useEffect, useMemo, useRef, type ReactNode } from 'react'
import { Group, Vector3 } from 'three'

import type { RangedWeaponId } from '../../game/runBuild'
import { useGameStore } from '../../runtime/gameStore'
import { runtime } from '../../runtime/registry'
import { AssetBoundary, StaticGltfModel, assetUrl } from '../AssetModels'
import { getWeaponVisual } from '../assetCatalog'
import { yawFromNegativeZForward } from '../direction'
import { applyHitstop } from '../hitstop'
import { TOON_PALETTE } from '../toonMaterials'
import {
  DEFAULT_WEAPON_HOVER,
  ORBIT_RADIUS,
  ORBIT_WORLD_Y,
  PLAYER_BODY_Y,
  REDUCED_MOTION_SCALE,
  WEAPON_SLOT_ANCHORS,
  advanceLag,
  approachAngle,
  orbitAngle,
  sampleBob,
  sampleDrift,
  sampleTilt,
  slotPhase,
  type WeaponLag,
} from './weaponHover'
import { findNearestEnemy } from './weaponTargeting'

function Graphite({ children }: { children: ReactNode }) {
  return <group>{children}</group>
}

function Barrel({ length = 0.62 }: { length?: number }) {
  return (
    <>
      <mesh castShadow position={[0, 0, -length / 2]}>
        <boxGeometry args={[0.13, 0.15, length]} />
        <meshStandardMaterial
          color="#151a1d"
          roughness={0.72}
          metalness={0.35}
        />
      </mesh>
      <mesh position={[0, 0, -length - 0.02]}>
        <boxGeometry args={[0.08, 0.08, 0.08]} />
        <meshBasicMaterial color={TOON_PALETTE.cyanLight} toneMapped={false} />
      </mesh>
    </>
  )
}

/**
 * Primitive stand-ins, and the fallback whenever a weapon GLB fails to load.
 * Every shape points its muzzle at local -Z, matching the game's facing
 * convention and whatever the build script bakes into the real models.
 */
function ProceduralWeapon({ id }: { id: RangedWeaponId }) {
  switch (id) {
    case 'micro-missiles':
      return (
        <Graphite>
          <mesh castShadow>
            <boxGeometry args={[0.42, 0.24, 0.48]} />
            <meshStandardMaterial
              color="#20272a"
              roughness={0.66}
              metalness={0.4}
            />
          </mesh>
          {[-0.12, 0.12].map((x) => (
            <mesh
              key={x}
              position={[x, 0, -0.27]}
              rotation={[Math.PI / 2, 0, 0]}
            >
              <cylinderGeometry args={[0.06, 0.06, 0.26, 8]} />
              <meshStandardMaterial color="#e6ecec" roughness={0.5} />
            </mesh>
          ))}
        </Graphite>
      )
    case 'scatter-cannon':
      return (
        <Graphite>
          <mesh castShadow position={[0, 0, -0.24]}>
            <boxGeometry args={[0.3, 0.24, 0.46]} />
            <meshStandardMaterial
              color="#252b2e"
              roughness={0.7}
              metalness={0.32}
            />
          </mesh>
          {[-0.09, 0, 0.09].map((x) => (
            <group key={x} position={[x, 0, -0.4]}>
              <Barrel length={0.35} />
            </group>
          ))}
        </Graphite>
      )
    case 'rail-lance':
      return (
        <Graphite>
          <Barrel length={1.04} />
          <mesh position={[0, 0.12, -0.44]}>
            <boxGeometry args={[0.25, 0.04, 0.72]} />
            <meshBasicMaterial
              color={TOON_PALETTE.cyanLight}
              toneMapped={false}
            />
          </mesh>
        </Graphite>
      )
    case 'arc-emitter':
      return (
        <Graphite>
          <mesh castShadow>
            <octahedronGeometry args={[0.28, 0]} />
            <meshStandardMaterial
              color="#e1e7e7"
              roughness={0.48}
              metalness={0.45}
            />
          </mesh>
          <mesh scale={0.54}>
            <octahedronGeometry args={[0.28, 0]} />
            <meshBasicMaterial
              color={TOON_PALETTE.cyanLight}
              toneMapped={false}
            />
          </mesh>
        </Graphite>
      )
    case 'orbit-drone':
      return (
        <Graphite>
          <mesh castShadow>
            <octahedronGeometry args={[0.22, 0]} />
            <meshStandardMaterial
              color="#202629"
              roughness={0.62}
              metalness={0.5}
            />
          </mesh>
          <group position={[0, 0, -0.2]}>
            <Barrel length={0.24} />
          </group>
        </Graphite>
      )
    default:
      return (
        <Graphite>
          <mesh castShadow position={[0, 0, -0.18]}>
            <boxGeometry args={[0.24, 0.2, 0.38]} />
            <meshStandardMaterial
              color="#e2e7e8"
              roughness={0.58}
              metalness={0.28}
            />
          </mesh>
          <Barrel />
        </Graphite>
      )
  }
}

/**
 * A weapon's body: the pack model when one has been built, the primitive
 * otherwise.
 *
 * The `model` check is what keeps this honest before the gun pack lands. With
 * no path there is no URL, so nothing is requested and nothing fails — the
 * error boundary below is a safety net for a corrupt or half-deployed file,
 * not the mechanism for "the asset does not exist yet".
 */
export function MountedWeapon({ id }: { id: RangedWeaponId }) {
  const visual = getWeaponVisual(id)
  // The stand-in is authored at its own size, so it carries its own scale.
  // The mount groups stay at 1 and `visual.scale` reads straight as the
  // weapon's length in world units.
  const fallback = (
    <group scale={visual.proceduralScale}>
      <ProceduralWeapon id={id} />
    </group>
  )
  if (!visual.model) return fallback
  return (
    <AssetBoundary resetKey={visual.model} fallback={fallback}>
      <StaticGltfModel
        url={assetUrl(visual.model)}
        rotation={[...visual.rotation]}
        scale={visual.scale}
        tint={visual.tint}
        tintStrength={visual.tintStrength}
        outline
        outlineDistance={visual.outlineDistance}
        name={`weapon-${id}`}
      />
    </AssetBoundary>
  )
}

/** How quickly a weapon swings around to the aim direction. */
const AIM_FOLLOW_RATE = 12
const FORMATION_FOLLOW_RATE = 10
const ORBIT_LOCAL_Y = ORBIT_WORLD_Y - PLAYER_BODY_Y
const ORBIT_DRONE_COUNT = 2

/**
 * All four ranged slots float beside the operative, including the deployment
 * weapon in slot zero. The old `slice(1)` hid that starter until a second
 * weapon was acquired even though it was already firing in gameplay.
 *
 * They are parented to the rigid body rather than to a hand bone, so nothing
 * here inherits the character animation — these read as field-held equipment,
 * not carried weapons. One `useFrame` drives the whole rig: the subtree under
 * `MountedWeapon` is torn down and rebuilt whenever an asset boundary swaps to
 * its fallback, so per-weapon frame loops would restart mid-motion.
 */
export function EquippedWeaponHardpoints() {
  const slots = useGameStore((state) => state.runBuild.weaponSlots)
  const reducedMotion = useGameStore((state) => state.settings.reducedMotion)
  // Explicit refs rather than one assigned inside a map — a shared ref would
  // leave only the last slot animated.
  const firstSlotRef = useRef<Group>(null)
  const secondSlotRef = useRef<Group>(null)
  const thirdSlotRef = useRef<Group>(null)
  const fourthSlotRef = useRef<Group>(null)
  const firstDroneRef = useRef<Group>(null)
  const secondDroneRef = useRef<Group>(null)
  const yaws = useRef<[number, number, number, number]>([0, 0, 0, 0])
  const orbitYaws = useRef<[number, number]>([0, 0])
  const formationYaw = useRef(0)
  const visualElapsed = useRef(0)
  const lags = useMemo<[WeaponLag, WeaponLag, WeaponLag, WeaponLag]>(
    () => [
      { x: 0, z: 0 },
      { x: 0, z: 0 },
      { x: 0, z: 0 },
      { x: 0, z: 0 },
    ],
    [],
  )
  const previousPlayer = useRef<Vector3 | null>(null)
  const playerDelta = useMemo(() => new Vector3(), [])
  const targetFacing = useMemo(() => new Vector3(), [])
  const aimFacing = useMemo(() => new Vector3(), [])
  const muzzlePositions = useMemo(
    () => [new Vector3(), new Vector3(), new Vector3(), new Vector3()],
    [],
  )
  // Published for the debug bridge only, so a browser test can measure what
  // actually reached the scene. Nothing in gameplay reads it.
  const rigRef = useRef<Group>(null)
  useEffect(() => {
    runtime.weaponRig = rigRef.current
    return () => {
      runtime.weaponRig = null
    }
  }, [])

  useFrame((_, rawDelta) => {
    const delta = applyHitstop(rawDelta)
    visualElapsed.current += delta
    const player = runtime.playerPosition
    // Seeded on the first frame, never before: a zero previous position would
    // read the spawn point as one frame of travel and fling the kit away.
    if (previousPlayer.current === null) {
      previousPlayer.current = new Vector3().copy(player)
    }
    playerDelta.subVectors(player, previousPlayer.current)
    previousPlayer.current.copy(player)

    const elapsed = visualElapsed.current
    const amplitude = reducedMotion ? REDUCED_MOTION_SCALE : 1
    const target = findNearestEnemy(player, runtime.enemies)
    runtime.weaponTargetId = target?.id ?? null
    if (target) {
      targetFacing.copy(target.position).sub(player).setY(0)
      if (targetFacing.lengthSq() > 0.0001) targetFacing.normalize()
      else targetFacing.copy(runtime.playerFacing)
    } else {
      targetFacing.copy(runtime.playerFacing)
    }
    formationYaw.current = approachAngle(
      formationYaw.current,
      yawFromNegativeZForward(targetFacing),
      delta,
      FORMATION_FOLLOW_RATE,
    )
    const formationSin = Math.sin(formationYaw.current)
    const formationCos = Math.cos(formationYaw.current)
    runtime.weaponMuzzles.clear()

    const groups = [
      firstSlotRef.current,
      secondSlotRef.current,
      thirdSlotRef.current,
      fourthSlotRef.current,
    ]
    for (let index = 0; index < groups.length; index += 1) {
      const group = groups[index]
      const lag = lags[index]
      advanceLag(lag, playerDelta.x, playerDelta.z, delta)
      if (!group) continue

      const phase = slotPhase(index)
      const anchor = WEAPON_SLOT_ANCHORS[index]
      const offsetX = anchor.x * formationCos + anchor.z * formationSin
      const offsetZ = -anchor.x * formationSin + anchor.z * formationCos
      group.position.set(
        offsetX + lag.x,
        anchor.y + sampleBob(DEFAULT_WEAPON_HOVER, elapsed, phase, amplitude),
        offsetZ + lag.z,
      )
      if (target) {
        aimFacing
          .set(
            target.position.x - (player.x + group.position.x),
            0,
            target.position.z - (player.z + group.position.z),
          )
          .normalize()
      } else {
        aimFacing.copy(runtime.playerFacing)
      }
      const aimYaw = yawFromNegativeZForward(aimFacing)
      yaws.current[index] = approachAngle(
        yaws.current[index],
        aimYaw,
        delta,
        AIM_FOLLOW_RATE,
      )
      group.rotation.set(
        sampleTilt(DEFAULT_WEAPON_HOVER, elapsed, phase, amplitude),
        yaws.current[index] +
          (target
            ? 0
            : sampleDrift(DEFAULT_WEAPON_HOVER, elapsed, phase, amplitude)),
        0,
      )
      const weapon = slots[index]
      if (weapon) {
        const id = weapon.weaponId as RangedWeaponId
        const muzzle = muzzlePositions[index]
        const muzzleOffset = getWeaponVisual(id).muzzleOffset
        muzzle.set(
          player.x +
            group.position.x -
            Math.sin(yaws.current[index]) * muzzleOffset,
          player.y + group.position.y,
          player.z +
            group.position.z -
            Math.cos(yaws.current[index]) * muzzleOffset,
        )
        runtime.weaponMuzzles.set(id, muzzle)
      }
    }

    const droneGroups = [firstDroneRef.current, secondDroneRef.current]
    for (let drone = 0; drone < droneGroups.length; drone += 1) {
      const group = droneGroups[drone]
      if (!group) continue
      const angle = orbitAngle(elapsed, drone, ORBIT_DRONE_COUNT)
      group.position.set(
        Math.cos(angle) * ORBIT_RADIUS,
        ORBIT_LOCAL_Y,
        Math.sin(angle) * ORBIT_RADIUS,
      )
      if (target) {
        aimFacing
          .set(
            target.position.x - (player.x + group.position.x),
            0,
            target.position.z - (player.z + group.position.z),
          )
          .normalize()
      } else {
        aimFacing.copy(runtime.playerFacing)
      }
      orbitYaws.current[drone] = approachAngle(
        orbitYaws.current[drone],
        yawFromNegativeZForward(aimFacing),
        delta,
        AIM_FOLLOW_RATE,
      )
      group.rotation.set(0, orbitYaws.current[drone], 0)
    }
  })

  const slotRefs = [firstSlotRef, secondSlotRef, thirdSlotRef, fourthSlotRef]

  return (
    <group name="equipped-weapon-hardpoints" ref={rigRef}>
      {slots.map((weapon, index) => {
        if (!weapon) return null
        const id = weapon.weaponId as RangedWeaponId
        if (id === 'orbit-drone') {
          return (
            <group key={`${id}-${index}`}>
              {Array.from({ length: ORBIT_DRONE_COUNT }, (_, drone) => {
                // Ring positions and the drone's own facing are derived from
                // the same constants PlayerProjectileSystem fires from, so the
                // bolts leave the model instead of the air beside it.
                const offset = (drone / ORBIT_DRONE_COUNT) * Math.PI * 2
                return (
                  <group
                    ref={drone === 0 ? firstDroneRef : secondDroneRef}
                    key={drone}
                    position={[
                      Math.cos(offset) * ORBIT_RADIUS,
                      0,
                      Math.sin(offset) * ORBIT_RADIUS,
                    ]}
                  >
                    <MountedWeapon id={id} />
                  </group>
                )
              })}
            </group>
          )
        }
        return (
          <group
            ref={slotRefs[index]}
            key={`${id}-${index}`}
            position={[
              WEAPON_SLOT_ANCHORS[index].x,
              WEAPON_SLOT_ANCHORS[index].y,
              WEAPON_SLOT_ANCHORS[index].z,
            ]}
          >
            <MountedWeapon id={id} />
          </group>
        )
      })}
    </group>
  )
}
