import { type Camera, Vector3 } from 'three'

export interface OperatorFeedViewportSize {
  readonly width: number
  readonly height: number
}

export interface OperatorFeedProjectionState {
  element: HTMLElement | null
  initialized: boolean
  visible: boolean
  viewportWidth: number
  viewportHeight: number
  screenX: number
  screenY: number
  renderedX: number
  renderedY: number
}

const PLAYER_FEED_ANCHOR_Y = 0.18
const SCREEN_DEAD_ZONE_PX = 0.35
const SCREEN_SMOOTHING_RATE = 22
const SCREEN_QUANTIZATION_PX = 0.5

export function createOperatorFeedProjectionState(): OperatorFeedProjectionState {
  return {
    element: null,
    initialized: false,
    visible: false,
    viewportWidth: 0,
    viewportHeight: 0,
    screenX: 0,
    screenY: 0,
    renderedX: Number.NaN,
    renderedY: Number.NaN,
  }
}

export function disconnectOperatorFeedProjection(
  state: OperatorFeedProjectionState,
): void {
  if (state.element?.dataset.visible === 'true') {
    state.element.dataset.visible = 'false'
  }
  state.element = null
  state.initialized = false
  state.visible = false
  state.viewportWidth = 0
  state.viewportHeight = 0
  state.renderedX = Number.NaN
  state.renderedY = Number.NaN
}

function quantizeScreenPixel(value: number): number {
  return Math.round(value / SCREEN_QUANTIZATION_PX) * SCREEN_QUANTIZATION_PX
}

function setVisibility(element: HTMLElement, visible: boolean): void {
  const value = visible ? 'true' : 'false'
  if (element.dataset.visible !== value) element.dataset.visible = value
}

/**
 * Projects the operative after the gameplay camera has settled for the frame.
 *
 * The target is a DOM overlay, so the result stays in CSS pixels. Only a
 * compositor transform and an occasional visibility attribute are written;
 * no React state or layout reads enter the render loop.
 */
export function updateOperatorFeedProjection(
  element: HTMLElement,
  camera: Camera,
  playerPosition: Readonly<{ x: number; y: number; z: number }>,
  viewport: OperatorFeedViewportSize,
  projection: Vector3,
  state: OperatorFeedProjectionState,
  deltaSeconds: number,
): void {
  const elementChanged = state.element !== element
  if (elementChanged) {
    if (state.element?.dataset.visible === 'true') {
      state.element.dataset.visible = 'false'
    }
    state.element = element
    state.initialized = false
    state.visible = false
    state.renderedX = Number.NaN
    state.renderedY = Number.NaN
  }

  const viewportChanged =
    state.viewportWidth !== viewport.width ||
    state.viewportHeight !== viewport.height
  state.viewportWidth = viewport.width
  state.viewportHeight = viewport.height

  camera.updateMatrixWorld()
  projection
    .set(
      playerPosition.x,
      playerPosition.y + PLAYER_FEED_ANCHOR_Y,
      playerPosition.z,
    )
    .project(camera)

  const visible =
    viewport.width > 0 &&
    viewport.height > 0 &&
    Number.isFinite(projection.x) &&
    Number.isFinite(projection.y) &&
    Number.isFinite(projection.z) &&
    projection.z >= -1 &&
    projection.z <= 1 &&
    projection.x >= -1.15 &&
    projection.x <= 1.15 &&
    projection.y >= -1.15 &&
    projection.y <= 1.15
  setVisibility(element, visible)
  state.visible = visible
  if (!visible) {
    // Do not interpolate from an obsolete offscreen coordinate. The first
    // visible frame will snap to the operative before smoothing resumes.
    state.initialized = false
    return
  }

  const targetX = (projection.x + 1) * 0.5 * viewport.width
  const targetY = (1 - projection.y) * 0.5 * viewport.height
  const shouldSnap = !state.initialized || elementChanged || viewportChanged

  if (shouldSnap) {
    state.screenX = targetX
    state.screenY = targetY
    state.initialized = true
  } else {
    const offsetX = targetX - state.screenX
    const offsetY = targetY - state.screenY
    if (Math.hypot(offsetX, offsetY) > SCREEN_DEAD_ZONE_PX) {
      const safeDelta = Math.min(0.1, Math.max(0, deltaSeconds))
      const blend = 1 - Math.exp(-SCREEN_SMOOTHING_RATE * safeDelta)
      state.screenX += offsetX * blend
      state.screenY += offsetY * blend
    }
  }

  const renderedX = quantizeScreenPixel(state.screenX)
  const renderedY = quantizeScreenPixel(state.screenY)
  if (renderedX === state.renderedX && renderedY === state.renderedY) return

  state.renderedX = renderedX
  state.renderedY = renderedY
  element.style.transform =
    `translate3d(${renderedX}px, ${renderedY}px, 0) ` + 'translate(-50%, -50%)'
}
